window.SOCIAL_DATA=window.SOCIAL_DATA||[];window.SOCIAL_DATA.push({"id": "geo-4", "subject": "地理", "chapter": "第四章", "title": "中國的發展與全球關連", "total": 373, "levels": {"必考": 38, "常考": 19}, "mapname": {"g4-map-region": "中國四大經濟區分布圖", "g4-map-sez": "中國經濟特區分布圖", "g4-map-belt": "中國一帶一路路線示意圖", "g4-map-ind": "中國三級產業產值比例統計圖", "g4-map-emp": "中國三級產業就業人口比例統計圖", "g4-map-mineral": "中國礦產分布圖", "g4-map-rail": "中國鐵路分布圖", "g4-map-rcep": "區域全面經濟夥伴協定（RCEP）簽署國"}, "concepts": [{"id": "e5", "name": "中國四大經濟區與區域均衡對策", "n": 86, "level": "必考", "card": {"說明": "改革開放政策率先於沿海推行，導致「東強西弱」、「沿海與內陸、都市與鄉村」的貧富與發展差距日益懸殊，每年春節引發全球規模最大的返鄉遷徙「春運」（東南熱、西北冷）。為解決發展不均問題，中國政府將全國劃分為「東部地區」、「中部地區」、「東北地區」與「西部地區」四大經濟區，因地制宜擬定不同的振興策略以促進區域協調發展。", "關鍵名詞": "<b>四大經濟區</b>——中國政府依地理位置、資源條件與經濟發展水平，將全國劃分為東部、中部、東北與西部四個宏觀政策調控區域。", "因果／影響": "引導東部產業向中西部轉移，推動西電東送、西氣東輸等重大資源調配工程，逐步活化內陸經濟。", "出處": "自修第 60 頁／講義第 46–47 頁、試題寶典第 29 頁。", "標示": "自修重要性評估 ★★★★、會考高頻整合題。"}, "imgs": ["g4-map-region", "g4-map-rail"], "clusters": [{"t": "區域發展不均（春運、外資、薪資、都市化）", "n": 38, "ids": ["g4-25", "g4-26", "g4-30", "g4-36", "g4-41", "g4-49", "g4-68", "g4-71", "g4-102", "g4-114", "g4-161", "g4-167", "g4-170", "g4-186", "g4-196", "g4-203", "g4-217", "g4-219", "g4-240", "g4-243", "g4-247", "g4-257", "g4-261", "g4-264", "g4-274", "g4-275", "g4-281", "g4-307", "g4-309", "g4-310", "g4-312", "g4-320", "g4-326", "g4-327", "g4-351", "g4-368", "g4-372", "g4-373"]}, {"t": "交通建設與鐵路分布", "n": 28, "ids": ["g4-5", "g4-6", "g4-19", "g4-37", "g4-39", "g4-80", "g4-82", "g4-90", "g4-94", "g4-101", "g4-109", "g4-125", "g4-133", "g4-154", "g4-204", "g4-207", "g4-226", "g4-234", "g4-239", "g4-278", "g4-290", "g4-291", "g4-300", "g4-315", "g4-324", "g4-354", "g4-355", "g4-359"]}, {"t": "東北振興：礦產枯竭、設備老舊", "n": 11, "ids": ["g4-28", "g4-66", "g4-74", "g4-77", "g4-88", "g4-89", "g4-136", "g4-185", "g4-208", "g4-314", "g4-319"]}, {"t": "中部崛起：工資較低、承東啟西", "n": 2, "ids": ["g4-143", "g4-245"]}, {"t": "西部大開發：資源豐富、交通不便", "n": 3, "ids": ["g4-20", "g4-163", "g4-284"]}, {"t": "東部率先發展與其他", "n": 4, "ids": ["g4-63", "g4-87", "g4-137", "g4-279"]}]}, {"id": "e3", "name": "經濟特區的設立與「世界工廠」崛起", "n": 76, "level": "必考", "card": {"說明": "1978 年底中國推行「經濟改革開放」，先後在東南沿海設立深圳、珠海、汕頭、廈門與海南 5 個「經濟特區」。這些特區憑藉優越的海運交通、低廉的工資與土地成本、優惠稅制及鄰近港澳臺僑資的優勢，吸引大量外資設廠，早期以成衣、玩具等勞力密集加工出口業為主。隨著基礎建設完善與技術升級，吸引電腦電子、汽車等跨國企業進駐，產銷規模擴及全球，使中國贏得「世界工廠」的稱號；2010 年更在西北內陸新增「喀什經濟特區」，作為拓展中亞邊境貿易的陸上樞紐。", "關鍵名詞": "• <b>經濟特區</b>：國家劃定特定區域，實施特殊稅賦減免與外資優惠政策，以吸引外資、引進先進技術與管理經驗的開放區域。<br>• <b>世界工廠</b>：形容一國製造業生產量龐大、產業鏈完整，製品外銷流通全球市場的地位。", "因果／影響": "帶動中國經濟躍升為全球第二大經濟體，但工廠高度集中於東南沿海，亦造成區域經濟發展嚴重失衡。", "出處": "自修第 59 頁／講義第 46 頁、試題寶典第 28 頁。", "標示": "講義「必考重點」、自修重要性評估 ★★★★。"}, "imgs": ["g4-map-sez"], "clusters": [{"t": "世界工廠：勞力便宜、產品價格低", "n": 25, "ids": ["g4-3", "g4-18", "g4-31", "g4-32", "g4-33", "g4-34", "g4-55", "g4-73", "g4-92", "g4-111", "g4-126", "g4-151", "g4-152", "g4-156", "g4-172", "g4-178", "g4-210", "g4-211", "g4-212", "g4-229", "g4-263", "g4-298", "g4-308", "g4-321", "g4-342"]}, {"t": "經濟特區的位置（深圳、喀什…）", "n": 28, "ids": ["g4-12", "g4-27", "g4-54", "g4-76", "g4-78", "g4-81", "g4-99", "g4-100", "g4-107", "g4-120", "g4-124", "g4-128", "g4-146", "g4-150", "g4-195", "g4-205", "g4-216", "g4-230", "g4-235", "g4-248", "g4-249", "g4-265", "g4-267", "g4-292", "g4-311", "g4-317", "g4-325", "g4-328"]}, {"t": "設立特區的條件：交通、勞力、土地", "n": 13, "ids": ["g4-83", "g4-108", "g4-116", "g4-130", "g4-158", "g4-168", "g4-184", "g4-271", "g4-316", "g4-318", "g4-365", "g4-366", "g4-371"]}, {"t": "改革開放吸引外資、技術升級", "n": 10, "ids": ["g4-16", "g4-29", "g4-59", "g4-61", "g4-86", "g4-103", "g4-144", "g4-198", "g4-322", "g4-360"]}]}, {"id": "e7", "name": "「一帶一路」倡議（絲綢之路經濟帶與海上絲綢之路）", "n": 48, "level": "必考", "card": {"說明": "中國於 2013 年提出「一帶一路」跨國經濟合作戰略，分為陸路「絲綢之路經濟帶」（一帶）與海路「21 世紀海上絲綢之路」（一路）。「一帶」由中國西北地區（如新疆經阿拉山口、霍爾果斯）貫穿中亞直通歐洲；「一路」則承襲歷史海上絲路，串聯東南沿海港口、麻六甲海峽、印度洋、非洲東岸直達歐洲。其核心目的在於協助沿線國家建設交通港口與能源網絡，藉此取得穩定海外能源供給、開拓國際貿易市場，並消化國內過剩的鋼鐵與水泥等工業產能。", "關鍵名詞": "• <b>絲綢之路經濟帶（一帶）</b>：從中國經中亞延伸至歐洲的陸上跨國經貿合作走廊。<br>• <b>21 世紀海上絲綢之路（一路）</b>：從中國沿海港口經南海、印度洋、非洲通往歐洲的海上經貿航線合作網絡。", "因果／影響": "促進了中歐班列運行及沿線國家的基礎設施更新，但也引發沿線發展中國家深陷「債務陷阱」與地緣政治主權爭端。", "出處": "自修第 61 頁／講義第 48–49 頁、試題寶典第 29 頁。", "標示": "講義「會考精熟重點」、自修重要性評估 ★★★★。"}, "imgs": ["g4-map-belt"], "clusters": [{"t": "一帶陸路：西安→新疆→中亞→歐洲", "n": 26, "ids": ["g4-9", "g4-21", "g4-38", "g4-67", "g4-95", "g4-97", "g4-119", "g4-140", "g4-162", "g4-188", "g4-189", "g4-200", "g4-201", "g4-213", "g4-218", "g4-222", "g4-227", "g4-250", "g4-251", "g4-252", "g4-287", "g4-337", "g4-338", "g4-346", "g4-369", "g4-370"]}, {"t": "一路海路：鄭和航線、經東南亞到非洲", "n": 7, "ids": ["g4-145", "g4-215", "g4-221", "g4-258", "g4-299", "g4-339", "g4-340"]}, {"t": "中巴經濟走廊", "n": 2, "ids": ["g4-220", "g4-266"]}, {"t": "目的：消化產能、能源、市場", "n": 9, "ids": ["g4-22", "g4-64", "g4-110", "g4-121", "g4-142", "g4-228", "g4-293", "g4-294", "g4-336"]}, {"t": "一帶一路路線辨識", "n": 4, "ids": ["g4-93", "g4-118", "g4-288", "g4-335"]}]}, {"id": "e1", "name": "農業面臨的挑戰與現代轉型（專業化生產、生態農業）", "n": 48, "level": "必考", "card": {"說明": "中國受限於「山多平原少」的自然限制，加上降水量與人口分布極不均勻，先天農耕條件有限。隨著工商業快速發展與城鎮化擴張，大量農地轉作建地或工廠，導致第一級產業就業人口逐年下降，人均可耕地面積僅約 0.08 公頃，遠低於世界平均水準。面對人口龐大且糧食需求持續攀升的壓力，中國農業積極推動因地制宜的「專業化生產」（如內蒙古乳牛飼養區、東北平原大規模機械化糧食區），並運用農業科技發展減農藥、重土壤保育的「生態農業」以追求永續發展。", "關鍵名詞": "• <b>專業化生產</b>：農業經營因地制宜，集中生產當地最具自然環境與區位優勢的單一農產品，形成規模化生產區。<br>• <b>生態農業</b>：運用農業科技，減少使用化學肥料與農藥，採取生物防治病蟲害，兼顧生態環境維護與糧食產量平衡的永續生產模式。", "因果／影響": "提高農產效能與糧食自給率，但在轉型過程中仍面臨北方缺水限制，促成跨流域的「南水北調」等大型水利工程建設。", "出處": "自修第 57–58 頁／講義第 44 頁、試題寶典第 28 頁。", "標示": "講義「重點分析」、自修重要性評估 ★★★★、會考精熟題。"}, "imgs": ["g4-map-emp"], "clusters": [{"t": "人均可耕地低：農地轉作他用、人口多", "n": 17, "ids": ["g4-42", "g4-51", "g4-65", "g4-91", "g4-104", "g4-139", "g4-180", "g4-181", "g4-192", "g4-302", "g4-304", "g4-305", "g4-306", "g4-329", "g4-347", "g4-357", "g4-364"]}, {"t": "專業生產區（內蒙古酪農、東北糧食）", "n": 14, "ids": ["g4-50", "g4-113", "g4-129", "g4-132", "g4-138", "g4-182", "g4-206", "g4-209", "g4-236", "g4-254", "g4-268", "g4-269", "g4-344", "g4-362"]}, {"t": "生態農業、科技化農業", "n": 8, "ids": ["g4-10", "g4-15", "g4-48", "g4-56", "g4-153", "g4-173", "g4-256", "g4-345"]}, {"t": "三級產業變化", "n": 6, "ids": ["g4-62", "g4-127", "g4-176", "g4-179", "g4-323", "g4-330"]}, {"t": "農業面臨的挑戰", "n": 3, "ids": ["g4-191", "g4-193", "g4-282"]}]}, {"id": "e6", "name": "跨國投資擴張與區域經濟整合（RCEP）", "n": 36, "level": "常考", "card": {"說明": "在累積龐大外匯儲備與資本後，中國政府轉而鼓勵本國具實力企業展開海外投資與跨國併購，藉此取得海外關鍵礦產資源、先進核心技術及歐美行銷通路（如吉利收購瑞典富豪汽車 Volvo、美的集團收購德國庫卡機器人等）。同時，中國積極參與多邊自由貿易協定，於 2020 年正式簽署、2022 年生效的「區域全面經濟夥伴協定（RCEP）」，涵蓋東協 10 國與中、日、韓、澳、紐共 15 國，占全球約 30% GDP 與人口，享有降低關稅與通關便捷等經貿優勢。", "關鍵名詞": "<b>區域全面經濟夥伴協定（RCEP）</b>——由東協發起並由東亞與大洋洲 15 個國家組成的自由貿易協定，為目前全球涵蓋人口最多、經濟量體最大的自由貿易區。", "因果／影響": "大幅擴張中國的全球經貿影響力，促成亞太區域供應鏈更深度的整合與相互依賴。", "出處": "自修第 61–62 頁／講義第 48 頁、試題寶典第 29 頁。", "標示": "講義「最新重點」、時事素養必考題。"}, "imgs": ["g4-map-rcep"], "clusters": [{"t": "RCEP：關稅減免、亞太 15 國", "n": 17, "ids": ["g4-7", "g4-14", "g4-43", "g4-44", "g4-45", "g4-46", "g4-60", "g4-84", "g4-122", "g4-123", "g4-134", "g4-214", "g4-241", "g4-277", "g4-331", "g4-333", "g4-367"]}, {"t": "對外投資：資源、技術、歐美市場", "n": 11, "ids": ["g4-13", "g4-70", "g4-112", "g4-141", "g4-190", "g4-242", "g4-260", "g4-273", "g4-285", "g4-313", "g4-350"]}, {"t": "貿易總額世界第一", "n": 8, "ids": ["g4-2", "g4-23", "g4-165", "g4-174", "g4-202", "g4-232", "g4-286", "g4-332"]}]}, {"id": "e4", "name": "內需成長與「世界市場」角色轉變", "n": 30, "level": "常考", "card": {"說明": "改革開放帶動中國人均所得與消費能力顯著提升，國內形成龐大的消費人口基數。中國不僅是製造出口大國，更吸引全球知名精品、汽車、餐飲與高科技品牌爭相進駐設立旗艦店與研發中心；加上電子商務與物流網迅速普及，2022 年中國消費支出占全球約 13%，已躍居僅次於美國的全球第二大消費市場，扮演牽動全球經貿景氣的「世界市場」。", "關鍵名詞": "<b>世界市場</b>——指一國因國民所得增加與消費力大增，具備龐大且持續擴張的商品與服務消化能力，成為全球跨國企業主要銷售目標的消費中心。", "因果／影響": "跨國企業對中國市場依賴加深；同時中國本土品牌（如電動車、手機）亦藉龐大國內市場迅速壯大並進一步拓展海外。", "出處": "自修第 59 頁／講義第 46 頁、試題寶典第 28 頁。", "標示": "講義「重點分析」、會考生活情境題。"}, "imgs": ["g4-map-ind"], "clusters": [{"t": "人口多＋所得提高＝世界市場", "n": 22, "ids": ["g4-1", "g4-11", "g4-47", "g4-53", "g4-75", "g4-135", "g4-147", "g4-169", "g4-177", "g4-199", "g4-224", "g4-238", "g4-244", "g4-262", "g4-270", "g4-272", "g4-280", "g4-296", "g4-297", "g4-334", "g4-341", "g4-353"]}, {"t": "外資轉投資服務業", "n": 2, "ids": ["g4-117", "g4-155"]}, {"t": "GDP 世界第二", "n": 6, "ids": ["g4-105", "g4-160", "g4-187", "g4-197", "g4-255", "g4-361"]}]}, {"id": "e9", "name": "中國當前經濟挑戰（生產成本上漲、貿易戰與科技封鎖）", "n": 20, "level": "常考", "card": {"說明": "近年中國面臨內外多重經濟挑戰。對內而言，隨著人口紅利消退，國內基本工資與土地成本逐年飆升，環保法規趨嚴，導致許多傳統勞力密集工廠外移至東南亞或內陸省分；對外而言，自 2018 年起美中貿易摩擦升溫，美國對大量中國進口商品加徵高額關稅，並在高階晶片、半導體關鍵技術與精密製造設備上實施出口限制與科技封鎖，促使外資企業調整全球供應鏈布局，加速分散「中國製造」風險。", "關鍵名詞": "<b>美中貿易摩擦</b>——2018 年起美國與中國之間因貿易逆差、智慧財產權與高科技主導權競爭，互相加徵懲罰性關稅及實施科技禁令引發的經貿對抗。", "因果／影響": "迫使中國加速發展自主科技創新與核心零組件自製，並促使跨國企業推行「中國加一」多元供應鏈策略。", "出處": "自修第 61 頁／講義第 49 頁、試題寶典第 29 頁。", "標示": "講義「會考最新趨勢」、時事素養必考題。"}, "imgs": [], "clusters": [{"t": "工資上漲，工廠外移", "n": 16, "ids": ["g4-17", "g4-35", "g4-40", "g4-58", "g4-96", "g4-157", "g4-159", "g4-171", "g4-231", "g4-233", "g4-237", "g4-283", "g4-303", "g4-343", "g4-348", "g4-363"]}, {"t": "美中貿易戰", "n": 3, "ids": ["g4-52", "g4-85", "g4-225"]}, {"t": "產業升級、科技自主", "n": 1, "ids": ["g4-24"]}]}, {"id": "e2", "name": "工業區位與南北工業發展差異（重工業 vs. 輕工業）", "n": 16, "level": "一般", "card": {"說明": "傳統工業發展高度依賴「原料區位」，礦產資源的空間分布直接決定了中國早期的工業結構。北方地區因富含煤、鐵、石油等重要礦產，成為中國發展鋼鐵、機械、石油化學等「重工業」的核心基地；南方地區礦產資源相對匱乏，昔日則憑藉豐富農產原料與密集人口，以紡織、食品加工等「輕工業」為主。", "關鍵名詞": "<b>原料區位</b>——工廠選擇設立在原料產地附近，以節省龐大且笨重的原料運輸成本之工業區位型態。", "因果／影響": "奠定了東北與華北作為早期重工業搖籃的格局，但也導致日後東北老工業區面臨礦產枯竭與設備老舊的轉型陣痛。", "出處": "自修第 58 頁／講義第 45 頁、試題寶典第 28 頁。", "標示": "講義「重點分析」、基礎必考題。"}, "imgs": ["g4-map-mineral"], "clusters": [{"t": "北重南輕：原料區位", "n": 13, "ids": ["g4-4", "g4-57", "g4-69", "g4-106", "g4-148", "g4-164", "g4-175", "g4-183", "g4-194", "g4-246", "g4-253", "g4-349", "g4-352"]}, {"t": "礦產與工業分布", "n": 3, "ids": ["g4-79", "g4-131", "g4-259"]}]}, {"id": "e8", "name": "「一帶一路」潛藏隱憂（債務陷阱與主權爭議）", "n": 13, "level": "一般", "card": {"說明": "參與「一帶一路」的沿線國家多屬經濟實力較弱、財政困難的發展中國家，當其向中國巨額貸款興建鐵路、港口等基建後，若經濟效益未如預期，往往面臨無法如期償還借款的龐大財務風險。部分國家為化解債務，被迫將重要國土基礎設施的經營權長期租借給中國（如斯里蘭卡將漢班托塔港租借 99 年），引起受援國民眾對國家主權受損、利益被操控的強烈質疑，進而引發政治反彈與部分工程計畫中止。", "關鍵名詞": "<b>債務陷阱</b>——指借款國因過度舉債進行基礎建設，最終無力償還債務，被迫在經濟資產、戰略要地或國家主權上讓步的困局。", "因果／影響": "引發國際社會對中國地緣政治擴張的高度戒心，使後續推動計画面臨諸多變數與外交阻力。", "出處": "自修第 61 頁／講義第 49 頁。", "標示": "講義「重點分析」、時事題庫常考題。"}, "imgs": ["g4-map-belt"], "clusters": [{"t": "債務陷阱、出租港口", "n": 12, "ids": ["g4-72", "g4-98", "g4-115", "g4-149", "g4-166", "g4-223", "g4-276", "g4-289", "g4-295", "g4-301", "g4-356", "g4-358"]}, {"t": "主權與利益糾紛", "n": 1, "ids": ["g4-8"]}]}], "questions": [{"id": "g4-1", "no": 1, "c": "e4", "src": "114上翰林社會2上A卷 卷5 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國被稱為「世界工廠」到「世界市場」，主要與下列哪項因素有密切關係？", "o": ["土地遼闊", "氣候複雜", "人口眾多", "教育發達"], "a": 2, "e": "中國人口眾多，勞工多、工資低，吸引外商設廠成為世界工廠；人民所得提高後，龐大人口又成為世界市場。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-2", "no": 2, "c": "e6", "src": "114上翰林社會2上A卷 卷5 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "貿易總額為一國在一定期間內出口總額和進口總額的合計值。圖(一)為 2020 年世界前五大貿易總額國家，由圖中判斷，下列哪一敘述最能做為該圖的佐證？", "o": ["中國在國際的經濟地位提升", "中國的人口增加率持續上升", "近年美商將工廠從東南亞遷移至中國", "中國對美國的部分進口商品減免關稅"], "a": 0, "e": "中國貿易總額世界第一，代表中國在國際的經濟地位提升。", "rep": false, "img": "g4-q2", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-3", "no": 3, "c": "e3", "src": "114上翰林社會2上A卷 卷5 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "「非洲肯亞的『中國廣場』超市開幕，這家超市以大量且低廉的價格出售從中國進口的各種商品，包括家具、衣物等，開幕兩週就賺超過了 15 萬美元，而引發當地商家抗議。」上述與中國的何項特色最相關？", "o": ["機構資源豐富", "邊境貿易活絡", "國內消費市場龐大", "勞工多且工資低廉"], "a": 3, "e": "中國勞工多、工資低，生產成本低，商品才能以低價大量外銷。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-4", "no": 4, "c": "e2", "src": "114上翰林社會2上A卷 卷5 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "昔日中國北部以重工業為主，南部以輕工業為主。這與下列哪一項工業區位要素的關係最密切？", "o": ["原料", "勞工", "交通", "資金"], "a": 0, "e": "中國的煤、鐵、石油主要分布在北部，所以北重工、南輕工，和原料分布有關。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-mineral"], "chk": ""}, {"id": "g4-5", "no": 5, "c": "e5", "src": "114上翰林社會2上A卷 卷5 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國此經濟區面臨海洋，有綿長海岸線和眾多港口，是中國最早改革開放的地方，有利於與多國進行技術交流，其經濟生產總額占全國總量達 60% 以上。上述是指中國哪一經濟區的發展？", "o": ["東北地區", "東部地區", "中部地區", "西部地區"], "a": 1, "e": "面海、港口多、最早改革開放、經濟產值最高，是東部地區。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-region"], "chk": ""}, {"id": "g4-6", "no": 6, "c": "e5", "src": "114上翰林社會2上A卷 卷5 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國各地的交通運輸特色不同，而鐵路、公路分布密集的地區通常具有下列哪一項特色？", "o": ["環境負載力低", "氣候乾燥少雨", "水力蘊藏豐富", "工商業較發達"], "a": 3, "e": "鐵公路密集的地方多是工商業發達的東部。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-rail"], "chk": ""}, {"id": "g4-7", "no": 7, "c": "e6", "src": "114上翰林社會2上A卷 卷5 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(二)中深色處為某貿易協定的簽署國家分布圖，該協定最有可能為下列何者？", "o": ["東南亞國家協會", "北美自由貿易協定", "亞太經濟合作會議", "區域全面經濟夥伴協定"], "a": 3, "e": "深色處包含東協、中、日、韓、澳、紐，是區域全面經濟夥伴協定（RCEP）。", "rep": true, "img": "g4-q7", "imgnote": "", "fh": "", "maps": ["g4-map-rcep"], "chk": ""}, {"id": "g4-8", "no": 8, "c": "e8", "src": "114上翰林社會2上A卷 卷5 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國透過一帶一路政策協助各參與國的基礎建設，並增強彼此經濟連結，但也造成部分負面影響，下列何者最有可能是為一帶一路政策所造成？", "o": ["交通易運作下降", "製造業比例偏高", "主權與利益糾紛", "各國以關稅報復"], "a": 2, "e": "部分國家借款建設後無力償還，只好出租港口，引發主權與利益糾紛。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-9", "no": 9, "c": "e7", "src": "114上翰林社會2上A卷 卷5 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "「中歐班列」從中國出發，以歐洲為終點，其中一條是經中亞、俄羅斯到達波蘭；另一條是經中亞、西亞到達波斯灣和地中海沿岸各國。可知中歐班列的開通與下列哪一項政策最有關係？", "o": ["改革開放", "一帶一路", "西部開發", "中部崛起"], "a": 1, "e": "中歐班列經中亞通往歐洲，是一帶一路（絲綢之路經濟帶）的一部分。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-belt"], "chk": ""}, {"id": "g4-10", "no": 10, "c": "e1", "src": "114上翰林社會2上A卷 卷5 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國山東省業者利用太陽能捕蟲燈抓捕農田害蟲，並可用於分析蟲害，提升農產品質。上述作法最能反映哪一項中國現代農業轉型的方向？", "o": ["擴大農地面積，增加糧食產量", "形成生產專區，提高生產效率", "限制農村發展，維持傳統農業模式", "減少使用農藥，兼顧環境與農產量"], "a": 3, "e": "用捕蟲燈取代農藥，兼顧環境與產量，是生態農業。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-11", "no": 11, "c": "e4", "src": "114上翰林社會2上A卷 卷5 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "「2016 年到 2020 年中國的消費增量高達 1.8 萬億美元，這個增量相當於英國全年度的消費市場規模。也就是說中國五年的消費增量相當於英國一年的消費總量。」上述內容最符合下列哪一個標籤？", "o": ["一帶一路", "世界市場", "世界工廠", "改革開放"], "a": 1, "e": "消費增量龐大，代表中國是消費力強大的世界市場。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-12", "no": 12, "c": "e3", "src": "114上翰林社會2上A卷 卷5 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "位於新疆的喀什是中國西部經濟特區的都市，中國政府期望將喀什打造成向西出口的加工基地，可出口紡織品、食品加工品至塔吉克等鄰國。可知喀什在中國所扮演的經濟角色，與下列哪個都市較為雷同？", "o": ["北京", "上海", "武漢", "深圳"], "a": 3, "e": "喀什和深圳一樣是經濟特區，喀什面向中亞發展邊境貿易。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-sez"], "chk": ""}, {"id": "g4-13", "no": 13, "c": "e6", "src": "114上翰林社會2上A卷 卷5 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國企業擁有龐大的財力，並以此併購各國具有指標性、高技術性的公司。透過併購可以讓中國企業得到哪項優勢？", "o": ["成為世界工廠", "吸引外商投資", "提高國內需求", "獲取產業技術"], "a": 3, "e": "透過併購外國公司，可以快速獲得技術、進入歐美市場。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-14", "no": 14, "c": "e6", "src": "114上翰林社會2上A卷 卷5 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國為擴大其經濟版圖，積極與各國簽訂自由貿易協定，如 2022 年 1 月 1 日起正式生效實施的 RCEP。參與 RCEP 的國家有下列何項優勢？", "o": ["享有關稅減免", "提高進口商品價格", "協助他國基礎建設", "避免參與國的債務"], "a": 0, "e": "參與 RCEP 的國家享有關稅減免、降低進出口限制。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-15", "no": 15, "c": "e1", "src": "114上翰林社會2上A卷 卷5 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(三)為中國單位面積糧食產量統計圖，該圖的變化趨勢與下列何者最有關聯？", "o": ["農田規模小而採集約化耕作", "壯年人力大量返鄉投入農業", "透過機械補助並研發新的農業技術", "糧食作物生產面積的比例逐年增加"], "a": 2, "e": "單位面積產量提高，是因為機械補助與農業技術研發。", "rep": false, "img": "g4-q15", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-16", "no": 16, "c": "e3", "src": "114上翰林社會2上A卷 卷5 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(四)為中國空氣污染 PM2.5 示意圖，其中最嚴重地區是因為大量的開發行為，使懸浮微粒持續不減。上述情況最可能為下列何者？", "o": ["大規模開採陸上礦產", "勞力密集型產業進駐", "沿海地區多交通樞紐", "老舊重工業工廠重建"], "a": 0, "e": "PM2.5 最嚴重地區在新疆一帶，屬西部大開發推動區，大規模開採與加工礦產造成空汙。", "rep": false, "img": "g4-q16", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-17", "no": 17, "c": "e9", "src": "114上翰林社會2上A卷 卷5 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國曾經因世界工廠的優勢，成為手機供應鏈核心，但隨著經濟情勢轉變，預計 2025 年將有四分之一的產品移往印度生產。除了國際局勢關係外，造成上述產地轉移的主因最可能為下列何者？", "o": ["平均薪資提升", "礦產資源缺乏", "水力資源不足", "基礎建設落後"], "a": 0, "e": "中國工資逐年上漲，生產成本提高，工廠移往工資較低的印度等地。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-18", "no": 18, "c": "e3", "src": "114上翰林社會2上A卷 卷5 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國自改革開放後，製造業發展迅速，電子商品、服飾上的「中國製造」成為家喻戶曉的標籤。上述現象與中國具有何項特色有關？", "o": ["勞力成本低廉", "發展高科技產業", "專注農業發展", "開放市場零關稅"], "a": 0, "e": "中國勞力成本低廉，產品便宜，「中國製造」遍布全球。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-19", "no": 19, "c": "e5", "src": "114上翰林社會2上A卷 卷5 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國湖北近年來積極建構高鐵網絡，圖(五)為該省的交通運輸路線圖。當地推動鐵路建設是為了達成下列哪一目標？", "o": ["強化對外的海陸空位置優勢", "連接沿海與內陸的交通樞紐", "推動重化工業轉型提升效能", "大量輸出能源資源至東部"], "a": 1, "e": "湖北位在中部，建設高鐵網是為了成為連接沿海與內陸的交通樞紐（中部崛起）。", "rep": false, "img": "g4-q19", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-20", "no": 20, "c": "e5", "src": "114上翰林社會2上A卷 卷5 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國 2024 年經濟成長年增率為 5%，圖(六)則為各地方政府預估之地方經濟年增率。圖中預估經濟成長最快速之地方政府，其發展與中國哪一項政策相關？", "o": ["開放生育", "東部率先發展", "西部開發", "經濟改革開放"], "a": 2, "e": "預估成長最快的是西藏、新疆等西部省分，與西部大開發政策有關。", "rep": false, "img": "g4-q20", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-21", "no": 21, "c": "e7", "src": "114上翰林社會2上A卷 卷5 題組 (一) 1", "st": "考卷", "ctx": "中國積極推動「一帶一路」政策向各國倡導區域經濟合作計畫，希望藉此擴大中國影響力。", "fig": "", "q": "文中「一帶」會經過哈薩克、吉爾吉斯、烏茲別克等國家，中國可從這些國家取得何種資源？", "o": ["對外港口", "海外資金", "研發技術", "礦產資源"], "a": 3, "e": "哈薩克等中亞國家蘊藏豐富的石油、天然氣等礦產資源。", "rep": false, "img": "g4-map-belt", "imgnote": "附圖以講義〈一帶一路路線示意圖〉代替", "fh": "", "maps": [], "chk": ""}, {"id": "g4-22", "no": 22, "c": "e7", "src": "114上翰林社會2上A卷 卷5 題組 (一) 2", "st": "考卷", "ctx": "中國積極推動「一帶一路」政策向各國倡導區域經濟合作計畫，希望藉此擴大中國影響力。", "fig": "", "q": "承上題，中國推動文中的政策，其主要目的為何？", "o": ["均衡工業發展", "降低生產成本", "減少工業污染", "擴大貿易市場"], "a": 3, "e": "一帶一路的主要目的之一是擴大貿易市場。", "rep": false, "img": "g4-map-belt", "imgnote": "附圖以講義〈一帶一路路線示意圖〉代替", "fh": "", "maps": [], "chk": ""}, {"id": "g4-23", "no": 23, "c": "e6", "src": "114上翰林社會2上A卷 卷5 題組 (二) 3", "st": "考卷", "ctx": "", "fig": "", "q": "隨著科技進步，中國積極推動產業升級，「中國製造 2025」旨在提升製造能力，減少對外技術依賴，而「中國標準 2035」則希望透過制定國際技術標準，提高全球影響力。這些政策不僅改變中國產業結構，也對國際貿易與科技發展產生影響。中國積極推動上述政策，主要目標為何？", "o": ["擴張經濟市場版圖", "取得關鍵糧食資源", "提升勞工薪資待遇", "提高進口產品比例"], "a": 0, "e": "提升製造能力、制定國際標準，是為了擴張經濟市場版圖、提高全球影響力。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-24", "no": 24, "c": "e9", "src": "114上翰林社會2上A卷 卷5 題組 (二) 4", "st": "考卷", "ctx": "隨著科技進步，中國積極推動產業升級，「中國製造 2025」旨在提升製造能力，減少對外技術依賴，而「中國標準 2035」則希望透過制定國際技術標準，提高全球影響力。這些政策不僅改變中國產業結構，也對國際貿易與科技發展產生影響。", "fig": "", "q": "承上題，上述提及的產業結構轉變，何者將成為具優勢的發展要素？", "o": ["原料", "勞力", "動力", "技術"], "a": 3, "e": "產業升級後，技術會成為最具優勢的發展要素。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-25", "no": 25, "c": "e5", "src": "114上翰林社會2上A卷 卷5 實戰模擬題 1", "st": "考卷", "ctx": "", "fig": "", "q": "中國四大經濟區因所具備的條件不同，造成區域間發展差異。下列有關各經濟區特色的敘述，何者正確？", "o": ["東北地區的重工業面臨設備老舊問題", "東部地區因工礦原料充足而發展最佳", "中部地區因缺乏天然資源而發展落後", "西部地區因平原廣大引外資投資"], "a": 0, "e": "東北是傳統重工業區，面臨礦產枯竭與設備老舊；東部缺原料、中部資源豐富、西部多高原山地。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-region"], "chk": ""}, {"id": "g4-26", "no": 26, "c": "e5", "src": "114上翰林社會2上A卷 卷5 實戰模擬題 2", "st": "考卷", "ctx": "", "fig": "", "q": "「中國深圳因民眾工眾多，有業者推出用貨櫃做成的廉價旅館，住過一個晚上的費用不到新臺幣 30 元，但許多在內陸地區找不到工作而流浪至此打工的人，仍負擔不起租金。」上述情況可能與哪一中國社會現象關係最密切？", "o": ["人口數量過多", "通貨膨脹嚴重", "區域發展不均", "勞工成本上漲"], "a": 2, "e": "內陸找不到工作的人流浪到沿海打工，反映區域發展不均。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-27", "no": 27, "c": "e3", "src": "114上翰林社會2上A卷 卷5 實戰模擬題 3", "st": "考卷", "ctx": "", "fig": "表：對國內——推動西部開發政策、促進族群的融合；對國外——強化與中亞國家的邊境貿易、利於歐亞大陸經濟整合", "q": "表(一)為中國推行某項建設要達成的政策目標，下列哪一城市的位置最符合此目標？", "o": ["深圳市", "上海市", "喀什市", "北京市"], "a": 2, "e": "推動西部開發、加強與中亞邊境貿易，最符合位於新疆的喀什。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-sez"], "chk": ""}, {"id": "g4-28", "no": 28, "c": "e5", "src": "114上翰林社會2上A卷 卷5 實戰模擬題 4", "st": "考卷", "ctx": "", "fig": "表(二)：2020 年 GDP（億人民幣）——1. 上海市 38,701、2. 北京市 36,103、3. 深圳市 26,360", "q": "表(二)是中國 2020 年 GDP 前三大都市排名，依據所在地位置判斷，多屬於哪一個經濟區？", "o": ["東部地區", "中部地區", "西部地區", "東北地區"], "a": 0, "e": "上海、北京、深圳都在東部地區。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-29", "no": 29, "c": "e3", "src": "114上翰林社會2上A卷 卷5 實戰模擬題 5", "st": "考卷", "ctx": "", "fig": "", "q": "圖(七)為中國進出口貿易的發展圖，根據此圖可知，1990 年後貿易總額逐漸成長，此一現象主要受下列哪一因素的影響？", "o": ["中國實施改革開放後，吸引外商投資", "中國推動「一帶一路」政策，市場門戶大開", "香港回歸中國後，資金大量湧入", "中國、亞洲與大洋洲多國簽訂自由貿易協定"], "a": 0, "e": "中國 1978 年底改革開放，吸引外商投資，貿易總額才快速成長。", "rep": false, "img": "g4-q29", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-30", "no": 30, "c": "e5", "src": "114上翰林社會2上A卷 卷5 實戰模擬題 6", "st": "考卷", "ctx": "", "fig": "", "q": "圖(八)為 2020 年外資企業在中國登記數量分布圖，其分布並不平均。若要研究該圖所呈現特徵的背景因素，則以下列哪一張地圖佐證最為適合？", "o": ["中國礦產分布圖", "中國人口分布圖", "中國三級產業產值比例統計圖", "1960～2020 年中國 GDP 變化圖"], "a": 1, "e": "外資企業集中在人口多的東部，可用人口分布圖佐證（人口多、勞力充足、市場大）。", "rep": false, "img": "g4-q30", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-31", "no": 31, "c": "e3", "src": "114上翰林社會2上A卷 卷5 實戰模擬題 7", "st": "考卷", "ctx": "", "fig": "", "q": "圖(九)為中國近年來的國際貿易統計，由圖中資料可推估，中國經濟的發展有何特色？「全球三分之一的鉛筆在中國製造，全球每兩雙鞋至少有一雙在中國生產……」", "o": ["製造業的產量龐大", "對外貿易長期入超", "國內消費市場萎縮", "電子商務相當發達"], "a": 0, "e": "全球大量的煤、原油、鋼材都被中國用掉，反映中國製造業產量龐大、需要大量原料。", "rep": false, "img": "g4-q31", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-32", "no": 32, "c": "e3", "src": "114上翰林社會2上A卷 卷6 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國製造業發達，被譽為「世界工廠」，其主要的工業產品從早期的紡織、成衣到近年來的汽車、機械、電腦等，顯示中國工業發展具有哪一項特色？", "o": ["技術持續提升", "政策持續支持", "勞力逐漸短缺", "工資逐漸上漲"], "a": 0, "e": "工業產品從紡織、成衣進步到汽車、電腦，代表技術持續提升。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-33", "no": 33, "c": "e3", "src": "114上翰林社會2上A卷 卷6 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "經濟改革開放後，外資企業爭相投資中國沿海地區，該地區吸引外資企業的區位優勢不包括下列何者？", "o": ["國內工資低廉", "對外交通便利", "土地取得成本低", "人民的消費力高"], "a": 3, "e": "改革開放初期，沿海吸引外資的是工資低、交通便、土地便宜；當時人民消費力並不高。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-34", "no": 34, "c": "e3", "src": "114上翰林社會2上A卷 卷6 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列為一則新聞報導，此則報導反映中國經濟上的何項特徵？「日本某汽車大廠受疫情影響，零件採購困難，因此宣布暫時停止日本九州組裝工廠的生產。不止日本，其他如美國通用、德國福斯、南韓現代等大廠依賴中國零件維持供應鏈的汽車製造商，都深受影響……。」", "o": ["是生產成本低廉的世界工廠", "是交通便利的國際貿易樞紐", "是資源豐沛的原料物料供應地", "是消費力強大的世界市場"], "a": 0, "e": "各國汽車廠依賴中國零件，代表中國是生產成本低廉的世界工廠。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-35", "no": 35, "c": "e9", "src": "114上翰林社會2上A卷 卷6 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "2018 年中美貿易戰爆發，美國對價值 2,500 億美元中國輸美商品加徵 25% 關稅，從儀器設備到日常的手提包，涵蓋貨品範圍廣泛。此現象將對中國產業造成下列何種影響？", "o": ["企業生產成本下降", "人民消費能力提升", "穩固世界工廠地位", "外國企業遷移他國"], "a": 3, "e": "美國加徵關稅使在中國生產的成本提高，外國企業遷移到其他國家。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-36", "no": 36, "c": "e5", "src": "114上翰林社會2上A卷 卷6 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國經濟發展程度區域不均，可分為東、中、西、東北四個經濟區。下列哪一個地區礦產資源豐富，傳統依賴重工業，近年來因礦產枯竭、設備老舊，發展停滯，急需振興眾多老工業區，加速產業轉型？", "o": ["東部地區", "中部地區", "西部地區", "東北地區"], "a": 3, "e": "礦產豐富、傳統重工業、現在礦產枯竭需振興的是東北地區。", "rep": true, "img": "g4-map-region", "imgnote": "附圖以講義〈四大經濟區分布圖〉代替", "fh": "", "maps": [], "chk": ""}, {"id": "g4-37", "no": 37, "c": "e5", "src": "114上翰林社會2上A卷 卷6 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國西部受限於先天地理環境，對外交通不便，水資源缺乏。可知該區的主要發展方向為何？", "o": ["食品加工製造", "礦產開採加工", "尖端科技研發", "傳統稻作農業"], "a": 1, "e": "西部對外交通不便、缺水，但礦產豐富，發展方向以礦產開採加工為主。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-38", "no": 38, "c": "e7", "src": "114上翰林社會2上A卷 卷6 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國中亞峰會於 2023 年 5 月在中國西安召開，旨在促進中國與中亞交通走廊建設，以及通往中亞的天然氣管道等共識。上述欲推動之建設，與下列哪一個政策最相關？", "o": ["推動 RCEP 合作", "一帶一路政策", "東部率先發展", "開放經濟特區"], "a": 1, "e": "建設通往中亞的交通走廊與天然氣管道，屬於一帶一路政策。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-39", "no": 39, "c": "e5", "src": "114上翰林社會2上A卷 卷6 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國為加大基礎建設，平衡區域發展，推動圖(一)中從重慶到昆明的渝昆高鐵，可串聯至北京、上海的兩大路線。可知該建設完工後，將為下列何項政策帶來效益？", "o": ["西部開發", "東部率先發展", "東北振興", "中部崛起"], "a": 0, "e": "渝昆高鐵在西部的重慶到昆明，有利西部大開發。", "rep": false, "img": "g4-q39", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-40", "no": 40, "c": "e9", "src": "114上翰林社會2上A卷 卷6 第 18 題", "st": "考卷", "ctx": "", "fig": "表(一)：裝車量（GWh）／年增率／市占率——寧德時代（中國）70.9／115.6%／34.8%；LG 新能源（韓國）29.2／6.9%／14.4%；比亞迪（中國）24.0／206.2%／11.8%", "q": "電動車逐漸成為未來趨勢，而電池性能會直接影響汽車的續航能力、充電效率以及使用壽命，占整車成本的 40%。表(一)為 2022 年電池品牌全球前三名，可知中國電池產業具有何種工業特色？", "o": ["產品附加價值低", "勞力密集程度高", "研發技術較落後", "產業競爭力強大"], "a": 3, "e": "寧德時代、比亞迪市占率合計近一半，代表中國電池產業競爭力強大。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-41", "no": 41, "c": "e5", "src": "114上翰林社會2上A卷 卷6 第 19 題", "st": "考卷", "ctx": "", "fig": "表(二)：2023 年農民工人數／增量／增速——東部 15,277 萬人／−170 萬／−1.1%；中部 6,982 萬人／211 萬／3.1%；西部 6,552 萬人／116 萬／1.8%；東北 872 萬人／29 萬／3.4%", "q": "農民工是指為了工作從農村移到城市的人，是中國經濟崛起的動力之一，表(二)為中國 2023 年農民工輸入地區統計。下列有關農民工數據的推論，何者正確？", "o": ["各地區人數均有成長", "農民工總數持續增加", "中、西部人口數增量多", "東北地區增加速度最慢"], "a": 2, "e": "中部增量 211、西部 116 最多，東部反而減少，所以中、西部人數增量多。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-42", "no": 42, "c": "e1", "src": "114上翰林社會2上A卷 卷6 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "大豆是美國對中國出口量最大的農產品，中國為降低進口依賴，開始減少從美國進口大豆，但在國內畜牧業規模持續擴大下，引起飼料供應的擔憂。上述畜牧業的發展，與下列何者關係最為密切？", "o": ["人民生活水準降低", "人均可耕地面積高", "市場需求數量減少", "農業轉型專業生產"], "a": 3, "e": "畜牧業規模擴大、需要大量飼料，代表農業轉型為大規模專業生產。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-43", "no": 43, "c": "e6", "src": "114上翰林社會2上A卷 卷6 題組 (一) 1", "st": "考卷", "ctx": "", "fig": "", "q": "圖(三)為某協定於 2021 年底的基本資料。參考此圖，由圖中內容可知，該協定應為下列何者？", "o": ["區域全面經濟夥伴協定", "跨太平洋夥伴全面進步協定", "北美自由貿易協定", "歐洲聯盟"], "a": 0, "e": "15 國參與、22 億人口、全球占比 30%，是區域全面經濟夥伴協定（RCEP）。", "rep": true, "img": "g4-q43", "imgnote": "", "fh": "", "maps": ["g4-map-rcep"], "chk": ""}, {"id": "g4-44", "no": 44, "c": "e6", "src": "114上翰林社會2上A卷 卷6 題組 (一) 2", "st": "考卷", "ctx": "圖(三)為某協定於 2021 年底的基本資料：15 國參與、22 億人口、經濟規模 26.2 兆美元、全球占比 30%。", "fig": "", "q": "承上題，下列何者為中國與各國簽署該協定的原因？", "o": ["擴張共產勢力", "降低貿易限制", "保護國內企業", "擴大基礎建設"], "a": 1, "e": "簽署 RCEP 是為了降低貿易限制、享有關稅減免。", "rep": false, "img": "g4-q43", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-45", "no": 45, "c": "e6", "src": "114上翰林社會2上A卷 卷6 題組 (一) 3", "st": "考卷", "ctx": "圖(三)為某協定於 2021 年底的基本資料：15 國參與、22 億人口、經濟規模 26.2 兆美元、全球占比 30%。", "fig": "", "q": "承上題，該協定的成員國，大多位於下列哪一大洲？", "o": ["歐洲", "亞洲", "非洲", "美洲"], "a": 1, "e": "RCEP 成員多在亞洲（東協、中、日、韓），另有澳洲、紐西蘭。", "rep": false, "img": "g4-q43", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-46", "no": 46, "c": "e6", "src": "114上翰林社會2上A卷 卷6 題組 (一) 4", "st": "考卷", "ctx": "圖(三)為某協定於 2021 年底的基本資料：15 國參與、22 億人口、經濟規模 26.2 兆美元、全球占比 30%。", "fig": "", "q": "2022 年 1 月 1 日，該協定正式生效。下列哪一則新聞最有可能是該協定生效後所產生的影響？", "o": ["上海簽署貿易協定，關稅減免破千萬人民幣", "斯里蘭卡債務問題未解，港口租給中國 99 年", "該協定使產業競爭加劇，中國減免產品出國優勢", "希臘讓售港口所有權，即日起中國海運可直通歐洲"], "a": 0, "e": "RCEP 生效後成員間關稅減免，上海企業因此受惠。斯里蘭卡、希臘港口是一帶一路的事。", "rep": false, "img": "g4-q43", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-47", "no": 47, "c": "e4", "src": "114上翰林社會2上A卷 卷6 實戰模擬題 3", "st": "考卷", "ctx": "", "fig": "", "q": "圖(四)為 2004、2024 年外國對中國投資行業比例圖。由圖中資訊判斷，下列推論何者正確？", "o": ["中國人民的消費能力提升", "外國設廠的生產成本下降", "中國自 2000 年實施改革開放政策", "外國投資第二級產業的比例增加"], "a": 0, "e": "外資投資服務業的比例大增，代表中國人民的消費能力提升。", "rep": false, "img": "g4-q47", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-48", "no": 48, "c": "e1", "src": "114上翰林社會2上A卷 卷6 實戰模擬題 4", "st": "考卷", "ctx": "", "fig": "", "q": "中國自古以農立國，農業發展至關重要。圖(五)為中國單位面積糧食產量統計圖，造成圖中現象的主要原因為何？", "o": ["生產技術的提升", "人口數量的增加", "經濟政策的變革", "氣候環境的改變"], "a": 0, "e": "單位面積產量持續提高，主要原因是生產技術提升。", "rep": false, "img": "g4-q48", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-49", "no": 49, "c": "e5", "src": "114上翰林社會2上A卷 卷6 實戰模擬題 5", "st": "考卷", "ctx": "", "fig": "", "q": "昔日中國的經濟以農牧業為主，基礎工業薄弱。自從改革開放後，目前第二、三級產業的產值已超越第一級產業，但因自然與人文條件的不同，各地發展有所不同。若要呈現中國工商業的區域差異，下列哪一張圖並非合適的佐證資料？", "o": ["中國礦產分布圖", "中國鐵路分布圖", "中國一帶一路路線圖", "中國經濟特區分布圖"], "a": 2, "e": "一帶一路路線圖無法呈現中國國內工商業的區域差異。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-50", "no": 50, "c": "e1", "src": "114上翰林社會2上A卷 卷6 實戰模擬題 6", "st": "考卷", "ctx": "", "fig": "", "q": "中國為解決豬場用地難題，投入建設 26 層樓的養豬大樓，第一批 3,700 隻豬已經搭上電梯大樓，可享受室內冷、暖氣供應，未來預計年產 120 萬頭豬。上述做法可達成何種目的？", "o": ["提升環境負載力", "提升市場需求量", "提升畜產品售價", "提升農耕地面積"], "a": 0, "e": "蓋養豬大樓可以在有限土地上養更多豬，提升環境負載力。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-51", "no": 51, "c": "e1", "src": "114上翰林社會2上A卷 卷6 實戰模擬題 7", "st": "考卷", "ctx": "", "fig": "", "q": "「蒙牛乳業」為中國乳製品的龍頭，該公司總部設立在內蒙古自治區。使內蒙古部分地區畜牧業產值上升的主要原因為何？", "o": ["工業用地轉作牧場", "國際牛奶價格飆漲", "產業轉型確保供應", "政府重牧輕農政策"], "a": 2, "e": "內蒙古發展專業化乳牛飼養，產業轉型以確保乳品供應。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-52", "no": 52, "c": "e9", "src": "114上翰林社會2上B卷 卷5 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "「中國自 2018 年起被『某國』提高部分商品關稅，加上該國高科技的關鍵性生產技術與零組件被禁止進入中國，改變了中國與全球經濟發展的關係。」文中的「某國」最可能為下列何者？", "o": ["俄羅斯", "澳洲", "美國", "巴西"], "a": 2, "e": "2018 年起對中國提高關稅、禁止關鍵技術輸入的是美國。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-53", "no": 53, "c": "e4", "src": "114上翰林社會2上B卷 卷5 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "「某美式賣場標榜『量大、質優、價格低』，在中國的第一間賣場開幕第一天僅開業 5 小時就因商品被掃購一空而被迫關門。」上述可說明下列何種現象？", "o": ["中國的勞工薪資低廉", "中國的民眾喜新厭舊", "中國民眾消費力驚人", "美國商品附課徵關稅"], "a": 2, "e": "開幕 5 小時商品就被搶購一空，說明中國民眾消費力驚人。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-54", "no": 54, "c": "e3", "src": "114上翰林社會2上B卷 卷5 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "小紅的爸爸在中國某經濟特區工作，圖(一)是爸爸寄給小紅的家書。依據圖中的資訊判斷，小紅爸爸工作的地點最不可能在下列哪一地區？「……我在特區內協助電腦硬體組裝……」", "o": ["深圳", "珠海", "廈門", "汕頭"], "a": 2, "e": "信封寄件地寫廣東省，廣東有深圳、珠海、汕頭三個特區，廈門在福建，最不可能。", "rep": true, "img": "g4-q54", "imgnote": "", "fh": "", "maps": ["g4-map-sez"], "chk": ""}, {"id": "g4-55", "no": 55, "c": "e3", "src": "114上翰林社會2上B卷 卷5 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國自 1970 年代末期開始實施經濟改革開放政策，使得中國東部沿海地區成為中國目前發展最佳地區的主要原因，不包括下列何者？", "o": ["勞力資源充足", "對外交通便利", "土地成本低廉", "礦產資源豐富"], "a": 3, "e": "東部沿海發展好是因為勞力充足、交通便利、土地便宜；東部礦產並不豐富。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-56", "no": 56, "c": "e1", "src": "114上翰林社會2上B卷 卷5 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "目前中國人民所從事的產業型態中，以下列哪一產業所代表的產業類型所占的比例最低？", "o": ["農夫插秧（第一級產業）", "工廠女工組裝（第二級產業）", "快遞外送員（第三級產業）", "高科技研發人員"], "a": 0, "e": "現在中國第一級產業（農業）就業人口比例最低。", "rep": false, "img": "g4-q56", "imgnote": "", "fh": "", "maps": ["g4-map-emp"], "chk": ""}, {"id": "g4-57", "no": 57, "c": "e2", "src": "114上翰林社會2上B卷 卷5 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "重工業的發展非常依賴礦產資源，依據中國的礦產資源分布情形判斷，圖(二)中哪一地區是中國重工業相對發達的地區？", "o": ["甲", "乙", "丙", "丁"], "a": 0, "e": "東北地區（甲）煤、鐵、石油豐富，是中國傳統重工業區。", "rep": true, "img": "g4-q57", "imgnote": "", "fh": "", "maps": ["g4-map-mineral"], "chk": ""}, {"id": "g4-58", "no": 58, "c": "e9", "src": "114上翰林社會2上B卷 卷5 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "「近年來，中國的投資環境改變，部分昔日擁有的生產優勢不再，因此有許多原本到中國投資的紡織、成衣及製鞋廠陸續移出。」文中提及的產業移出最可能與中國何種條件出現變化有關？", "o": ["國民素質下降", "國內市場萎縮", "國民所得下降", "基本工資上揚"], "a": 3, "e": "紡織、成衣、製鞋廠移出，是因為中國基本工資上揚。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-59", "no": 59, "c": "e3", "src": "114上翰林社會2上B卷 卷5 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(三)是水果日報的新聞報導，依據內容判斷，○○應為下列何者？「○○十年內交出『世界最大勞動力人口國』寶座，拱手讓給印度……但○○高居全球製造業霸主地位……」", "o": ["美國", "中國", "日本", "德國"], "a": 1, "e": "勞動力人口將被印度超越、但仍是製造業霸主的國家是中國。", "rep": false, "img": "g4-q59", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-60", "no": 60, "c": "e6", "src": "114上翰林社會2上B卷 卷5 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國為擴大其經濟版圖，在 2020 年簽署「區域全面經濟夥伴協定」，該協定的參與國享有關稅減免、降低進出口限制等優惠，對中國貿易發展有極大的幫助。下列何者是該組織的成員國？", "o": ["蒙古", "南韓", "印度", "俄羅斯"], "a": 1, "e": "RCEP 成員包括南韓；蒙古、印度、俄羅斯都不是成員。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-rcep"], "chk": ""}, {"id": "g4-61", "no": 61, "c": "e3", "src": "114上翰林社會2上B卷 卷5 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國自 1970 年代末期實施經濟改革，若將初期與近期前往該國投資的產業型態進行比較，可以發現投資型態有下列哪一種轉變？", "o": ["勞力密集型產業→技術密集型產業", "資本密集型產業→勞力密集型產業", "技術密集型產業→資本密集型產業", "原料密集型產業→勞力密集型產業"], "a": 0, "e": "初期以勞力密集型產業為主，近期轉向技術密集型產業。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-62", "no": 62, "c": "e1", "src": "114上翰林社會2上B卷 卷5 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(四)為 1980～2023 年中國三級產業就業人口比例圖，依據中國的經濟發展情形判斷，圖中甲、乙、丙所指的分別為哪一級產業？", "o": ["甲：第一級、乙：第二級、丙：第三級", "甲：第二級、乙：第三級、丙：第一級", "甲：第三級、乙：第二級、丙：第一級", "甲：第三級、乙：第一級、丙：第二級"], "a": 2, "e": "丙持續下降是第一級、乙小幅變化是第二級、甲持續上升是第三級。", "rep": false, "img": "g4-q62", "imgnote": "", "fh": "", "maps": ["g4-map-emp"], "chk": ""}, {"id": "g4-63", "no": 63, "c": "e5", "src": "114上翰林社會2上B卷 卷5 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(五)為中國的四大經濟區分布圖，位於四川盆地東側的重要都市是近年來中國重點發展的城市之一，由該城市的發展可以看出，中國正積極改善圖中哪一個經濟區的投資環境？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "重慶位於西部地區（丁），中國正積極改善西部的投資環境。", "rep": false, "img": "g4-q63", "imgnote": "", "fh": "", "maps": ["g4-map-region"], "chk": ""}, {"id": "g4-64", "no": 64, "c": "e7", "src": "114上翰林社會2上B卷 卷5 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國之所以提出「一帶一路」的經濟合作方案，其主要目的不包括下列何者？", "o": ["擴大對外貿易的市場", "獲得穩定的能源供給", "維持中國工業的穩定發展", "將資本主義推廣至參與國"], "a": 3, "e": "一帶一路是經濟合作，不是推廣資本主義。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-65", "no": 65, "c": "e1", "src": "114上翰林社會2上B卷 卷5 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國的國土面積居世界第四位，但人均可耕地面積遠低於世界平均值的主要原因可能為下列何者？", "o": ["農地轉作他用", "生產技術落後", "缺乏灌溉水源", "沙漠面積過大"], "a": 0, "e": "工商業與城鎮擴張，大量農地轉作他用，人均可耕地面積很小。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-66", "no": 66, "c": "e5", "src": "114上翰林社會2上B卷 卷5 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "「這個地區昔日因為礦產資源豐富，使其成為中國傳統重工業重心，但隨著礦產枯竭，加上工廠設備老舊，因此政府提出振興政策，希望可以促進產業轉型。」上文提及的應為哪一個經濟區？", "o": ["東部經濟區", "東北經濟區", "中部經濟區", "西部經濟區"], "a": 1, "e": "昔日礦產豐富、傳統重工業重心、現在需要振興的是東北經濟區。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-region"], "chk": ""}, {"id": "g4-67", "no": 67, "c": "e7", "src": "114上翰林社會2上B卷 卷5 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國新提出的「一帶一路」經濟政策，其中綠色網絡絲綢之路經濟帶的主要線路與圖(六)中何者最相符？", "o": ["甲", "乙", "丙", "丁"], "a": 1, "e": "絲綢之路經濟帶從西安出發，經新疆往西通往中亞、歐洲，是乙路線。", "rep": true, "img": "g4-q67", "imgnote": "", "fh": "", "maps": ["g4-map-belt"], "chk": ""}, {"id": "g4-68", "no": 68, "c": "e5", "src": "114上翰林社會2上B卷 卷5 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "交通建設是影響產業發展的重要因素，中國各地區的地理環境差異大，交通建設也不盡相同，圖(七)中哪一地區的鐵公路網的密度最低？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "丁位在青藏高原，地勢高、地形崎嶇，鐵公路網密度最低。", "rep": false, "img": "g4-q68", "imgnote": "", "fh": "", "maps": ["g4-map-rail"], "chk": ""}, {"id": "g4-69", "no": 69, "c": "e2", "src": "114上翰林社會2上B卷 卷5 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(八)中的黑點是中國某種礦產資源的分布情形，若依據原料區位的因素判斷，這些地區最適合發展何種產業？", "o": ["鋼鐵工業", "石化工業", "造船工業", "紡織工業"], "a": 1, "e": "黑點是石油產地，依原料區位最適合發展石化工業。", "rep": false, "img": "g4-q69", "imgnote": "", "fh": "", "maps": ["g4-map-mineral"], "chk": ""}, {"id": "g4-70", "no": 70, "c": "e6", "src": "114上翰林社會2上B卷 卷5 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "自 2000 年開始，中國開始主張「走出去」政策，鼓勵本國企業對外國投資。這些企業對外投資的目的最不可能為下列何者？", "o": ["進入歐美等國市場", "取得石油礦產資源", "快速獲得產業技術", "增加國家領土面積"], "a": 3, "e": "企業對外投資是為了市場、資源、技術，不可能增加國家領土。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-71", "no": 71, "c": "e5", "src": "114上翰林社會2上B卷 卷5 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國在實施經濟改革開放後，出現了嚴重區域發展不均的現象。為了達到區域均衡發展，政府提出多項策略。圖(九)為某項工程的路線圖，根據圖中資訊判斷，應屬下列哪一策略的內容？", "o": ["青藏鐵路", "西電東送", "南水北調", "中部崛起"], "a": 1, "e": "圖中是從西部往東部的輸送路線，屬於西部大開發的「西電東送」。", "rep": false, "img": "g4-q71", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-72", "no": 72, "c": "e8", "src": "114上翰林社會2上B卷 卷5 第 21 題", "st": "考卷", "ctx": "", "fig": "", "q": "「一帶一路」雖然可以透過合作來擴展沿線國家的經濟利益，但也有學者提出，該政策可能會出現許多挑戰。上述所指的挑戰不包括下列何者？", "o": ["部分參與國經濟發展程度落後，易產生龐大的債務", "參與國人民擔心中國會以投資左右該國的政治經濟", "參與國的軍事實力強大，中國面臨國際衝突危機", "參與國期望引進中國資金，卻產生國內利益糾紛"], "a": 2, "e": "一帶一路參與國多為經濟落後的國家，並非軍事強大的國家。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-73", "no": 73, "c": "e3", "src": "114上翰林社會2上B卷 卷5 第 22 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(十)的虛線圈是中國最早實施經濟改革開放的地區，1980 年代，中國以該地區所具有的工業發展優勢吸引外國資金及技術進駐，帶動該地區的工商業發展。文中提及的優勢不包括下列何者？", "o": ["便捷的交通", "廉價的勞工", "低廉的土地", "進步的技術"], "a": 3, "e": "經濟特區的優勢是交通便捷、勞工廉價、土地低廉；當時中國技術並不進步。", "rep": false, "img": "g4-q73", "imgnote": "", "fh": "", "maps": ["g4-map-sez"], "chk": ""}, {"id": "g4-74", "no": 74, "c": "e5", "src": "114上翰林社會2上B卷 卷5 第 23 題", "st": "考卷", "ctx": "", "fig": "", "q": "某區因位置較為內陸，發展不如東部地區，因此政府提出「相關政策」，希望複製沿海成功的經驗，以較低廉的工資及自然資源優勢，吸引外國資金投入，該區的發展重點如湖北省武漢市等。文中提及的政策最可能為下列何者？", "o": ["東北振興", "中部崛起", "西部開發", "東部率先發展"], "a": 1, "e": "位在內陸、以低廉工資與自然資源吸引外資、重點城市如武漢，是中部崛起。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-region"], "chk": ""}, {"id": "g4-75", "no": 75, "c": "e4", "src": "114上翰林社會2上B卷 卷5 第 24 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(十一)是 2004 年及 2023 年外商在中國的投資行業比例變化情形，由圖可發現中國經濟發展的何種變遷？", "o": ["為了保護國內製造業，政府限制製造業進入", "網際網路的便捷度提升，電子商務大幅攀升", "人民所得增加提升消費力，吸引服務業進駐", "為獲取外國的技術，中資大量併購外國企業"], "a": 2, "e": "外商投資服務業的比例增加，是因為人民所得增加、消費力提升。", "rep": false, "img": "g4-q75", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-76", "no": 76, "c": "e3", "src": "114上翰林社會2上B卷 卷5 題組 (一) 1", "st": "考卷", "ctx": "", "fig": "", "q": "中國於 2010 年正式批准設立喀什經濟特區，期望以 1978 年設立的五大經濟特區為榜樣，將喀什打造成為國際現代化都市。經過 15 年的發展，喀什的進出口貿易額年均成長率高達 300%，居民人均所得更居全行政區之首。憑藉其「五口通八國、一路連歐亞」的地理優勢，喀什經濟特區未來的發展潛力十分可觀。文中提及的城市位於哪一行政區的範圍內？", "o": ["西藏自治區", "內蒙古自治區", "廣西壯族自治區", "新疆維吾爾自治區"], "a": 3, "e": "喀什位在新疆維吾爾自治區。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-sez"], "chk": ""}, {"id": "g4-77", "no": 77, "c": "e5", "src": "114上翰林社會2上B卷 卷5 題組 (一) 2", "st": "考卷", "ctx": "中國於 2010 年正式批准設立喀什經濟特區，期望以 1978 年設立的五大經濟特區為榜樣，將喀什打造成為國際現代化都市。經過 15 年的發展，喀什的進出口貿易額年均成長率高達 300%，居民人均所得更居全行政區之首。憑藉其「五口通八國、一路連歐亞」的地理優勢，喀什經濟特區未來的發展潛力十分可觀。", "fig": "", "q": "承上題，文中提及的城市發展與下列哪一政策的關聯性最大？", "o": ["東北振興", "西部開發", "中部崛起", "東部率先發展"], "a": 1, "e": "喀什經濟特區位於西部，與西部開發政策關係最大。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-78", "no": 78, "c": "e3", "src": "114上翰林社會2上B卷 卷5 題組 (一) 3", "st": "考卷", "ctx": "中國於 2010 年正式批准設立喀什經濟特區，期望以 1978 年設立的五大經濟特區為榜樣，將喀什打造成為國際現代化都市。經過 15 年的發展，喀什的進出口貿易額年均成長率高達 300%，居民人均所得更居全行政區之首。憑藉其「五口通八國、一路連歐亞」的地理優勢，喀什經濟特區未來的發展潛力十分可觀。", "fig": "", "q": "承上題，文中提及該城市所屬的八國，最可能是圖(十二)中哪一地區？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "喀什鄰近的國家多在中亞（丁）。", "rep": false, "img": "g4-q78", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-79", "no": 79, "c": "e2", "src": "114上翰林社會2上B卷 卷5 題組 (一) 4", "st": "考卷", "ctx": "中國於 2010 年正式批准設立喀什經濟特區，期望以 1978 年設立的五大經濟特區為榜樣，將喀什打造成為國際現代化都市。經過 15 年的發展，喀什的進出口貿易額年均成長率高達 300%，居民人均所得更居全行政區之首。憑藉其「五口通八國、一路連歐亞」的地理優勢，喀什經濟特區未來的發展潛力十分可觀。", "fig": "", "q": "承上題，中國在該經濟特區除了可以發展勞力密集型產業外，也可以利用該區內所蘊藏的礦產發展相關產業。而文中提及的礦產最可能為下列何者？", "o": ["黃金", "鐵礦", "石油", "稀土"], "a": 2, "e": "新疆蘊藏豐富的石油，可以發展石化工業。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-80", "no": 80, "c": "e5", "src": "114上翰林社會2上B卷 卷5 題組 (二) 5", "st": "考卷", "ctx": "", "fig": "", "q": "「四十年看深圳，一百年看上海，五百年看北京，兩千年看西安。」是近年來興起的一句中國俗諺，其中「四十年看深圳」是指深圳所代表改革開放的時代屬性；「一百年看上海」是指《南京條約》而開港的上海；「五百年看北京」是指明清兩代，北京都作為中國的首都，是文化政治經濟的中心；「兩千年看西安」是指從秦始皇到唐代，西安一直是中國的核心。除了西安外，其他三個城市均位於下列哪一經濟區？", "o": ["東部經濟區", "東北經濟區", "中部經濟區", "西部經濟區"], "a": 0, "e": "深圳、上海、北京都位在東部經濟區。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-81", "no": 81, "c": "e3", "src": "114上翰林社會2上B卷 卷5 題組 (二) 6", "st": "考卷", "ctx": "「四十年看深圳，一百年看上海，五百年看北京，兩千年看西安。」是近年來興起的一句中國俗諺，其中「四十年看深圳」是指深圳所代表改革開放的時代屬性；「一百年看上海」是指《南京條約》而開港的上海；「五百年看北京」是指明清兩代，北京都作為中國的首都，是文化政治經濟的中心；「兩千年看西安」是指從秦始皇到唐代，西安一直是中國的核心。", "fig": "", "q": "承上題，文中提及的「四十年」城市應位於圖(十三)中何處？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "「四十年看深圳」，深圳在廣東省珠江口東側，是圖中的丁。", "rep": false, "img": "g4-q81", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-82", "no": 82, "c": "e5", "src": "114上翰林社會2上B卷 卷5 題組 (二) 7", "st": "考卷", "ctx": "「四十年看深圳，一百年看上海，五百年看北京，兩千年看西安。」是近年來興起的一句中國俗諺，其中「四十年看深圳」是指深圳所代表改革開放的時代屬性；「一百年看上海」是指《南京條約》而開港的上海；「五百年看北京」是指明清兩代，北京都作為中國的首都，是文化政治經濟的中心；「兩千年看西安」是指從秦始皇到唐代，西安一直是中國的核心。", "fig": "", "q": "承上題，文中提及的「一百年城市」（上海）的發展與便捷的對外交通有關，該城市因位於下列哪一河川出海口，可以將流域內的貨物集結後輸出海外？", "o": ["黃河", "長江", "淮河", "珠江"], "a": 1, "e": "上海位在長江出海口，可集結流域內的貨物輸出。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-83", "no": 83, "c": "e3", "src": "114上翰林社會2上B卷 卷6 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國於 1978 年起陸續在東南沿海地區成立了五個經濟特區，初期這些經濟特區所吸引設廠的產業型態，其生產成本的比例圖與下列何者最相符？", "o": ["圖 (A)", "圖 (B)", "圖 (C)", "圖 (D)"], "a": 0, "e": "經濟特區初期以勞力密集產業為主，生產成本以勞工成本最多，選 (A)。", "rep": false, "img": "g4-q83", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-84", "no": 84, "c": "e6", "src": "114上翰林社會2上B卷 卷6 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "由中國主導的「區域全面經濟夥伴協定」，經濟規模高達 26 兆美元，成員國包含東協及部分亞洲國家，而參與協定的國家享有關稅減免的優惠。依據上列判斷，下列選項中的國家商品往來，何者不符合上述關稅減免的條件？", "o": ["日本→南韓", "中國→澳洲", "澳洲→紐西蘭", "印度→菲律賓"], "a": 3, "e": "印度沒有加入 RCEP，印度與菲律賓之間不能享有協定的關稅減免。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-rcep"], "chk": ""}, {"id": "g4-85", "no": 85, "c": "e9", "src": "114上翰林社會2上B卷 卷6 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "在全球化經濟的時代，國家與國之間的貿易活動，有時可能影響全球經濟。圖(一)中所示的兩個國家自 2018 年起因何種狀況而影響到全球經濟？", "o": ["礦產匱乏", "關稅爭議", "領土大小", "耕地差異"], "a": 1, "e": "美國和中國從 2018 年起爆發關稅爭議（貿易戰），影響全球經濟。", "rep": false, "img": "g4-q85", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-86", "no": 86, "c": "e3", "src": "114上翰林社會2上B卷 卷6 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國於 1978 年實施經濟改革，其中最早實施改革開放的地區為圖(二)中何地？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "最早改革開放的是東南沿海地區（丁）。", "rep": false, "img": "g4-q86", "imgnote": "", "fh": "", "maps": ["g4-map-region"], "chk": ""}, {"id": "g4-87", "no": 87, "c": "e5", "src": "114上翰林社會2上B卷 卷6 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(三)是億億寄給好友張三的信，依據信中地址判斷，該封信寄出地到收件地，其運送方向大致為何？", "o": ["向北送", "向南送", "向西送", "向東送"], "a": 1, "e": "信從北京寄到福建廈門，運送方向大致向南。", "rep": false, "img": "g4-q87", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-88", "no": 88, "c": "e5", "src": "114上翰林社會2上B卷 卷6 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(四)是中國煤礦分布圖，近年隨著礦產枯竭，陸續進行產業轉型，而朝向發展的產業包括下列何項？", "o": ["電動汽車", "鋼鐵工業", "成衣加工", "永續農業"], "a": 0, "e": "煤礦區礦產枯竭後，產業轉型朝向發展電動汽車等新興產業。", "rep": false, "img": "g4-q88", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-89", "no": 89, "c": "e5", "src": "114上翰林社會2上B卷 卷6 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國自 2003 年起，在「這個地區」實施多項振興經濟的政策，如更新工廠老舊設施或促進產業轉型；加強與俄羅斯、北韓邊界地區的經貿合作等。上述政策最可能是下列何者？", "o": ["東北振興", "中部崛起", "西部開發", "東部率先發展"], "a": 0, "e": "更新老舊工廠、加強與俄羅斯和北韓合作，是東北振興。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-region"], "chk": ""}, {"id": "g4-90", "no": 90, "c": "e5", "src": "114上翰林社會2上B卷 卷6 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(五)為中國四大經濟區，其中哪一地區是中國人口最稠密、勞力最充足，亦擁有優越的對外交通優勢？", "o": ["甲", "乙", "丙", "丁"], "a": 1, "e": "人口最稠密、勞力充足、對外交通最好的是東部地區（乙）。", "rep": false, "img": "g4-q90", "imgnote": "", "fh": "", "maps": ["g4-map-region"], "chk": ""}, {"id": "g4-91", "no": 91, "c": "e1", "src": "114上翰林社會2上B卷 卷6 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國在世界面積前六大的國家中，其人均可耕地面積是唯一低於世界平均值的國家，導致此現象產生的主要原因最可能為下列何者？", "o": ["中國沙漠面積廣大", "中國產業結構改變", "中國生產技術落後", "中國地形崎嶇不平"], "a": 1, "e": "中國人均可耕地低，主要是產業結構改變，許多農地轉作他用。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-92", "no": 92, "c": "e3", "src": "114上翰林社會2上B卷 卷6 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "根據下文，中國影響全球經濟因何種產業環境有關？「大寶：廉價的『Made in China』產品暢銷全球，使各國在地產業難以與其競爭。阿全：大企業直接設廠於中國以進行專業化生產，導致原國家失業率上升。」", "o": ["進步的技術", "廉價的勞工", "豐富的礦產", "廣大的市場"], "a": 1, "e": "廉價的中國產品使各國產業難以競爭，反映中國勞工廉價。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-93", "no": 93, "c": "e7", "src": "114上翰林社會2上B卷 卷6 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(六)是中國某位探險家的路線圖，此路線是中國政府於 2013 年提出的經濟策略之基礎。透過此一路線，中國希望加強合作的國家包括下列何者？", "o": ["非洲", "南美洲", "大洋洲", "南極洲"], "a": 0, "e": "鄭和下西洋的路線經東南亞、印度洋到非洲東岸，是海上絲綢之路的基礎。", "rep": false, "img": "g4-q93", "imgnote": "", "fh": "", "maps": ["g4-map-belt"], "chk": ""}, {"id": "g4-94", "no": 94, "c": "e5", "src": "114上翰林社會2上B卷 卷6 第 23 題", "st": "考卷", "ctx": "", "fig": "", "q": "近年來，中國與甲國進行航運合作，新增圖(七)中的海參崴作為內貿貨物中轉口岸，此一政策實行後，便捷物流的打通有助於下列哪一經濟政策的推動？", "o": ["中部崛起", "東北振興", "西部開發", "東部率先發展"], "a": 1, "e": "經俄羅斯海參崴出海，便利吉林、黑龍江物流，有助於東北振興。", "rep": false, "img": "g4-q94", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-95", "no": 95, "c": "e7", "src": "114上翰林社會2上B卷 卷6 題組 (一) 1", "st": "考卷", "ctx": "", "fig": "", "q": "圖(八)是中國於 2013 年提出的「一帶一路」路線圖，希望透過陸上海路網絡，與沿線國家進行經濟合作，擴展中國在世界經濟舞臺的重要性。圖中甲、乙代表的是兩條路線，而ㄅ～ㄈ則為亞洲的不同分區。透過圖中甲路線（絲綢之路經濟帶）可以前往哪一大洲？", "o": ["非洲", "歐洲", "美洲", "大洋洲"], "a": 1, "e": "甲路線是絲綢之路經濟帶，經中亞可以前往歐洲。", "rep": false, "img": "g4-q95", "imgnote": "", "fh": "", "maps": ["g4-map-belt"], "chk": ""}, {"id": "g4-96", "no": 96, "c": "e9", "src": "114上翰林社會2上B卷 卷6 題組 (一) 2", "st": "考卷", "ctx": "", "fig": "", "q": "「近年來，由於中國工資逐漸上漲，部分臺商的低價代工廠也逐漸就近遷移至其他國家。」依據經濟發展情形判斷，上述的其他國家最可能為下列何者？", "o": ["越南", "日本", "南韓", "美國"], "a": 0, "e": "中國工資上漲，低價代工廠移到工資更低的越南等東南亞國家。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-97", "no": 97, "c": "e7", "src": "114上翰林社會2上B卷 卷6 題組 (一) 3", "st": "考卷", "ctx": "圖(八)是中國於 2013 年提出的「一帶一路」路線圖，希望透過陸上海路網絡，與沿線國家進行經濟合作，擴展中國在世界經濟舞臺的重要性。圖中甲、乙代表的是兩條路線，而ㄅ～ㄈ則為亞洲的不同分區。", "fig": "", "q": "承第 1 題，圖中乙路線（21世紀海上絲綢之路）所串聯的地區不包括下列何地？", "o": ["非洲", "歐洲", "南美洲", "東南亞"], "a": 2, "e": "海上絲綢之路串聯東南亞、南亞、非洲、歐洲，不包括南美洲。", "rep": false, "img": "g4-q95", "imgnote": "", "fh": "", "maps": ["g4-map-belt"], "chk": ""}, {"id": "g4-98", "no": 98, "c": "e8", "src": "114上翰林社會2上B卷 卷6 題組 (一) 4", "st": "考卷", "ctx": "圖(八)是中國於 2013 年提出的「一帶一路」路線圖，希望透過陸上海路網絡，與沿線國家進行經濟合作，擴展中國在世界經濟舞臺的重要性。圖中甲、乙代表的是兩條路線，而ㄅ～ㄈ則為亞洲的不同分區。", "fig": "", "q": "「因為無法償還由中國建造港口的債務，斯里蘭卡只好將該港口租給中國 99 年，但此舉卻引發國內民眾的嚴重抗議。」上述提及的國家應位於圖中哪一地區？", "o": ["ㄅ", "ㄆ", "ㄇ", "ㄈ"], "a": 1, "e": "斯里蘭卡位在南亞（ㄆ）。", "rep": false, "img": "g4-q95", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-99", "no": 99, "c": "e3", "src": "114上翰林社會2上B卷 卷6 題組 (二) 5", "st": "考卷", "ctx": "", "fig": "", "q": "交通建設是產業發展的基礎，圖(九)是中國近期通車的高速鐵路路線圖，該路線經過中國某經濟特區，通車後的搭載率相當高，也帶動了中國中部與東部經濟區之間的往來。文中提及的經濟特區應為下列何者？", "o": ["廈門", "深圳", "珠海", "汕頭"], "a": 1, "e": "高鐵起點是位在香港旁的深圳經濟特區。", "rep": false, "img": "g4-q99", "imgnote": "", "fh": "", "maps": ["g4-map-sez"], "chk": ""}, {"id": "g4-100", "no": 100, "c": "e3", "src": "114上翰林社會2上B卷 卷6 題組 (二) 6", "st": "考卷", "ctx": "交通建設是產業發展的基礎，圖(九)是中國近期通車的高速鐵路路線圖，該路線經過中國某經濟特區，通車後的搭載率相當高，也帶動了中國中部與東部經濟區之間的往來。", "fig": "", "q": "承上題，文中提及的經濟特區位於哪一河川出海口？", "o": ["黃河", "淮河", "長江", "珠江"], "a": 3, "e": "深圳位在珠江出海口。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-101", "no": 101, "c": "e5", "src": "114上翰林社會2上B卷 卷6 題組 (二) 7", "st": "考卷", "ctx": "交通建設是產業發展的基礎，圖(九)是中國近期通車的高速鐵路路線圖，該路線經過中國某經濟特區，通車後的搭載率相當高，也帶動了中國中部與東部經濟區之間的往來。", "fig": "", "q": "承上題，上文中的路線通車後，吸引不少產業進入中部經濟區投資，中部經濟區發展優勢包括以下哪一項？", "o": ["工商業最發達", "設有經濟特區", "工資較為低廉", "對外交通便利"], "a": 2, "e": "中部地區的優勢是工資比東部低廉。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-102", "no": 102, "c": "e5", "src": "114上翰林社會2上C卷 卷5 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "由於中國地理環境差異大，所以各地區的交通方式、運輸網絡密集程度也不盡相同，進而影響各地的工商業發展。下列哪一地區受到自然環境影響，鐵路線路最少？", "o": ["青藏高原", "山東丘陵", "四川盆地", "東北平原"], "a": 0, "e": "青藏高原地勢高、地形崎嶇，鐵路最少。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-rail"], "chk": ""}, {"id": "g4-103", "no": 103, "c": "e3", "src": "114上翰林社會2上C卷 卷5 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國在實施經濟改革開放以來，對於國家整體經濟發展最主要的影響為下列何者？", "o": ["人民可以選擇居住的區域", "吸引外國資金投資及設廠", "外移人口比例呈快速增加", "人口快速增加糧食較缺乏"], "a": 1, "e": "改革開放最主要的影響是吸引外國資金投資設廠。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-104", "no": 104, "c": "e1", "src": "114上翰林社會2上C卷 卷5 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(一)顯示中國人均可耕地與其他國家的比較，根據比較結果，中國的人均可耕地具有下列何種特色？", "o": ["農地轉作他用，人均可耕地較小", "由於面積廣大，人均可耕地較大", "農耕技術較佳，人均可耕地較大", "年降水量不均，人均可耕地較小"], "a": 0, "e": "中國人均可耕地只有 0.09 公頃，遠低於世界平均，主因是農地轉作他用。", "rep": false, "img": "g4-q104", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-105", "no": 105, "c": "e4", "src": "114上翰林社會2上C卷 卷5 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(二)為世界國內生產毛額（GDP）最多的三個國家。依據圖中內容判斷，乙應為哪一國？", "o": ["中國", "美國", "日本", "德國"], "a": 0, "e": "中國 GDP 在 2010 年超越日本，居世界第二，是乙。", "rep": false, "img": "g4-q105", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-106", "no": 106, "c": "e2", "src": "114上翰林社會2上C卷 卷5 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "新疆近年已成為國家重要的石化工業基地，2014 年石油石化工業總產值達到 3852.44 億元，比 2009 年增長 96%。新疆發展石化工業的區位條件為何？", "o": ["勞工便宜", "鄰近市場", "盛產原料", "交通便利"], "a": 2, "e": "新疆盛產石油、天然氣，發展石化工業是原料區位。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-107", "no": 107, "c": "e3", "src": "114上翰林社會2上C卷 卷5 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(三)顯示中國沿海經濟特區的位置，經濟特區分布在中國哪個行政區的數量最多？", "o": ["廣東", "福建", "海南", "上海"], "a": 0, "e": "廣東有深圳、珠海、汕頭三個經濟特區，數量最多。", "rep": true, "img": "g4-q107", "imgnote": "", "fh": "", "maps": ["g4-map-sez"], "chk": ""}, {"id": "g4-108", "no": 108, "c": "e3", "src": "114上翰林社會2上C卷 卷5 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "早期中國成立經濟特區，開放其他國家可以進行投資，當時主要成立的工廠，具有下列哪項特色？", "o": ["技術密集", "勞力密集", "能源密集", "資金密集"], "a": 1, "e": "早期經濟特區以勞力密集產業為主。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-109", "no": 109, "c": "e5", "src": "114上翰林社會2上C卷 卷5 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "2022 年上海港集裝箱吞吐量連續 13 年蟬聯世界第一名，其中以洋山港區運輸量最多。上述港口應位於圖(四)中何處？", "o": ["甲", "乙", "丙", "丁"], "a": 2, "e": "上海港位在長江出海口，海岸線中段的丙。", "rep": false, "img": "g4-q109", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-110", "no": 110, "c": "e7", "src": "114上翰林社會2上C卷 卷5 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國的一帶一路政策所帶來的正面效益龐大，其中解決中國國內面臨的經濟發展困境，包括下列何者？", "o": ["耕地面積不足", "人口老化問題", "勞動人口不足", "工業產能過剩"], "a": 3, "e": "一帶一路能消化中國過剩的工業產能。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-111", "no": 111, "c": "e3", "src": "114上翰林社會2上C卷 卷5 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "瑞雪整理中國成為「世界工廠」的優勢條件，以下她歸納的結果，何者並非吸引外國資金投資設廠的優勢條件？", "o": ["方便的交通", "廣大的市場", "低廉的工資", "溫和的氣候"], "a": 3, "e": "溫和的氣候不是吸引外資設廠的條件。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-112", "no": 112, "c": "e6", "src": "114上翰林社會2上C卷 卷5 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國政府鼓勵企業在他國投資，例如：中國萬達集團收購美國傳奇影業公司，五礦集團收購加拿大和澳洲的國際礦產公司。下列何者不是上述中國對外投資的目的？", "o": ["便於取得他國的自然資源", "快速進入歐美等國的市場", "可直接獲取他國產業技術", "與他國合作成立區域組織"], "a": 3, "e": "成立區域組織要簽訂協定，不是企業收購的目的。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-113", "no": 113, "c": "e1", "src": "114上翰林社會2上C卷 卷5 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "地理課四位同學介紹中國農業發展，下列哪位同學的說法錯誤？", "o": ["農作物類型深受自然環境影響", "牧業與農業皆集中在中國東部", "目前有些農民改採機械化耕作", "因地制宜轉型成為專業生產區"], "a": 1, "e": "牧業主要在西部，農業在東部，所以 (B) 錯。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-114", "no": 114, "c": "e5", "src": "114上翰林社會2上C卷 卷5 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國為了平衡區域差異，提出「中部崛起」政策，希望建設中部以「承東啟西」，並結合兩者產業發展優勢而崛起。上述地區的發展優勢包括下列何項？", "o": ["較東部低廉的工資", "海運交通最為便利", "對外開放時間最早", "傳統的重工業中心"], "a": 0, "e": "中部的優勢是工資比東部低廉。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-115", "no": 115, "c": "e8", "src": "114上翰林社會2上C卷 卷5 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "2017 年由於斯里蘭卡將沿海港口租給中國 99 年，當地居民被迫遷移，因此引發民眾與政府對立衝突。斯里蘭卡將港口租給中國的主要原因為何？", "o": ["與中國合作開發資源", "為降低出口中國關稅", "無力償還中國的債務", "為增強彼此經濟連結"], "a": 2, "e": "斯里蘭卡無力償還中國的債務，只好出租港口。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-116", "no": 116, "c": "e3", "src": "114上翰林社會2上C卷 卷5 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "1980 年代，中國沿海的經濟特區多從事紡織、玩具等輕工業。上述的工廠類型較符合下列哪種產業類型？", "o": ["圖 (A)", "圖 (B)", "圖 (C)", "圖 (D)"], "a": 0, "e": "紡織、玩具等輕工業是勞力密集產業，勞工成本比例最高，選 (A)。", "rep": false, "img": "g4-q116", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-117", "no": 117, "c": "e4", "src": "114上翰林社會2上C卷 卷5 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(五)為 2004、2023 年外國對中國投資行業比例圖，圖中哪一類型的產業比例增加最多？", "o": ["農業", "服務業", "重工業", "高科技產業"], "a": 1, "e": "2023 年外國投資服務業的比例大幅增加。", "rep": false, "img": "g4-q117", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-118", "no": 118, "c": "e7", "src": "114上翰林社會2上C卷 卷5 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "志翔上網搜尋中國某項促進經濟發展的政策，找到的圖片如圖(六)所示（沙漠中駱駝行進伴隨火車），他所搜尋的是哪項政策內容？", "o": ["一帶一路", "經濟特區", "中部崛起", "西部開發"], "a": 0, "e": "圖中是陸、海兩條路線連接亞、歐、非，是一帶一路。", "rep": false, "img": "g4-q118", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-119", "no": 119, "c": "e7", "src": "114上翰林社會2上C卷 卷5 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "由中國開客西開往歐洲的中歐班列於 2011 年啟航，串聯許多歐亞大都市。相較於 1980 年代中國以東部沿海作為貿易重心，新貿易路線的出現，將使中國對外貿易出現哪一變化？", "o": ["空運將比以往更加重要", "運送成本較空運昂貴", "運送時間較傳統海運短", "經濟發展重心由內陸擴散至沿海"], "a": 2, "e": "中歐班列走陸路，運送時間比繞遠路的傳統海運短。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-120", "no": 120, "c": "e3", "src": "114上翰林社會2上C卷 卷5 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "這座位於中國西部的城市，由於政府積極開發，在成為經濟特區後，當地國際貿易往來更加頻繁。上述城市應為下列何者？", "o": ["珠海", "廈門", "汕頭", "喀什"], "a": 3, "e": "位於西部的經濟特區是喀什。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-sez"], "chk": ""}, {"id": "g4-121", "no": 121, "c": "e7", "src": "114上翰林社會2上C卷 卷5 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "學者指出，今日的中國在非洲具有舉足輕重的政治及經濟影響力。中國與非洲各國之間貿易往來頻繁，主要的原因為何？", "o": ["兩地區隔印度洋往來便利", "非洲具有先進的產業技術", "中國積極擴大國際間貿易", "非洲為世界主要消費市場"], "a": 2, "e": "中國透過一帶一路積極擴大國際貿易，與非洲往來頻繁。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-122", "no": 122, "c": "e6", "src": "114上翰林社會2上C卷 卷5 題組 (一) 1", "st": "考卷", "ctx": "", "fig": "", "q": "「區域全面經濟夥伴協定（簡稱 RCEP）」是由東南亞國家協會發起簽署的自由貿易協定，其會員國範圍的人口高達 20 億人，占全球人口約 30%，成為目前世界最大的自由貿易協議，圖(十)為 RCEP 簽署國家分布圖。下列哪個國家並非上述協定的會員國之一？", "o": ["印度", "澳洲", "日本", "紐西蘭"], "a": 0, "e": "印度不是 RCEP 的成員國。", "rep": true, "img": "g4-q122", "imgnote": "", "fh": "", "maps": ["g4-map-rcep"], "chk": ""}, {"id": "g4-123", "no": 123, "c": "e6", "src": "114上翰林社會2上C卷 卷5 題組 (一) 2", "st": "考卷", "ctx": "「區域全面經濟夥伴協定（簡稱 RCEP）」是由東南亞國家協會發起簽署的自由貿易協定，其會員國範圍的人口高達 20 億人，占全球人口約 30%，成為目前世界最大的自由貿易協議，圖(十)為 RCEP 簽署國家分布圖。", "fig": "", "q": "承上題，簽署該協定的國家具有下列哪項國際貿易優勢？", "o": ["會員國間可以共同開採能源", "降低會員國間的進出口限制", "勞工往來會員國之間免簽證", "會員國須共同決定產品價格"], "a": 1, "e": "RCEP 讓會員國之間降低進出口限制、減免關稅。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-124", "no": 124, "c": "e3", "src": "114上翰林社會2上C卷 卷5 題組 (二) 3", "st": "考卷", "ctx": "", "fig": "", "q": "中國經濟改革開放之初，深圳成為第一個經濟特區，吸引外國資金投入發展經濟。用了 40 年的時間，深圳從一個名不見經傳的邊陲小漁村變成一個國際矚目的現代化大都市，外貿出口總額連續 20 多年居中國第一位，金融、科技與文創等產業十分興盛。文中文城市的位置具有下列何種特色？", "o": ["位長江出海口", "位於東南沿海", "東臨臺灣海峽", "鄰近中國首都"], "a": 1, "e": "深圳位於東南沿海的珠江口。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-125", "no": 125, "c": "e5", "src": "114上翰林社會2上C卷 卷5 題組 (二) 4", "st": "考卷", "ctx": "中國經濟改革開放之初，深圳成為第一個經濟特區，吸引外國資金投入發展經濟。用了 40 年的時間，深圳從一個名不見經傳的邊陲小漁村變成一個國際矚目的現代化大都市，外貿出口總額連續 20 多年居中國第一位，金融、科技與文創等產業十分興盛。", "fig": "", "q": "承上題，上述城市所在經濟帶，其經濟發展特色最可能包括下列哪一項？", "o": ["勞力充足且對外交通便利", "能源與礦產蘊藏十分豐富", "工資低廉以發展重工業為主", "連結中國沿海與內陸的樞紐"], "a": 0, "e": "東部經濟區的特色是勞力充足、對外交通便利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-126", "no": 126, "c": "e3", "src": "114上翰林社會2上C卷 卷6 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "根據調查，中國的外資企業投資金額全球數一數二，也是世界上重要原料進口國。外國企業投資中國的原因最可能為下列何者？", "o": ["各地皆有鐵路與高鐵", "政府鼓勵農民移入都市", "人口眾多且有低廉勞力", "高科技技術領先全球"], "a": 2, "e": "外國企業投資中國，是看中人口眾多、勞力低廉。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-127", "no": 127, "c": "e1", "src": "114上翰林社會2上C卷 卷6 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(一)是中國三級產業就業人口比例圖，則第一、二、三級產業，依序為何？", "o": ["甲、乙、丙", "丙、乙、甲", "甲、丙、乙", "丙、甲、乙"], "a": 1, "e": "丙下降是第一級、乙持平是第二級、甲上升是第三級。", "rep": false, "img": "g4-q127", "imgnote": "", "fh": "", "maps": ["g4-map-emp"], "chk": ""}, {"id": "g4-128", "no": 128, "c": "e3", "src": "114上翰林社會2上C卷 卷6 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國自 1980 年代起，陸續在沿海設立經濟特區，以吸引外資並促進在地的經濟發展，下列哪個城市的發展與經濟特區最相關？", "o": ["廣州", "上海", "深圳", "北京"], "a": 2, "e": "深圳是改革開放後設立的經濟特區。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-sez"], "chk": ""}, {"id": "g4-129", "no": 129, "c": "e1", "src": "114上翰林社會2上C卷 卷6 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國實施經濟改革開放後，第一級產業隨著經濟發展產生變化，關於其變化的說明，下列何者不符合現況？", "o": ["從事農業人口充足", "轉型為專業生產區", "以永續發展為目標", "開始推行生態農業"], "a": 0, "e": "中國產業結構改變，從事農業的人口減少，並不充足。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-130", "no": 130, "c": "e3", "src": "114上翰林社會2上C卷 卷6 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "早期中國在東南沿海設立經濟特區，主要是考量東南沿海地區具備哪些優勢條件？", "o": ["勞力、礦產", "原料、動力", "土地、技術", "交通、勞力"], "a": 3, "e": "東南沿海設特區的優勢是交通便利、勞力充足。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-131", "no": 131, "c": "e2", "src": "114上翰林社會2上C卷 卷6 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(二)為中國煤、鐵、石油的分布狀況。根據圖中資料，上述資源主要分布在哪個地形區？", "o": ["東北平原", "華北平原", "四川盆地", "長江中下游平原"], "a": 1, "e": "圖中煤、鐵、石油多集中在黃河中下游的華北平原。", "rep": false, "img": "g4-q131", "imgnote": "", "fh": "", "maps": ["g4-map-mineral"], "chk": ""}, {"id": "g4-132", "no": 132, "c": "e1", "src": "114上翰林社會2上C卷 卷6 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "近年中國內蒙古的酪農業發展穩健，相關企業相繼以先進設備提高品質，因此帶動內蒙古的農業經濟快速成長。以上現象可以用來說明中國農業轉型後的何種特色？", "o": ["為兼顧農產", "機械化耕作", "農產品的多樣化", "形成專業生產區"], "a": 3, "e": "內蒙古發展大規模酪農業，是形成專業生產區。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-133", "no": 133, "c": "e5", "src": "114上翰林社會2上C卷 卷6 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(三)為某旅行社製作的青藏鐵路沿線景點簡介圖，根據圖中內容判斷，該鐵路對於下列哪一經濟發展政策的推動最有幫助？", "o": ["東北振興", "中部崛起", "西部大開發", "東部率先發展"], "a": 2, "e": "青藏鐵路從格爾木到拉薩，有助於西部大開發。", "rep": false, "img": "g4-q133", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-134", "no": 134, "c": "e6", "src": "114上翰林社會2上C卷 卷6 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國政府近年積極拓展國際貿易，2020 年簽署區域全面經濟夥伴協定，該協定簽署後將對中國帶來何種影響？", "o": ["與美國的貿易往來更加頻繁", "可利用陸路與歐洲各國往來", "大量投資鄰近國家交通建設", "與會員國之間享有減免關稅"], "a": 3, "e": "RCEP 簽署後，中國與會員國之間享有關稅減免。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-135", "no": 135, "c": "e4", "src": "114上翰林社會2上C卷 卷6 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "臺灣某餐飲企業目前在全球共有 566 家門市，2007 年開始在中國經營，目前有 234 家直營門市、年營業額達新臺幣 63 億元。上述內容可以說明該企業投資中國主要的原因為何？", "o": ["在中國取得豐富原料", "中國勞動力十分充足", "中國有廣大消費潛力", "中國電子商務趨勢發展"], "a": 2, "e": "餐飲企業到中國開設大量門市，是看中中國廣大的消費潛力。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-136", "no": 136, "c": "e5", "src": "114上翰林社會2上C卷 卷6 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國的區域發展政策中，其中哪一項是為了解決礦產枯竭、工廠設備老舊的困境，所提出的區域計畫？", "o": ["東北振興", "中部崛起", "西部大開發", "東部率先發展"], "a": 0, "e": "解決礦產枯竭、設備老舊的是東北振興。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-region"], "chk": ""}, {"id": "g4-137", "no": 137, "c": "e5", "src": "114上翰林社會2上C卷 卷6 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(四)為中國四大經濟區，圖中哪個區域雖然商業發展最緩慢，但因為有豐富礦產，具有開發潛力？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "西部地區（丁）商業發展最緩慢，但礦產豐富，具開發潛力。", "rep": false, "img": "g4-q137", "imgnote": "", "fh": "", "maps": ["g4-map-region"], "chk": ""}, {"id": "g4-138", "no": 138, "c": "e1", "src": "114上翰林社會2上C卷 卷6 實戰模擬題 2", "st": "考卷", "ctx": "", "fig": "", "q": "王博士參加以中國現代農業轉型為主題的演講，下列哪個內容符合上述主題？", "o": ["蟲蟲危機：利用太陽能捕蟲燈抓捕田害蟲", "山牧季移：順應季節變化的畜牧產業活動", "南稻北麥：南部多種水稻，北部多種小麥", "在地好牛：內蒙古東部廣闊草原放牧牛群"], "a": 0, "e": "用捕蟲燈抓害蟲、減少農藥，是現代農業轉型（生態農業）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-139", "no": 139, "c": "e1", "src": "114上翰林社會2上C卷 卷6 實戰模擬題 3", "st": "考卷", "ctx": "", "fig": "", "q": "中國科學家在山東省一處農場，進行農業試驗，以「不減產、保生態、漲農價」為目標。上述目標與中國農業轉型的何種特色最相關？", "o": ["提高人均可耕地的面積", "利用科技提高農產量", "兼顧自然環境與產量", "各地生產具優勢農產品"], "a": 2, "e": "「不減產、保生態」兼顧自然環境與產量，是生態農業。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-140", "no": 140, "c": "e7", "src": "114上翰林社會2上C卷 卷6 實戰模擬題 4", "st": "考卷", "ctx": "", "fig": "表(一)：陸上——公路、鐵路／移動速度較慢／運量較少／時間較短；海上——海運／移動速度較快／運量較多／時間較長", "q": "表(一)為中國一帶一路政策中，陸上絲路與海上絲路間的比較，下列哪個選項不正確？", "o": ["交通方式", "移動速度", "運量", "時間"], "a": 1, "e": "陸上運輸（鐵路、公路）其實比海運快，表中「移動速度」寫反了。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-141", "no": 141, "c": "e6", "src": "114上翰林社會2上C卷 卷6 實戰模擬題 5", "st": "考卷", "ctx": "", "fig": "", "q": "近年中國大型企業對非洲的投資金額快速成長，尤其在中國政府推動「走出去」（going global）策略以及加入世界貿易組織（WTO）後，中國在非洲的貿易和投資活動更積極。中國政府鼓勵企業投資非洲的主要因素包括下列何者？", "o": ["勞動力的成本逐年提升", "希望取得更多礦產資源", "積極降低自然環境災害", "希望更快速研發技術"], "a": 1, "e": "中國企業投資非洲，是希望取得更多礦產資源。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-142", "no": 142, "c": "e7", "src": "114上翰林社會2上C卷 卷6 實戰模擬題 6", "st": "考卷", "ctx": "", "fig": "", "q": "中國 2013 年提出的一帶一路政策，影響地區廣大，為中國的國際貿易翻開嶄新的一頁。上述政策對中國的影響，不包括下列何者？", "o": ["與他國合作建設交通能源等基礎設施", "藉由強化基礎建設消化中國過剩產能", "開拓國際市場並得到穩定的能源供給", "降低中國大城市過度發展的汙染問題"], "a": 3, "e": "一帶一路不能降低中國大城市的汙染問題。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-143", "no": 143, "c": "e5", "src": "114上翰林社會2上C卷 卷6 實戰模擬題 7", "st": "考卷", "ctx": "", "fig": "", "q": "圖(五)為中國的四大經濟區。位於長江流域的武漢市，由於政府相關政策，目前以較低廉的工資及自然資源優勢吸引外資投入，近年經濟成長速度甚至超越沿海城市。武漢市應位於圖(五)中哪個區域？", "o": ["甲", "乙", "丙", "丁"], "a": 1, "e": "武漢位在長江中游，屬於中部經濟區（乙）。", "rep": false, "img": "g4-q143", "imgnote": "", "fh": "", "maps": ["g4-map-region"], "chk": ""}, {"id": "g4-144", "no": 144, "c": "e3", "src": "114上翰林社會2上C卷 卷6 題組 1", "st": "考卷", "ctx": "", "fig": "表(二)：都市化程度——1964 年 18.3%、1978 年 17.9%、1985 年 23.7%、1990 年 26.4%、2000 年 36.2%、2015 年 56.1%", "q": "中國於 1978 年實施了某項政策，吸引大量外國資金到中國投資設廠，表(二)為中國都市化程度變化。上文中提及的「某項政策」應為下列何者？", "o": ["轉型為科技化農業", "多條高速鐵路完工", "實施經濟改革開放", "都市的生育率提高"], "a": 2, "e": "1978 年實施經濟改革開放，吸引外資，都市化程度快速提高。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-145", "no": 145, "c": "e7", "src": "114上金安翰版社會2上A卷 第5次練習 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國一帶一路政策中的海線部分，沿著昔日鄭和出使西洋路線，闢建一條 21 世紀海上絲綢之路，由福建沿海經南海、麻六甲海峽、印度洋、紅海及地中海等。根據上述內容判斷，下列哪一洲不是該路線合作的國家？", "o": ["美洲", "非洲", "亞洲", "歐洲"], "a": 0, "e": "海上絲綢之路經亞洲、非洲到歐洲，不包括美洲。", "rep": true, "img": "g4-map-belt", "imgnote": "附圖以講義〈一帶一路路線示意圖〉代替", "fh": "", "maps": [], "chk": ""}, {"id": "g4-146", "no": 146, "c": "e3", "src": "114上金安翰版社會2上A卷 第5次練習 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國於 1980 年代起設立經濟特區，以出口為導向。右圖為某臺商對當時經濟特區的說法，由圖中內容判斷，最可能為下列何地？「我在特區投資設廠，主要擔任靠近中亞、西亞一帶……」", "o": ["深圳", "喀什", "廈門", "珠海"], "a": 1, "e": "靠近中亞、西亞的經濟特區是新疆喀什。", "rep": false, "img": "g4-q146", "imgnote": "", "fh": "", "maps": ["g4-map-sez"], "chk": ""}, {"id": "g4-147", "no": 147, "c": "e4", "src": "114上金安翰版社會2上A卷 第5次練習 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "早期外國企業是捧著錢到中國蓋工廠，現在則是捧著錢到中國蓋購物中心、連鎖商店及大賣場等。這種轉變是看中中國哪一項優勢？", "o": ["資本", "技術", "市場", "交通"], "a": 2, "e": "外國企業到中國蓋購物中心、賣場，是看中中國的市場。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-148", "no": 148, "c": "e2", "src": "114上金安翰版社會2上A卷 第5次練習 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國地大物博，蘊藏豐富的礦產資源，提供國家發展有利的條件。右圖中何地因煤、鐵、石油產量豐富，重工業發達？", "o": ["甲", "乙", "丙", "丁"], "a": 0, "e": "甲在華北、東北一帶，煤鐵石油豐富，重工業發達。", "rep": false, "img": "g4-q148", "imgnote": "", "fh": "", "maps": ["g4-map-mineral"], "chk": ""}, {"id": "g4-149", "no": 149, "c": "e8", "src": "114上金安翰版社會2上A卷 第5次練習 第 5 題", "st": "考卷", "ctx": "", "fig": "表：甲 斯里蘭卡、乙 義大利、丙 希臘、丁 德國", "q": "中國推動「一帶一路」政策至今，遭到許多國家的質疑及反對，右表中哪些國家因無力償還貸款，只好將港口租借給中國？", "o": ["甲乙", "甲丙", "乙丁", "丙丁"], "a": 1, "e": "斯里蘭卡（漢班托塔港）、希臘（皮雷埃夫斯港）都把港口交給中國經營。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-150", "no": 150, "c": "e3", "src": "114上金安翰版社會2上A卷 第5次練習 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "「中國經濟改革開放後，此地在於珠江口東側，接近香港，吸引大量外資投入，目前已由勞力密集型產業轉型為創新產業的發展重心。」上文是在描述下列哪一座城市？", "o": ["北京市", "上海市", "深圳市", "廣州市"], "a": 2, "e": "位於珠江口東側、接近香港的是深圳。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-sez"], "chk": ""}, {"id": "g4-151", "no": 151, "c": "e3", "src": "114上金安翰版社會2上A卷 第5次練習 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國的「經濟改革開放」政策歷經多年的發展，使中國已經成為世界經濟體系的一員。由右圖的產品可以判斷，下列何者是其所扮演的角色？", "o": ["世界研發中心", "世界金融中心", "世界工廠", "世界市場"], "a": 2, "e": "多種產品產量世界第一，中國扮演世界工廠的角色。", "rep": false, "img": "g4-q151", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-152", "no": 152, "c": "e3", "src": "114上金安翰版社會2上A卷 第5次練習 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國近年來積極發展工業，因此全球市場有一句俗語：「中國生產什麼產品，這種產品的市場價格就會下降。」依俗語內容推論，中國產品最具備下列哪項優勢？", "o": ["品質精良", "產品創新", "價格低廉", "時尚流行"], "a": 2, "e": "中國生產的產品會讓市場價格下降，代表中國產品價格低廉。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-153", "no": 153, "c": "e1", "src": "114上金安翰版社會2上A卷 第5次練習 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國為了兼顧糧食生產環境與產量的平衡，達到永續發展農業的目標，推動何種農業類型？", "o": ["集約農業", "精緻農業", "休閒農業", "生態農業"], "a": 3, "e": "兼顧生產環境與產量、達到永續發展，是生態農業。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-154", "no": 154, "c": "e5", "src": "114上金安翰版社會2上A卷 第5次練習 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "右列是中國的鐵路路網分布圖，可以看出中國的鐵路交通具有哪一項特色？", "o": ["中國鐵路主要分布在西半部", "中國鐵路系統已成環狀分布", "沙漠地區過於乾燥，無鐵路通行", "東半部的地理環境適合鐵路建築"], "a": 3, "e": "東半部地形平坦、人口多，適合鐵路建築，所以鐵路集中在東半部。", "rep": false, "img": "g4-q154", "imgnote": "", "fh": "", "maps": ["g4-map-rail"], "chk": ""}, {"id": "g4-155", "no": 155, "c": "e4", "src": "114上金安翰版社會2上A卷 第5次練習 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國實施經濟改革開放政策後，吸引外商進入，快速培養其經濟實力，下列何者是外商投資中國的調整方向？", "o": ["由第一級產業逐漸轉向第二級產業", "由第一級產業逐漸轉向第三級產業", "由第二級產業逐漸轉向第三級產業", "由第三級產業逐漸轉向第一級產業"], "a": 2, "e": "外商投資從第二級產業（製造業）逐漸轉向第三級產業（服務業）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-156", "no": 156, "c": "e3", "src": "114上金安翰版社會2上A卷 第5次練習 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國早期以製鞋、玩具等產業為主，近年吸引電腦、汽車、工業機械等製造業設廠，中國工業生產型態轉變，其原因為何？", "o": ["工資成本提高", "生產技術精進", "減少工業污染", "擴大生產產量"], "a": 1, "e": "工業從製鞋、玩具進步到電腦、汽車，是因為生產技術精進。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-157", "no": 157, "c": "e9", "src": "114上金安翰版社會2上A卷 第5次練習 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "右圖是近年上海市的最低工資的變化，此趨勢將可能使下列哪一種產業因成本高漲，選擇離開當地？", "o": ["汽車工業", "紡織工業", "資訊工業", "石化工業"], "a": 1, "e": "最低工資上漲，勞力密集的紡織工業成本高漲，會選擇離開。", "rep": false, "img": "g4-q157", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-158", "no": 158, "c": "e3", "src": "114上金安翰版社會2上A卷 第5次練習 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "「1980 年代，中國領導人推行『四個現代化』，以農業、工業、科技和國防作為發展目標，希望能促進經濟發展，尤其是東南沿海經濟特區的設立。」經濟特區主要是為了下列哪一因素而設立？", "o": ["吸引外資", "吸引原料", "吸引勞力", "吸引移民"], "a": 0, "e": "經濟特區主要是為了吸引外資。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-159", "no": 159, "c": "e9", "src": "114上金安翰版社會2上A卷 第5次練習 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "1980 年代，世界許多知名運動鞋普遍是「中國製造」，近年逐漸被「越南製造」取代。運動鞋品牌紛紛將代工廠撤離中國，主要與中國目前何種現象最有關？", "o": ["礦產原料枯竭", "工資成本提高", "電力嚴重不足", "民眾消費力提升"], "a": 1, "e": "運動鞋代工廠撤離中國，是因為中國工資成本提高。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-160", "no": 160, "c": "e4", "src": "114上金安翰版社會2上A卷 第5次練習 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "美國、日本、中國是世界三大經濟體，三國 GDP 的排名如右圖所示。圖中甲、乙、丙各自代表的國家為何？", "o": ["美國、日本、中國", "日本、美國、中國", "美國、中國、日本", "中國、美國、日本"], "a": 2, "e": "甲最高是美國，乙快速上升是中國，丙是日本。", "rep": false, "img": "g4-q160", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-161", "no": 161, "c": "e5", "src": "114上金安翰版社會2上A卷 第5次練習 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國在 1978 年啟動經濟體制改革，採取「讓部分地區率先富起來」，再帶動整體發展。此舉雖成功帶動經濟快速成長，但也造成何種問題？", "o": ["族群紛爭不斷", "通貨膨脹嚴重", "區域發展不均", "失業人口增加"], "a": 2, "e": "讓部分地區先富起來，造成區域發展不均。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-162", "no": 162, "c": "e7", "src": "114上金安翰版社會2上A卷 第6次練習 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國於 2013 年提出「一帶一路」政策。右圖是一帶一路主要路線，其中甲是絲綢之路經濟帶的起點，依據位置判斷，應是下列何者？", "o": ["重慶", "武漢", "北京", "西安"], "a": 3, "e": "絲綢之路經濟帶的起點是西安。", "rep": false, "img": "g4-q162", "imgnote": "", "fh": "", "maps": ["g4-map-belt"], "chk": ""}, {"id": "g4-163", "no": 163, "c": "e5", "src": "114上金安翰版社會2上A卷 第6次練習 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國近年來積極推動「西部大開發」，除了希望加速西部地區的經濟發展外，其最大目的是要將哪些資源輸出至東部？(甲)鐵 (乙)金 (丙)煤 (丁)石油 (戊)銅", "o": ["甲乙丙", "甲乙丁", "甲丙丁", "丙丁戊"], "a": 2, "e": "西部大開發把煤、石油、天然氣輸往東部（西氣東輸、西電東送）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-164", "no": 164, "c": "e2", "src": "114上金安翰版社會2上A卷 第6次練習 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國的工業發展「北重南輕」，意即北部以重工業為主，南部以輕工業為主。此種工業分布的特色，主要與下列哪一項工業區位要素關係最密切？", "o": ["原料", "勞工", "交通", "資金"], "a": 0, "e": "北重南輕，和礦產原料的分布有關。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-mineral"], "chk": ""}, {"id": "g4-165", "no": 165, "c": "e6", "src": "114上金安翰版社會2上A卷 第6次練習 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "隨著交通運輸的進步，全球的國際貿易更加發達。右圖是 2023 年世界前 5 大貿易總額國家，其中甲、乙應分別是哪兩個國家？", "o": ["中國、美國", "美國、荷蘭", "日本、德國", "德國、中國"], "a": 0, "e": "2023 年貿易總額第一是中國、第二是美國。", "rep": false, "img": "g4-q165", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-166", "no": 166, "c": "e8", "src": "114上金安翰版社會2上A卷 第6次練習 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "下列亞洲哪一個位在中國「21 世紀海上絲綢之路」的主要路線上，想藉由中國的投資促進國內經濟的發展，卻因無力償還大額債務被迫出租港口 99 年供中國使用？", "o": ["新加坡", "土耳其", "斯里蘭卡", "馬來西亞"], "a": 2, "e": "斯里蘭卡無力償還債務，被迫出租漢班托塔港 99 年。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-167", "no": 167, "c": "e5", "src": "114上金安翰版社會2上A卷 第6次練習 第 12 題", "st": "考卷", "ctx": "", "fig": "表：都市化程度前四名——上海 88.1%、北京 86.5%、天津 83.2%、廣東 70.7%；最後四名——西藏 31.1%、貴州 47.5%、甘肅 47.7%、雲南 47.8%", "q": "2018 年中國都市化程度各行政區的排名如右表。表內呈現差異極大的現象，下列何者最可能是中國政府對此提出的對策？", "o": ["東北振興", "中部崛起", "西部大開發", "設經濟特區"], "a": 2, "e": "都市化程度前四名在東部、後四名在西部，對策是西部大開發。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-168", "no": 168, "c": "e3", "src": "114上金安翰版社會2上A卷 第6次練習 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國於 1978 年後實施經濟改革開放，利用其優勢成立經濟特區。當時臺商阿成至中國投資，最可能會選擇何種產業來發展較有優勢？", "o": ["小聰明軟體工業", "跑得快製鞋工業", "飛得高航空工業", "硬梆梆鋼鐵工業"], "a": 1, "e": "經濟特區初期以勞力密集產業為主，製鞋工業最有優勢。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-169", "no": 169, "c": "e4", "src": "114上金安翰版社會2上A卷 第6次練習 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "右列是中國近年來興起的購物節活動，在民眾的熱烈回應下，屢屢創下驚人的交易金額。由此可得知下列何項訊息？「阿里巴巴光棍節雙11的營業額、電商京東的618周年慶……」", "o": ["中國的外匯存底世界第一", "中國是世界最大的代工國", "中國是世界第一的投資大國", "中國人民的消費力十分驚人"], "a": 3, "e": "購物節交易金額驚人，代表中國人民消費力十分驚人。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-170", "no": 170, "c": "e5", "src": "114上金安翰版社會2上A卷 第6次練習 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國依目前經濟社會發展趨勢，畫分為四大經濟區：東部、中部、西部和東北地區，並訂定不同的發展政策，其主要目標是為了解決哪一項問題？", "o": ["人口素質低落", "人口數量過多", "交通建設不足", "區域發展差異"], "a": 3, "e": "劃分四大經濟區，目的是解決區域發展差異。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-171", "no": 171, "c": "e9", "src": "114上金安翰版社會2上A卷 第6次練習 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "臺灣的鴻海精密集團是全球最大電子代工廠，主要工廠集中在中國，如深圳、鄭州等都市。近年該集團的工業生產逐漸朝向機械自動化發展，此工業生產的變化，將對中國經濟發展產生何種衝擊？", "o": ["就業機會減少", "電力需求降低", "生產技術退步", "生態環境破壞"], "a": 0, "e": "工廠機械自動化，需要的工人變少，就業機會減少。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-172", "no": 172, "c": "e3", "src": "114上金安翰版社會2上A卷 第6次練習 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "2025 年，美國總統川普大打關稅戰，美國對從中國進口的商品加重關稅。有人認為此舉不見得對美國人民有利，因為美國人民常以較高的價格購買其他國家生產的產品。上述的說法反映了中國商品有何項優勢存在？", "o": ["品質良好，售後服務佳", "用料實在無使用的年限", "產出成本低，使用者眾", "國力強，產品行銷世界"], "a": 2, "e": "美國人改買其他國家產品要付更高價格，代表中國產品成本低、價格便宜。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-173", "no": 173, "c": "e1", "src": "114上金安翰版社會2上A卷 第6次練習 第 21 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國人口眾多，糧食需求大，為了能供應足夠糧食，也從生產技術著手，右圖利用無人機噴灑農藥。這是屬於下列哪一種農業？", "o": ["有機農業", "休閒農業", "精緻農業", "科技化農業"], "a": 3, "e": "利用無人機噴灑農藥，屬於科技化農業。", "rep": false, "img": "g4-q173", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-174", "no": 174, "c": "e6", "src": "114上金安翰版社會2上A卷 第6次練習 第 22 題", "st": "考卷", "ctx": "", "fig": "", "q": "右圖為近年中國進口、出口及貿易總額統計，從圖判斷中國的國際貿易，可得到下列何項事實？", "o": ["進口多為工業原料", "出口多為工業產品", "中國輕重工業發達", "中國為貿易出超國"], "a": 3, "e": "出口值長年高於進口值，中國是貿易出超國。", "rep": false, "img": "g4-q174", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-175", "no": 175, "c": "e2", "src": "114上金安翰版社會2上A卷 第6次練習 第 23 題", "st": "考卷", "ctx": "", "fig": "", "q": "環境問題對中國居民的生活造成極大的衝擊，也影響全球的生態。大量使用化石燃料造成中國空氣品質變差，其中燃煤更是導致霧霾的主因。依據煤礦分布及重工業發展地區判斷，下列哪個地區的霧霾情形可能最為嚴重？", "o": ["華北平原", "四川盆地", "長江三角洲", "珠江三角洲"], "a": 0, "e": "華北平原煤礦多、重工業發達，霧霾最嚴重。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-176", "no": 176, "c": "e1", "src": "114上金安翰版社會2上A卷 第6次練習 第 24 題", "st": "考卷", "ctx": "", "fig": "", "q": "右列為中國三級產業就業人口比例統計圖，圖中顯示第一級產業就業人口逐年下降，其主要原因不包括下列何者？", "o": ["山地多平原狹小", "降水量分布不均", "完全機械化耕種", "產業結構的轉型"], "a": 2, "e": "中國並沒有完全機械化耕種，大部分平原仍靠人力。", "rep": false, "img": "g4-q176", "imgnote": "", "fh": "", "maps": ["g4-map-emp"], "chk": ""}, {"id": "g4-177", "no": 177, "c": "e4", "src": "114上金安翰版社會2上A卷 第6次練習 題組 (一) 26", "st": "考卷", "ctx": "", "fig": "", "q": "上海迪士尼樂園是中國境內繼香港之後所興建的第二座迪士尼樂園，其位於上海市浦東新區的川沙新鎮。上海迪士尼樂園的成立，主要是看中中國的消費市場龐大，上海位於右圖中何處？", "o": ["甲", "乙", "丙", "丁"], "a": 0, "e": "上海位在長江出海口，是圖中的甲。", "rep": false, "img": "g4-q177", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-178", "no": 178, "c": "e3", "src": "114上金安翰版社會2上A卷 第6次練習 題組 (一) 27", "st": "考卷", "ctx": "上海迪士尼樂園是中國境內繼香港之後所興建的第二座迪士尼樂園，其位於上海市浦東新區的川沙新鎮。上海迪士尼樂園的成立，主要是看中中國的消費市場龐大，", "fig": "", "q": "承上題，香港迪士尼樂園所販售的玩具商品，大部分商品在生產地的標籤上均為 MIC，意謂為「中國製造」，這些商品會在中國生產的主因為下列何者？", "o": ["原料成本較低廉", "生產技術較先進", "對外交通較便利", "勞工工資較低廉"], "a": 3, "e": "玩具在中國生產，主因是勞工工資低廉。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-179", "no": 179, "c": "e1", "src": "講義第 45 頁 學習即時通 4-1 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "右圖為中國三級產業從業人口比例變化圖，依據圖中資訊判斷，其中甲、乙、丙依序分別代表何種產業？", "o": ["第一級、第二級、第三級", "第二級、第三級、第一級", "第三級、第二級、第一級", "第二級、第一級、第三級"], "a": 2, "e": "丙由最高持續下降是第一級、乙平緩是第二級、甲上升到最高是第三級，所以甲、乙、丙是第三、二、一級。", "rep": false, "img": "g4-q179", "imgnote": "", "fh": "", "maps": ["g4-map-emp"], "chk": ""}, {"id": "g4-180", "no": 180, "c": "e1", "src": "講義第 45 頁 學習即時通 4-1 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "右圖是世界排名前幾名國家的人均可耕地面積比較圖，其中何者最可能是中國的資料？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "中國人均可耕地只有 0.08 公頃，是丁。", "rep": false, "img": "g4-q180", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-181", "no": 181, "c": "e1", "src": "講義第 45 頁 學習即時通 4-1 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "中國自古以農立國，農業可說是中國發展的根本，但隨著社會環境轉變，中國現代農業發展面臨許多挑戰。這些挑戰最可能包括下列何者？", "o": ["農業勞力不足", "農地的品質下降", "農業土地轉作他用", "農業技術較為落後"], "a": 2, "e": "農業的挑戰是工商業發展後，農業土地轉作他用。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-182", "no": 182, "c": "e1", "src": "講義第 45 頁 學習即時通 4-1 第 4 題", "st": "講義", "ctx": "", "fig": "", "q": "中國隨著耕地面積減少，加上近年糧食需求量不減反增，使其農業發展面臨巨大挑戰。該國為了因應上述挑戰進行農業轉型，其中不包括下列何者？", "o": ["增加耕作面積", "改採機械化耕作", "發展生態農業", "設立專業生產區"], "a": 0, "e": "耕地減少，不可能靠增加耕作面積解決；轉型方式是機械化、生態農業、專業生產區。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-183", "no": 183, "c": "e2", "src": "講義第 47 頁 學習即時通 4-2 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "中國的工業發展有南北差異，形成「北重南輕」的局面，影響此一分布型態最主要的因素為何？", "o": ["勞力素質", "資金多寡", "市場規模", "原料分布"], "a": 3, "e": "北重南輕最主要是原料（礦產）分布的影響。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-mineral"], "chk": "講義第 47 頁不在 PDF 中，無法對照原題"}, {"id": "g4-184", "no": 184, "c": "e3", "src": "講義第 47 頁 學習即時通 4-2 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(一)為中國經濟特區分布圖，其中甲、乙兩處經濟特區成立的主要優勢區位條件為何？", "o": ["勞力素質優良", "工礦原料豐富", "鄰近邊境貿易", "科技研發領先"], "a": 2, "e": "喀什鄰近中亞、海南鄰近東南亞，都有利於邊境貿易。", "rep": false, "img": "g4-map-sez", "imgnote": "附圖以講義〈經濟特區分布圖〉代替（甲喀什不在此圖內）", "fh": "", "maps": [], "chk": "講義第 47 頁不在 PDF 中，無法對照原題"}, {"id": "g4-185", "no": 185, "c": "e5", "src": "講義第 47 頁 學習即時通 4-2 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "表(一)為中國四大經濟區的發展策略，下列配對何者正確？", "o": ["甲—東北振興", "乙—西部大開發", "丙—中部崛起", "丁—中部崛起"], "a": 2, "e": "四大經濟區與政策的正確配對是：西部—西部大開發、東北—東北振興、中部—中部崛起、東部—東部率先發展。", "rep": false, "img": "g4-map-region", "imgnote": "附圖以講義〈四大經濟區分布圖〉代替", "fh": "", "maps": [], "chk": "講義第 47 頁不在 PDF 中，無法對照原題"}, {"id": "g4-186", "no": 186, "c": "e5", "src": "講義第 48 頁 學習即時通 4-3 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "右圖是中國實施經濟改革開放措施之後出現了明顯的區域差異，圖中是依其發展畫分的四個區域，其中哪一地區為人口稠密、勞力密集，是中國最先發展的地區？", "o": ["甲", "乙", "丙", "丁"], "a": 1, "e": "人口稠密、勞力密集、最先發展的是東部沿海地區（乙）。", "rep": false, "img": "g4-q186", "imgnote": "", "fh": "", "maps": ["g4-map-region"], "chk": ""}, {"id": "g4-187", "no": 187, "c": "e4", "src": "講義第 48 頁 學習即時通 4-3 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "右圖是 1960～2024 年中國、美國及日本的 GDP 變遷情形，下列何者最可能是中國的資料？", "o": ["甲", "乙", "丙", "無法判斷"], "a": 1, "e": "中國 GDP 在 2000 年後快速攀升，是乙。", "rep": false, "img": "g4-q187", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-188", "no": 188, "c": "e7", "src": "講義第 49 頁 學習即時通 4-3 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "中國於 2013 年提出一帶一路政策，而右圖為該政策的兩條主要路線示意圖，希望透過海上及陸地兩條路線增加與他國的經貿往來，並消化中國過剩的工業生產能量。根據圖中內容判斷，下列哪一地區受到該政策影響最小？", "o": ["中亞", "歐洲", "西亞", "北美洲"], "a": 3, "e": "一帶一路連接亞、歐、非，北美洲受影響最小。", "rep": false, "img": "g4-q188", "imgnote": "", "fh": "", "maps": ["g4-map-belt"], "chk": ""}, {"id": "g4-189", "no": 189, "c": "e7", "src": "講義第 49 頁 學習即時通 4-3 第 4 題", "st": "講義", "ctx": "", "fig": "", "q": "中國與部分亞洲及歐洲國家合作，推出中歐班列，該路線行駛於中國到歐洲之間，多由中國新疆出境，出境後最可能進入的是下列哪一地區？", "o": ["中亞", "南亞", "東北亞", "東南亞"], "a": 0, "e": "中歐班列由新疆出境，最先進入中亞。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-belt"], "chk": ""}, {"id": "g4-190", "no": 190, "c": "e6", "src": "講義第 49 頁 學習即時通 4-3 第 5 題", "st": "講義", "ctx": "", "fig": "", "q": "近年中國積極鼓勵國內的企業到外國進行投資，其主要目的不包括下列何者？", "o": ["利於礦產資源的取得", "可獲得他國產業技術", "便於進入歐美的市場", "增加國內人口的移出"], "a": 3, "e": "企業對外投資的目的是資源、技術、市場，不是讓人口移出。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-191", "no": 191, "c": "e1", "src": "講義第 51 頁 會考學力診斷 基礎題 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "水源是發展農業活動不可或缺的重要因素，中國主要農業區中，水資源相對缺乏的地區多屬於下列何種氣候區的範圍？", "o": ["高地氣候區", "熱帶季風氣候區", "溫帶季風氣候區", "副熱帶季風氣候區"], "a": 2, "e": "中國北方屬溫帶季風氣候區，水資源相對缺乏。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-192", "no": 192, "c": "e1", "src": "講義第 51 頁 會考學力診斷 基礎題 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "老師請同學針對中國現代農業發展的狀況進行說明，下列哪一位同學的說法與實際情形最相符？", "o": ["阿國：人均可耕地面積低於世界平均", "小芬：東南沿海地區水資源最為缺乏", "小宣：由集約耕作模式轉朝粗放經營", "阿玲：受自然環境影響改以自用為主"], "a": 0, "e": "中國人均可耕地面積低於世界平均。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-193", "no": 193, "c": "e1", "src": "講義第 51 頁 會考學力診斷 基礎題 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "中國隨著耕地面積減少，加上近年糧食需求量不減反增，傳統活動陸續轉型，其中哪一地區採大規模機械化的耕作模式，生產水稻、小麥等糧食作物？", "o": ["東北平原", "青藏高原", "塔里木盆地", "內蒙古高原"], "a": 0, "e": "東北平原採大規模機械化耕作，生產糧食作物。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-194", "no": 194, "c": "e2", "src": "講義第 51 頁 會考學力診斷 基礎題 第 4 題", "st": "講義", "ctx": "", "fig": "", "q": "礦產資源對一地區工業活動的發展影響甚大，圖(一)哪一地區附近因擁有豐富礦產資源，重工業相對發達？", "o": ["甲", "乙", "丙", "丁"], "a": 0, "e": "東北（甲）礦產豐富，重工業相對發達。", "rep": false, "img": "g4-q194", "imgnote": "", "fh": "", "maps": ["g4-map-mineral"], "chk": ""}, {"id": "g4-195", "no": 195, "c": "e3", "src": "講義第 51 頁 會考學力診斷 基礎題 第 5 題", "st": "講義", "ctx": "", "fig": "", "q": "中國實施經濟改革開放後，陸續成立數個經濟特區，其中哪一個經濟特區位於內陸的新疆維吾爾自治區，是中國與中亞地區國家貿易往來的重要基地之一？", "o": ["廈門", "喀什", "海南", "深圳"], "a": 1, "e": "位於新疆、與中亞貿易往來的經濟特區是喀什。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-sez"], "chk": ""}, {"id": "g4-196", "no": 196, "c": "e5", "src": "講義第 51 頁 會考學力診斷 基礎題 第 6 題", "st": "講義", "ctx": "", "fig": "", "q": "「中國經濟有顯著的區域差異，其中中部地區因位置的關係，發展不如東部地區，因此中國提出『中部崛起』政策，以豐富的煤、糧食及較低廉工資吸引外資進入。」依據位置判斷，上述政策的實施區包括下列何者？", "o": ["上海", "撫順", "深圳", "武漢"], "a": 3, "e": "中部崛起的範圍包括湖北武漢。上海、深圳在東部，撫順在東北。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-region"], "chk": ""}, {"id": "g4-197", "no": 197, "c": "e4", "src": "講義第 51 頁 會考學力診斷 基礎題 第 7 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(二)是 1960～2024 年中國、美國、日本 GDP 變化圖，其中甲、乙、丙指的國家為何？", "o": ["甲：中國、乙：日本、丙：美國", "甲：中國、乙：美國、丙：日本", "甲：美國、乙：中國、丙：日本", "甲：日本、乙：美國、丙：中國"], "a": 2, "e": "甲最高是美國、乙快速上升是中國、丙是日本。", "rep": false, "img": "g4-q197", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-198", "no": 198, "c": "e3", "src": "講義第 51 頁 會考學力診斷 基礎題 第 8 題", "st": "講義", "ctx": "", "fig": "", "q": "中國自 1978 年實施經濟改革開放政策後，吸引許多外國企業前往當地投資，依據時間先後的順序，下列哪一種產業外資前往當地投資的時間最早？", "o": ["家電產業", "汽車工業", "紡織工業", "高科技業"], "a": 2, "e": "改革開放初期外資先投資勞力密集的紡織工業。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-199", "no": 199, "c": "e4", "src": "講義第 52 頁 會考學力診斷 基礎題 第 9 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(三)是小華在某網路上見到的新聞標題，此一現象可以用來輔助說明該國家所具有的何種特徵？「中國人不想買，黃金銷量大衰退」", "o": ["國土面積廣大", "勞工薪資低廉", "消費潛力驚人", "農業產量增加"], "a": 2, "e": "中國人買黃金的意願影響全球黃金銷量，說明中國消費潛力驚人。", "rep": false, "img": "g4-q199", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-200", "no": 200, "c": "e7", "src": "講義第 52 頁 會考學力診斷 基礎題 第 10 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(四)是中國部分一帶一路路線的示意圖，其中甲都市是絲綢之路經濟帶的起點，依據位置判斷，其最可能是中國哪一城市？", "o": ["上海市", "北京市", "廣州市", "西安市"], "a": 3, "e": "絲綢之路經濟帶的起點是西安。", "rep": true, "img": "g4-q200", "imgnote": "", "fh": "", "maps": ["g4-map-belt"], "chk": ""}, {"id": "g4-201", "no": 201, "c": "e7", "src": "講義第 52 頁 會考學力診斷 基礎題 第 11 題", "st": "講義", "ctx": "", "fig": "", "q": "2013 年中國提出「一帶一路」的經濟政策，其中「一帶」全名為「絲綢之路經濟帶」，該路線是經由中國西部地區聯繫海外國家，其中聯繫的地區不包括何地？", "o": ["中亞", "西亞", "歐洲", "美洲"], "a": 3, "e": "絲綢之路經濟帶經中亞、西亞通往歐洲，不包括美洲。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-belt"], "chk": ""}, {"id": "g4-202", "no": 202, "c": "e6", "src": "講義第 52 頁 會考學力診斷 基礎題 第 12 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(五)是 2024 年世界前四大貿易總額國家的貿易往來數值，其中何者應為中國的資料？", "o": ["甲", "乙", "丙", "丁"], "a": 0, "e": "中國是世界貿易總額第一的國家，是甲。", "rep": false, "img": "g4-q202", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-203", "no": 203, "c": "e5", "src": "講義第 52 頁 會考學力診斷 精熟題 第 13 題", "st": "講義", "ctx": "", "fig": "", "q": "每年農曆春節前後，中國有數億離鄉工作的人口，藉鐵、公路往返於家鄉與工作地點間，龐大人潮造成交通壅塞，使政府運輸部門如臨大敵，此現象稱為「春運」。根據上述，若以中國四大經濟區區分，春節前返鄉人潮移動方向以何者為最大宗？", "o": ["西部地區→中部地區", "中部地區→西部地區", "東部地區→中部地區", "西部地區→東北地區"], "a": 2, "e": "春節前在東部工作的人返回中部家鄉，以東部→中部最多。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-region"], "chk": ""}, {"id": "g4-204", "no": 204, "c": "e5", "src": "講義第 52 頁 會考學力診斷 精熟題 第 14 題", "st": "講義", "ctx": "", "fig": "", "q": "1990 年代初期，臺灣某廠商為開拓海外市場，決定在中國設置生產據點，該廠商選擇在長江三角洲附近地區設廠，他表示此地交通便利，利於產品外銷到其他國家，又可兼顧中國龐大的內銷市場。上述設廠地點最可能為下列哪一城市附近？", "o": ["武漢", "上海", "拉薩", "北京"], "a": 1, "e": "長江三角洲、交通便利、可兼顧內銷，最可能是上海。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-205", "no": 205, "c": "e3", "src": "講義第 52 頁 會考學力診斷 精熟題 第 15 題", "st": "講義", "ctx": "", "fig": "", "q": "中國政府宣布近期要在甲地推動的計畫，其目標包括：「推動西部開發、帶動經濟發展；促進族群融合，強化與鄰近的中亞國家之貿易，藉以達到歐亞大陸經濟整合」。依據上述判斷，若將甲地以灰色色塊表示，下列何圖較符合？", "o": ["新疆灰色", "西藏灰色", "內蒙古灰色", "東北灰色"], "a": 0, "e": "推動西部開發、加強與中亞貿易，甲地應是新疆。", "rep": false, "img": "g4-q205", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-206", "no": 206, "c": "e1", "src": "講義第 53 頁 會考學力診斷 精熟題 第 16 題", "st": "講義", "ctx": "", "fig": "", "q": "因人口及產業發展導致的汙染以及過度捕撈，使長江生物完整性指數已達到最差的「無魚」等級，中國為改善此現象，提出十年的禁漁計畫，希望到 2030 年計畫截止時，長江魚類資源可恢復提升。上述最適合說明中國農業何種轉型的方向？", "o": ["專業化生產", "機械化生產", "使環境永續", "大規模生產"], "a": 2, "e": "十年禁漁讓長江魚類資源恢復，是讓環境永續。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-207", "no": 207, "c": "e5", "src": "講義第 53 頁 會考學力診斷 精熟題 第 17 題", "st": "講義", "ctx": "", "fig": "", "q": "鐵路是長途運輸的重要工具，依常理鐵路網絡密度愈高的地區，其產業發展程度亦高，若以此標準來判斷中國的經濟發展情形，圖(六)中哪一地區的經濟發展可能相對較差？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "丁是西部地區，鐵路密度最低，經濟發展相對較差。", "rep": false, "img": "g4-q207", "imgnote": "", "fh": "", "maps": ["g4-map-region", "g4-map-rail"], "chk": ""}, {"id": "g4-208", "no": 208, "c": "e5", "src": "講義第 53 頁 會考學力診斷 精熟題 第 18 題", "st": "講義", "ctx": "", "fig": "", "q": "2003 年起，中國在某地區實施右列中多項振興經濟措施：(1)更新昔日重工業工廠老舊設施或進行工業升級；(2)加強與俄羅斯、北韓邊界地區的經貿合作；(3)進行礦業、林業等資源型都市的轉型。依其內容判斷，該地最可能是中國哪一經濟區？", "o": ["西部地區", "東部地區", "中部地區", "東北地區"], "a": 3, "e": "更新重工業設施、與俄羅斯和北韓合作、資源型都市轉型，是東北地區。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-region"], "chk": ""}, {"id": "g4-209", "no": 209, "c": "e1", "src": "講義第 53 頁 會考學力診斷 精熟題 第 19 題", "st": "講義", "ctx": "", "fig": "", "q": "這個地區昔日以畜牧業為主，近年因中國民眾對肉、乳的需求量增加，其經營方式由小規模牧場轉型為大規模的專業化生產，是中國重要乳製品供應地。上述地區應位於圖(七)中何處？", "o": ["甲", "乙", "丙", "丁"], "a": 0, "e": "昔日畜牧、轉型為大規模乳製品專業生產區的是內蒙古（甲）。", "rep": false, "img": "g4-q209", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-210", "no": 210, "c": "e3", "src": "講義第 53 頁 會考學力診斷 精熟題 第 20 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(八)是世界 500 強企業總部所在國家的統計，依據圖中內容判斷，這段期間成長最快速的國家具有的產業發展優勢為何？", "o": ["進步的技術與優質的勞工", "廉價的勞工與廣大的市場", "便捷的交通與開明的政治", "充足的動力與豐富的礦產"], "a": 1, "e": "中國 500 強企業數量成長最快，優勢是廉價的勞工與廣大的市場。", "rep": false, "img": "g4-q210", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-211", "no": 211, "c": "e3", "src": "講義第 53 頁 會考學力診斷 精熟題 第 21 題", "st": "講義", "ctx": "", "fig": "", "q": "在《沒有中國製造的一年》一書中，作者寫出在某個契機下，她思考『沒有中國我們曾怎樣？』結論，她面臨到的狀況可能挑不到小孩的聖誕禮物、必須花更多預算購買日用品等。導致上文中情形產生的主要因素為何？", "o": ["中國勞工薪資低廉", "中國國土面積廣大", "中國對外交通便利", "中國生產技術優異"], "a": 0, "e": "沒有中國製造的商品會變貴，主因是中國勞工薪資低廉。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-212", "no": 212, "c": "e3", "src": "講義第 53 頁 會考學力診斷 精熟題 第 22 題", "st": "講義", "ctx": "", "fig": "", "q": "「Made in China」深入世界每個角落。根據統計，全世界每四雙襪子，至少有一雙是中國生產；70% 玩具是中國製造……。上文說明中國經濟發展的哪一項特性？", "o": ["工業的分布不均", "工業產品質佳", "世界工廠的地位", "世界市場的角色"], "a": 2, "e": "大量日用品由中國生產，說明中國世界工廠的地位。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-213", "no": 213, "c": "e7", "src": "講義第 54 頁 會考學力診斷 精熟題 第 23 題", "st": "講義", "ctx": "", "fig": "", "q": "中歐班列是指中國與其他國家進行合作的鐵路路線，該路線沿著「一帶」政策的路線前進，為減少作業時間和物流費用，實施統一運單的方式，此舉使貨物運輸組織在運送時大幅提升效率。上文提及的鐵路路線，經過的地區包含下列何者？", "o": ["日本", "臺灣", "南韓", "哈薩克"], "a": 3, "e": "中歐班列經過中亞的哈薩克。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-belt"], "chk": ""}, {"id": "g4-214", "no": 214, "c": "e6", "src": "講義第 54 頁 會考學力診斷 精熟題 第 24 題", "st": "講義", "ctx": "", "fig": "", "q": "中國為擴大其經濟版圖，積極與各國簽訂自由貿易協定，其中 2020 年簽署的「區域全面經濟夥伴協定」已於 2022 年 1 月 1 日生效。簽署上述協定的國家主要涵蓋圖(九)中哪兩大洲？", "o": ["甲乙", "甲丁", "乙丙", "戊己"], "a": 1, "e": "RCEP 主要涵蓋亞洲（甲）和大洋洲（丁）。", "rep": false, "img": "g4-q214", "imgnote": "", "fh": "", "maps": ["g4-map-rcep"], "chk": ""}, {"id": "g4-215", "no": 215, "c": "e7", "src": "講義第 54 頁 會考學力診斷 精熟題 第 25 題", "st": "講義", "ctx": "", "fig": "", "q": "中國一帶一路政策中的海線部分，是希望沿著昔日鄭和出使西洋的路線，闢建一條新的 21 世紀海上絲綢之路，其路線由福建沿海出發後經過南海、麻六甲海峽、印度洋、紅海及地中海等。根據上述內容判斷，下列何者不是該路線合作的國家？", "o": ["希臘", "印度", "肯亞", "北韓"], "a": 3, "e": "海上絲綢之路經南海、印度洋、紅海、地中海，不經過北韓。", "rep": false, "img": "g4-map-belt", "imgnote": "附圖以講義〈一帶一路路線示意圖〉代替", "fh": "", "maps": [], "chk": ""}, {"id": "g4-216", "no": 216, "c": "e3", "src": "講義第 54 頁 歷屆會考題 第 26 題", "st": "講義", "ctx": "", "fig": "", "q": "中國某一座跨海大橋於 2018 年完工，其連結了中國兩個特別行政區及一個經濟特區，可縮短往來三地的距離，及強化三地經濟社會的交流。上述跨海大橋應位於下列哪條河川的出海口？", "o": ["珠江", "長江", "海河", "黃河"], "a": 0, "e": "港珠澳大橋連接香港、澳門與珠海，位在珠江口。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-217", "no": 217, "c": "e5", "src": "講義第 54 頁 歷屆會考題 第 27 題", "st": "講義", "ctx": "", "fig": "表：外商投資總額前四名——江蘇 18.89%、廣東 15.64%、上海 13.43%、浙江 6.92%；後四名——西藏 0.03%、青海 0.11%、寧夏 0.14%、新疆 0.19%", "q": "右表為中國 2006 至 2015 年外商投資總額最多和最少的四個行政區。根據表中呈現外商投資的空間差異，下列哪一項策略最能夠改善表中所呈現的問題？", "o": ["促進東北老舊工業區轉型", "與東協簽署自由貿易協定", "取消一胎化的計畫生育政策", "推動與中亞國家的邊境貿易"], "a": 3, "e": "外資集中東部、西部最少，推動與中亞的邊境貿易可以改善西部。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-218", "no": 218, "c": "e7", "src": "講義第 54 頁 歷屆會考題 第 28 題", "st": "講義", "ctx": "", "fig": "", "q": "「2016 年初，滿載商品的貨運列車從中國浙江義烏出發，經西安、蘭州和烏魯木齊等城市後，駛往伊朗德黑蘭，歷時 14 天完成首航，再現古絲路的輝煌。」這班列車在駛離中國後，最可能途經下列何地？", "o": ["中亞", "南亞", "東歐", "東南亞"], "a": 0, "e": "中歐班列駛離新疆後最先經過中亞。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-belt"], "chk": ""}, {"id": "g4-219", "no": 219, "c": "e5", "src": "講義第 54 頁 歷屆會考題 第 29 題", "st": "講義", "ctx": "", "fig": "", "q": "中國於 1970 年代末推動的改革開放政策，帶動經濟快速成長，但是卻加深區域發展失衡現象。下列關於中國的新聞報導，何者最能反映中國區域發展不均的現象？", "o": ["今年出現的多起沙塵暴，已直接威脅北京、上海及南京等大都市", "推動海上絲路計畫，發展從中國沿海港口經印度洋至歐洲的航線", "農曆春節將湧現數億人次返鄉人潮，堪稱地表最大規模的人口移動", "南方近年降雨減少，旱象環生，南水北調將威脅南方用水的供應量"], "a": 2, "e": "春運數億人返鄉，反映區域發展不均（沿海工作、內陸家鄉）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-220", "no": 220, "c": "e7", "src": "講義第 55 頁 歷屆會考題 第 30 題", "st": "講義", "ctx": "", "fig": "", "q": "中國實施「一帶一路」政策規畫了許多經濟走廊，圖(十)為部分經濟走廊示意圖。其中有一條的規畫目的，除可降低從波斯灣運石油至中國須經印尼、馬來西亞間海峽及南海的風險外，也兼具促進中國西部地區與西亞、南亞國家的能源和貿易往來，此經濟走廊最可能為圖中何者？", "o": ["甲", "乙", "丙", "丁"], "a": 2, "e": "中巴經濟走廊從新疆經巴基斯坦到瓜達爾港，可避開麻六甲海峽，是丙。", "rep": false, "img": "g4-q220", "imgnote": "", "fh": "", "maps": ["g4-map-belt"], "chk": ""}, {"id": "g4-221", "no": 221, "c": "e7", "src": "講義第 55 頁 圖表判讀題組 第 31 題", "st": "講義", "ctx": "", "fig": "", "q": "中國於 2013 年提出「一帶一路」政策，利用此政策加強與周邊國家的經濟合作，同時解決中國經濟快速發展下出現工業產能過剩的情形，圖(十一)為該政策的兩條主要路線。圖(十一)中乙路線（海上絲綢之路）涵蓋的合作國家，不包含哪一大洲的範圍？", "o": ["亞洲", "歐洲", "非洲", "美洲"], "a": 3, "e": "乙路線是海上絲綢之路，不包括美洲。", "rep": false, "img": "g4-q221", "imgnote": "", "fh": "", "maps": ["g4-map-belt"], "chk": ""}, {"id": "g4-222", "no": 222, "c": "e7", "src": "講義第 55 頁 圖表判讀題組 第 32 題", "st": "講義", "ctx": "中國於 2013 年提出「一帶一路」政策，利用此政策加強與周邊國家的經濟合作，同時解決中國經濟快速發展下出現工業產能過剩的情形，圖(十一)為該政策的兩條主要路線。", "fig": "", "q": "承上題，圖(十一)中甲路線（絲綢之路經濟帶）由中國出發，在中國境內經過的範圍多屬於哪一種氣候區？", "o": ["高地氣候", "熱帶季風氣候", "溫帶沙漠氣候", "副熱帶季風氣候"], "a": 2, "e": "甲路線在中國境內經過西北的新疆一帶，屬溫帶沙漠氣候。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-223", "no": 223, "c": "e8", "src": "講義第 55 頁 圖表判讀題組 第 33 題", "st": "講義", "ctx": "中國於 2013 年提出「一帶一路」政策，利用此政策加強與周邊國家的經濟合作，同時解決中國經濟快速發展下出現工業產能過剩的情形，圖(十一)為該政策的兩條主要路線。", "fig": "", "q": "承上題，上文中提到該政策面臨的問題，不包括下列何者？", "o": ["參與國家經濟較差，可能出現債務問題", "參與國家主權不穩，使投資計畫難執行", "參與國家人民擔憂，反對中國勢力深入", "參與國家資金充足，中國企業易被收購"], "a": 3, "e": "一帶一路參與國多經濟落後、資金不足，所以 (D) 不是它的問題。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-224", "no": 224, "c": "e4", "src": "講義第 55 頁 閱讀素養題組 第 34 題", "st": "講義", "ctx": "", "fig": "", "q": "美國電動車大廠特斯拉考量中國投資環境，因此到上海設廠，特斯拉在電動車生產技術具有領導地位，為了能與其競爭，中國在電動車品牌比亞迪加速創新與新技術提升，比亞迪起初以生產各類型電池為主，在 2003 年才正式進軍汽車產業，並在中國政府對電動車產業的補貼下，得以快速成長。文中提及特斯拉到中國設廠，其主要考量因素最可能為下列何者？", "o": ["國土面積廣且礦產資源豐富", "生產成本低且消費市場大", "國民素質佳且研發技術佳", "氣候條件佳且地形起伏小"], "a": 1, "e": "特斯拉到上海設廠，看中生產成本低、消費市場大。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-225", "no": 225, "c": "e9", "src": "講義第 55 頁 閱讀素養題組 第 35 題", "st": "講義", "ctx": "美國電動車大廠特斯拉考量中國投資環境，因此到上海設廠，特斯拉在電動車生產技術具有領導地位，為了能與其競爭，中國在電動車品牌比亞迪加速創新與新技術提升，比亞迪起初以生產各類型電池為主，在 2003 年才正式進軍汽車產業，並在中國政府對電動車產業的補貼下，得以快速成長。", "fig": "", "q": "承上題，文中提及比亞迪電動車得以快速發展，與下列哪一因素的關係最密切？", "o": ["原料豐富", "交通便捷", "政府政策", "動力充足"], "a": 2, "e": "比亞迪快速發展，和中國政府的補貼政策有關。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-226", "no": 226, "c": "e5", "src": "講義第 59 頁 第二次段考複習評量 第 20 題", "st": "講義", "ctx": "", "fig": "", "q": "湖北省的武漢擁有「東方芝加哥」的稱號，因其位於中國的交通要道和政經中心，現今已是 GDP 占的比例第 9 大、生產全球 1/4 光纖的城市。該地位置較為內陸，經濟雖不及沿海城市發展，卻也正逐漸發展起來。上述城市位於中國哪一政策推動區的範圍？", "o": ["西部開發", "中部崛起", "東北振興", "東部率先發展"], "a": 1, "e": "武漢位於湖北，屬中部崛起的範圍。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-region"], "chk": ""}, {"id": "g4-227", "no": 227, "c": "e7", "src": "講義第 59 頁 第二次段考複習評量 題組 第 21 題", "st": "講義", "ctx": "", "fig": "", "q": "中國於 2013 年提出一帶一路的經濟政策，透過與其他國家的經濟合作，希望可以擴大中國的貿易範圍，圖(七)為現有貨運路線示意圖。多數路線需經新疆阿拉山口，而列車出阿拉山口後進入的範圍應為圖(七)中何處？", "o": ["甲", "乙", "丙", "丁"], "a": 1, "e": "列車出新疆阿拉山口後進入中亞（乙）。", "rep": false, "img": "g4-q227", "imgnote": "", "fh": "", "maps": ["g4-map-belt"], "chk": ""}, {"id": "g4-228", "no": 228, "c": "e7", "src": "講義第 59 頁 第二次段考複習評量 題組 第 22 題", "st": "講義", "ctx": "中國於 2013 年提出一帶一路的經濟政策，透過與其他國家的經濟合作，希望可以擴大中國的貿易範圍，圖(七)為現有貨運路線示意圖。", "fig": "", "q": "承上題，上文中鐵路貨運路線主要是聯繫哪一大洲的國家？", "o": ["非洲", "歐洲", "美洲", "大洋洲"], "a": 1, "e": "中歐班列主要聯繫歐洲。", "rep": false, "img": "g4-q227", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-229", "no": 229, "c": "e3", "src": "講義第 59 頁 第二次段考複習評量 題組 第 23 題", "st": "講義", "ctx": "深圳作為中國經濟特區的櫥窗，擁有眾多發展優勢，該地區每平方公里創造的 GDP 產值和稅收都曾是中國最高，可說是改革開放的前段班。雖然 2010 年起，因國民平均工資快速上漲，使得部分產業紛紛出走到勞工成本較低的東南亞等國家，但該城市仍致力轉型，努力朝新創產業發展。", "fig": "", "q": "中國當初選擇在該地區成立經濟特區，其主要考量的條件不包括下列何者？", "o": ["礦產豐富", "勞工眾多", "交通便利", "土地低廉"], "a": 0, "e": "深圳設特區是看中勞工多、交通便、土地便宜，深圳礦產並不豐富。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-sez"], "chk": ""}, {"id": "g4-230", "no": 230, "c": "e3", "src": "講義第 59 頁 第二次段考複習評量 題組 第 24 題", "st": "講義", "ctx": "深圳作為中國經濟特區的櫥窗，擁有眾多發展優勢，該地區每平方公里創造的 GDP 產值和稅收都曾是中國最高，可說是改革開放的前段班。雖然 2010 年起，因國民平均工資快速上漲，使得部分產業紛紛出走到勞工成本較低的東南亞等國家，但該城市仍致力轉型，努力朝新創產業發展。", "fig": "", "q": "承上題，文中提及的經濟特區應為圖(八)中何者？", "o": ["甲", "乙", "丙", "丁"], "a": 2, "e": "深圳位在香港旁，是丙。", "rep": false, "img": "g4-q230", "imgnote": "", "fh": "", "maps": ["g4-map-sez"], "chk": ""}, {"id": "g4-231", "no": 231, "c": "e9", "src": "講義第 59 頁 第二次段考複習評量 題組 第 25 題", "st": "講義", "ctx": "深圳作為中國經濟特區的櫥窗，擁有眾多發展優勢，該地區每平方公里創造的 GDP 產值和稅收都曾是中國最高，可說是改革開放的前段班。雖然 2010 年起，因國民平均工資快速上漲，使得部分產業紛紛出走到勞工成本較低的東南亞等國家，但該城市仍致力轉型，努力朝新創產業發展。", "fig": "", "q": "承上題，上文中提到出走至東南亞的產業，可能以哪一類型的比重最高？", "o": ["技術密集型產業", "勞力密集型產業", "資本密集型產業", "高附加價值產業"], "a": 1, "e": "工資上漲後出走到東南亞的，多是勞力密集型產業。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-232", "no": 232, "c": "e6", "src": "試題寶典評量 第 32 頁 選擇題 第 5 題", "st": "講義", "ctx": "", "fig": "圖(四)：2023 年世界貿易總額前 5 大國家長條圖，由高到低依序為甲、乙、丙、丁、戊。", "q": "隨著交通運輸的進步，全球的國際貿易更加發達。圖(四)是 2023 年世界貿易總額前 5 大國家統計圖，其中的甲、乙、丙應分別是哪三個國家？", "o": ["美國、中國、日本", "美國、中國、荷蘭", "中國、美國、德國", "中國、美國、英國"], "a": 2, "e": "2023 年貿易總額前三名是中國、美國、德國。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-233", "no": 233, "c": "e9", "src": "試題寶典評量 第 32 頁 選擇題 第 6 題", "st": "講義", "ctx": "", "fig": "", "q": "自 2018 年起，中美貿易戰使部分外資撤離中國，造成失業人口大幅增加。外資企業選擇撤離中國的主要原因為何？", "o": ["生產成本提高", "市場規模擴大", "生產技術提升", "環保意識高漲"], "a": 0, "e": "中美貿易戰使在中國生產的成本提高，外資撤離。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-234", "no": 234, "c": "e5", "src": "試題寶典評量 第 32 頁 選擇題 第 7 題", "st": "講義", "ctx": "", "fig": "", "q": "中國為了均衡區域發展，根據各區域現況畫分為 4 個經濟區，其中西部地區未來工業發展的最大優勢為何？", "o": ["對外交通便利", "自然資源豐富", "高素質的勞力", "海運交通便利"], "a": 1, "e": "西部地區工業發展最大的優勢是自然資源豐富。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-235", "no": 235, "c": "e3", "src": "試題寶典評量 第 32 頁 選擇題 第 8 題", "st": "講義", "ctx": "", "fig": "圖(五)：中國地圖標示甲、乙、丙、丁四處，丁在新疆的最西邊。", "q": "喀什是中國歷史文化名城之一，不僅有獨特的自然風光和濃厚的民族風情，也有氣勢宏大的人造景觀，每年吸引大量國內外遊客觀光。上述城市位於圖(五)中何處？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "喀什位在新疆西南部，是丁。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-236", "no": 236, "c": "e1", "src": "試題寶典評量 第 32 頁 選擇題 第 9 題", "st": "講義", "ctx": "", "fig": "", "q": "某電視節目專門介紹中國農村百姓創業致富的故事，其中一集播出：「四川盆地某位農夫，發現近年中國的畜牧產品大增，為順應時局，他將稻田改建為豬舍，並利用科技化的方式管理大量豬隻，短短 3 年就賺進人生第一桶金，事業版圖亦日漸擴大。」上述故事，透露了中國第一級產業經營的何種現象？", "o": ["因應全球氣候異常", "朝向休閒農業發展", "形成專業的生產區", "農業勞力成本增加"], "a": 2, "e": "四川農夫把稻田改成豬舍大量養豬，是形成專業生產區。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-237", "no": 237, "c": "e9", "src": "試題寶典評量 第 32 頁 選擇題 第 10 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(六)為近年日本對東南亞和中國的投資金額統計，由圖中顯示，2012 年後日本對中國投資額不斷減少，而對東南亞地區明顯增加。主要原因為中國工業發展的哪項優勢已逐漸消失？", "o": ["廉價的勞力", "廣大的市場", "便利的運輸", "充足的資金"], "a": 0, "e": "日本對中國投資減少，是因為中國廉價勞力的優勢消失。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-238", "no": 238, "c": "e4", "src": "試題寶典評量 第 32 頁 選擇題 第 11 題", "st": "講義", "ctx": "", "fig": "", "q": "近年來，有許多國際的精品名牌業者進駐中國，如法國的 Chanel、LV 等知名品牌紛紛在中國設置旗艦店，成為重要的行銷據點。上述現象與下列哪一因素最相關？", "o": ["人口數量增加", "消費能力提高", "勞工素質提升", "產業升級轉型"], "a": 1, "e": "國際精品進駐中國，是因為中國人的消費能力提高。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-239", "no": 239, "c": "e5", "src": "試題寶典評量 第 33 頁 選擇題 第 12 題", "st": "講義", "ctx": "", "fig": "表(一)：對國內——推動西部大開發、促進族群的融合；對國外——強化與中亞國家的貿易、利於歐亞大陸經濟整合", "q": "表(一)為中國推行某項建設要達成的政策目標，由表中內容判斷，此一建設最可能是下列何者？", "o": ["西電東送的輸電系統", "南水北調的輸水工程", "橫貫新疆的聯外鐵路", "穿越高原的青藏鐵路"], "a": 2, "e": "推動西部大開發、加強與中亞貿易，最可能是橫貫新疆的聯外鐵路。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-240", "no": 240, "c": "e5", "src": "試題寶典評量 第 33 頁 選擇題 第 13 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(七)為中國目前規劃建設的 19 個都市群，這 19 個都市群約占 25% 的土地，卻聚集約 74% 的人口，創造了約 90% 的人均 GDP。圖中資訊最能呈現何種現象？", "o": ["人口數量龐大", "流動人口眾多", "區域發展不均", "貧富差距擴大"], "a": 2, "e": "19 個都市群占 25% 土地卻集中 74% 人口、90% GDP，呈現區域發展不均。", "rep": false, "img": "g4-q240", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-241", "no": 241, "c": "e6", "src": "試題寶典評量 第 33 頁 選擇題 第 14 題", "st": "講義", "ctx": "", "fig": "", "q": "中國為擴大其經濟版圖，積極與各國簽訂自由貿易協定。其中，2020 年簽署的區域全面經濟夥伴協定（RCEP），參與該協定的國家享有的優惠包括哪些？(甲)人民往來免簽證 (乙)關稅減免 (丙)發行共同貨幣 (丁)降低進出口限制", "o": ["甲乙", "甲丙", "乙丁", "丙丁"], "a": 2, "e": "RCEP 的優惠是關稅減免（乙）、降低進出口限制（丁）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-242", "no": 242, "c": "e6", "src": "試題寶典評量 第 33 頁 選擇題 第 15 題", "st": "講義", "ctx": "", "fig": "", "q": "自 2000 年開始，中國政府鼓勵本國企業到外國投資，希望透過收購的方式取得經營權，例如：浙江吉利控股集團收購瑞典的富豪汽車、美的集團收購德國機器人手臂製造商等。根據上述內容判斷，中國投資外國企業的主要目的為何？", "o": ["擴大國內市場", "獲取產業技術", "賺取貿易外匯", "干涉他國內政"], "a": 1, "e": "收購外國企業，主要目的是獲取產業技術。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-243", "no": 243, "c": "e5", "src": "試題寶典評量 第 33 頁 選擇題 第 16 題", "st": "講義", "ctx": "", "fig": "表(二)：外商投資總額前四名——江蘇 18.89%、廣東 15.64%、上海 13.43%、浙江 6.92%；後四名——西藏 0.03%、青海 0.11%、寧夏 0.14%、新疆 0.19%", "q": "表(二)為中國 2006 至 2015 年外商投資總額最多和最少的四個行政區。根據表中呈現外商投資的地區差異，下列哪一項策略最能夠改善表中所呈現的問題？", "o": ["促進東北老舊工業區轉型", "與東協簽署自由貿易協定", "取消一胎化的計畫生育政策", "推動與中亞國家的邊境貿易"], "a": 3, "e": "外資集中東部、西部最少，推動與中亞邊境貿易可改善西部投資環境。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-244", "no": 244, "c": "e4", "src": "試題寶典評量 第 33 頁 選擇題 第 17 題", "st": "講義", "ctx": "", "fig": "", "q": "中國的網路購物熱潮自 2009 年興起，使得電子商務蓬勃發展，並造就中國某知名電商曾勇奪亞洲市值王，為全球第 7 名。中國電商能在極短時間興起，是因為中國具有下列哪項最大的優勢？", "o": ["充足的勞動力", "龐大的消費市場", "廉價的工業製品", "流行的時尚商品"], "a": 1, "e": "電商快速興起，因為中國有龐大的消費市場。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-245", "no": 245, "c": "e5", "src": "試題寶典評量 第 34 頁 選擇題 第 18 題", "st": "講義", "ctx": "", "fig": "", "q": "某跨國集團生產 iPhone 的主要工廠，最早是在設在中國東部經濟區的深圳，但於 2010 年遷到中部經濟帶的鄭州生產。下列何者最可能是該集團將工廠遷移的主要原因？", "o": ["均衡區域發展", "降低生產成本", "加速工業升級", "減少工業汙染"], "a": 1, "e": "從深圳遷到鄭州，是因為中部工資比較低，可以降低生產成本。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-246", "no": 246, "c": "e2", "src": "試題寶典評量 第 34 頁 選擇題 第 19 題", "st": "講義", "ctx": "", "fig": "", "q": "工業生產為了降低成本，增加競爭力，工廠的設置會選擇適合的地點，稱為工業區位。圖(八)為中國礦產分布圖，由圖中資訊判斷，下列敘述何者最合理？", "o": ["北部石化工業發達", "南部以重工業為主", "北部鐵路分布密集", "南部設立經濟特區"], "a": 0, "e": "北部盛產石油，石化工業發達。", "rep": false, "img": "g4-q246", "imgnote": "", "fh": "", "maps": ["g4-map-mineral"], "chk": ""}, {"id": "g4-247", "no": 247, "c": "e5", "src": "試題寶典評量 第 34 頁 選擇題 第 20 題", "st": "講義", "ctx": "", "fig": "", "q": "中國於 1970 年代末推動的改革開放政策，帶動經濟快速成長，但是卻加深區域發展失衡現象。下列關於中國的新聞報導，何者最能反映中國區域發展不均的現象？", "o": ["今年出現的多起沙塵暴，已直接威脅北京、上海及南京等大都市", "推動海上絲路計畫，發展從中國沿海港口經印度洋至歐洲的航線", "農曆春節將湧現數億人次返鄉人潮，堪稱地表最大規模的人口移動", "南方近年降雨減少，旱象環生，南水北調將威脅南方用水的供應量"], "a": 2, "e": "春運數億人返鄉，最能反映區域發展不均。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-248", "no": 248, "c": "e3", "src": "試題寶典評量 第 34 頁 素養UP題組 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "東部沿海地區由於有利於工業發展，成為中國最早推動經濟改革開放的地區。1980 年代設立汕頭、廈門、深圳、珠海、海南 5 個經濟特區，成功帶動此區的經濟發展。之後沿著海岸線及河川、鐵路等交通幹線，發展出許多工商業密集區。最初經濟特區的工業類型，其性質最類似於臺灣哪一種工業區？", "o": ["科學園區", "石化專業區", "加工出口區", "資源型工業區"], "a": 2, "e": "經濟特區以勞力密集的加工出口業為主，類似臺灣的加工出口區。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-249", "no": 249, "c": "e3", "src": "試題寶典評量 第 34 頁 素養UP題組 第 2 題", "st": "講義", "ctx": "東部沿海地區由於有利於工業發展，成為中國最早推動經濟改革開放的地區。1980 年代設立汕頭、廈門、深圳、珠海、海南 5 個經濟特區，成功帶動此區的經濟發展。之後沿著海岸線及河川、鐵路等交通幹線，發展出許多工商業密集區。", "fig": "", "q": "承上題，上文中，這 5 個經濟特區具有下列哪一項共同的優越性？", "o": ["天然資源豐富", "對外交通便利", "資金相當充足", "技術非常先進"], "a": 1, "e": "5 個經濟特區都在東南沿海，對外交通便利。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-250", "no": 250, "c": "e7", "src": "試題寶典評量 第 35 頁 閱讀素養 第 3 題（原為簡答題）", "st": "講義", "ctx": "近年來的中國，已成為世界上重要的經濟大國，為了提高在國際上的影響力，提出「一帶一路」政策，全名為「絲綢之路經濟帶」及「21 世紀海上絲綢之路」，路線如圖(九)所示，希望透過「一帶一路」沿線國家加強基礎建設及開發，讓中國與周邊國家在經濟、貿易的合作關係更加密切。", "fig": "", "q": "由圖中位置判斷，「絲綢之路經濟帶」經由中國西部地區連接何處通往歐洲？", "o": ["中亞", "南亞", "東亞", "北亞"], "a": 0, "e": "絲綢之路經濟帶經中國西部連接中亞通往歐洲。", "rep": false, "img": "g4-q250", "imgnote": "", "fh": "", "maps": ["g4-map-belt"], "chk": ""}, {"id": "g4-251", "no": 251, "c": "e7", "src": "試題寶典評量 第 35 頁 閱讀素養 第 4 題", "st": "講義", "ctx": "近年來的中國，已成為世界上重要的經濟大國，為了提高在國際上的影響力，提出「一帶一路」政策，全名為「絲綢之路經濟帶」及「21 世紀海上絲綢之路」，路線如圖(九)所示，希望透過「一帶一路」沿線國家加強基礎建設及開發，讓中國與周邊國家在經濟、貿易的合作關係更加密切。", "fig": "", "q": "「21 世紀海上絲綢之路」是指中國歷史上哪個人物當初下西洋的海上通路？", "o": ["鄭和", "玄奘", "張騫", "鐵木真"], "a": 0, "e": "21 世紀海上絲綢之路是鄭和下西洋的海路。", "rep": false, "img": "g4-q250", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-252", "no": 252, "c": "e7", "src": "試題寶典評量 第 35 頁 閱讀素養 第 5 題", "st": "講義", "ctx": "近年來的中國，已成為世界上重要的經濟大國，為了提高在國際上的影響力，提出「一帶一路」政策，全名為「絲綢之路經濟帶」及「21 世紀海上絲綢之路」，路線如圖(九)所示，希望透過「一帶一路」沿線國家加強基礎建設及開發，讓中國與周邊國家在經濟、貿易的合作關係更加密切。", "fig": "", "q": "中國推動「一帶一路」新政策，其主要目的為何？", "o": ["解決城鄉差異", "降低生產成本", "減少工業汙染", "消化過剩產能"], "a": 3, "e": "一帶一路可以消化中國過剩的產能。", "rep": false, "img": "g4-q250", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-253", "no": 253, "c": "e2", "src": "試題寶典評量 第 36 頁 第二次段考模擬試題 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "中國某地區因煤、鐵、石油等礦產資源較少，昔日以輕工業為主。上文中的「某地區」位於圖(一)中何處？", "o": ["甲", "乙", "丙", "丁"], "a": 0, "e": "南方（甲）煤、鐵、石油較少，昔日以輕工業為主。", "rep": false, "img": "g4-q253", "imgnote": "", "fh": "", "maps": ["g4-map-mineral"], "chk": ""}, {"id": "g4-254", "no": 254, "c": "e1", "src": "試題寶典評量 第 36 頁 第二次段考模擬試題 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "中國隨著經濟發展，傳統畜牧業經營方式也有所改變。圖(二)為中國某牧場所購製的設備，從圖中可以看出此牧場經營發展的方向為何？", "o": ["開發休閒牧場，以達到環境保育的目的", "透過機械可大量生產，形成專業生產區", "維持傳統畜牧方式，避免傳統文化失傳", "低密度飼養，減少汙染，提高環保意識"], "a": 1, "e": "使用機械化擠乳設備可大量生產，形成專業生產區。", "rep": false, "img": "g4-q254", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-255", "no": 255, "c": "e4", "src": "試題寶典評量 第 36 頁 第二次段考模擬試題 第 4 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(三)為世界三大經濟體的 GDP 變化圖，由圖中資訊判斷，中國、美國、日本依序為下列何者？", "o": ["甲乙丙", "甲丙乙", "乙甲丙", "丙甲乙"], "a": 2, "e": "甲是美國、乙是中國、丙是日本，所以中、美、日依序為乙甲丙。", "rep": false, "img": "g4-q255", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-256", "no": 256, "c": "e1", "src": "試題寶典評量 第 36 頁 第二次段考模擬試題 第 5 題", "st": "講義", "ctx": "", "fig": "", "q": "中國農民透過生態農業的方式，逐步提升耕地肥沃度，兼顧糧食生產環境與產量。上述措施的主要目的為何？", "o": ["均衡區域發展", "節省開發成本", "提高國民所得", "達成永續發展"], "a": 3, "e": "生態農業兼顧生產環境與產量，目的是永續發展。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-257", "no": 257, "c": "e5", "src": "試題寶典評量 第 37 頁 第二次段考模擬試題 第 6 題", "st": "講義", "ctx": "", "fig": "表(一)：東部／中部——自然資源 較豐富／較缺乏；對外交通 較不便／較便利；勞力成本 較昂貴／較低廉；開發時間 較晚／較早", "q": "1978 年，中國實施經濟改革開放政策後，區域發展呈現失衡狀態。表(一)為東部地區和中部地區的比較，下列何者正確？", "o": ["自然資源", "對外交通", "勞力成本", "開發時間"], "a": 2, "e": "表中只有「勞力成本：東部較昂貴、中部較低廉」是正確的，其他三項都寫反了。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-258", "no": 258, "c": "e7", "src": "試題寶典評量 第 37 頁 第二次段考模擬試題 第 7 題", "st": "講義", "ctx": "", "fig": "", "q": "「一帶一路」政策是由中國主導的跨國經濟帶，其範圍涵蓋歷史上絲綢之路和海上絲綢之路行經的國家。加入一帶一路計畫的國家，主要是希望可以取得下列何項效益？", "o": ["希望得到中國軍事保護", "傾銷國內過剩的農作物", "吸引各國先進技術投入", "引進中國資金發展經濟"], "a": 3, "e": "參加一帶一路的國家希望引進中國資金發展經濟。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-259", "no": 259, "c": "e2", "src": "試題寶典評量 第 37 頁 第二次段考模擬試題 第 8 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(四)為中國三級產業產值比例統計圖，嘉玲的職業屬於圖中的「乙」產業，依據圖中資訊判斷，她最有可能從事下列何種工作？", "o": ["在速食店擔任收銀員", "在紡織廠擔任作業員", "在購物中心擔任推銷員", "在畜牧場擔任乳牛飼養員"], "a": 1, "e": "乙長年約 30%～40%，是第二級產業（工業），紡織廠作業員屬第二級產業。", "rep": false, "img": "g4-q259", "imgnote": "", "fh": "", "maps": ["g4-map-ind"], "chk": ""}, {"id": "g4-260", "no": 260, "c": "e6", "src": "試題寶典評量 第 37 頁 第二次段考模擬試題 第 10 題", "st": "講義", "ctx": "", "fig": "", "q": "中國企業收購瑞典 Volvo 汽車公司，除了取得相關技術和品牌資源，還能進一步拓展哪一市場的版圖？", "o": ["歐洲", "非洲", "美洲", "大洋洲"], "a": 0, "e": "瑞典是歐洲國家，收購 Volvo 可以拓展歐洲市場。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-261", "no": 261, "c": "e5", "src": "試題寶典評量 第 39 頁 第二次段考模擬試題 第 18 題", "st": "講義", "ctx": "", "fig": "", "q": "中國西部大開發政策包含西電東送、西氣東輸、青藏鐵路及南水北調等。上述規畫主要是為了解決中國經濟改革開放後的哪一項問題？", "o": ["人口數量眾多", "人口素質低落", "交通建設落後", "區域發展差異"], "a": 3, "e": "西部大開發的各項建設，是為了解決區域發展差異。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-262", "no": 262, "c": "e4", "src": "試題寶典評量 第 39 頁 第二次段考模擬試題 第 20 題", "st": "講義", "ctx": "", "fig": "", "q": "根據統計，中國某一年消費高達 193 億公升的葡萄酒，位居全球第五大葡萄酒消費國。同時中國也是全球第七大葡萄酒生產國，產量僅次於義大利、法國、西班牙、美國、澳大利亞和阿根廷。下列何者最能說明上述現象？", "o": ["中國擁有充足又廉價的勞動力", "釀造葡萄酒技術已超越歐美", "中國擁有龐大消費市場的潛力", "近年中國已成為世界工廠名號"], "a": 2, "e": "中國葡萄酒消費量很大，說明中國有龐大的消費市場。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-263", "no": 263, "c": "e3", "src": "試題寶典評量 第 39 頁 第二次段考模擬試題 第 21 題", "st": "講義", "ctx": "", "fig": "", "q": "張老師為了讓同學能了解中國工業發展歷程，特別邀請王同學的祖母到班上分享職場工作經驗。圖(八)為當天的分享內容，依圖中資訊判斷，王奶奶當時前往中國發展，主要是受下列何項政策影響？「1985 年時，由於中國勞工成本低廉，老闆決定將工廠遷移至中國，我便在中國的紡織廠擔任管理幹部長達十幾年。」", "o": ["東北的振興", "西部大開發", "設經濟特區", "中部的崛起"], "a": 2, "e": "1985 年因勞工成本低把工廠遷往中國，和設立經濟特區有關。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-264", "no": 264, "c": "e5", "src": "社會自修(3) 第 64 頁 會考試題範例 第 1 題", "st": "自修", "ctx": "", "fig": "", "q": "中國於 1970 年代末推動的改革開放政策，帶動經濟快速成長，但是卻加深區域發展失衡現象。下列關於中國的新聞報導，何者最能反映中國區域發展不均的現象？", "o": ["今年出現的多起沙塵暴，已直接威脅北京、上海及南京等大都市", "推動海上絲路計畫，發展從中國沿海港口經印度洋至歐洲的航線", "農曆春節將湧現數億人次返鄉人潮，堪稱地表最大規模的人口移動", "南方近年降雨減少，旱象環生，南水北調將威脅南方用水的供應量"], "a": 2, "e": "春運數億人返鄉，最能反映區域發展不均。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-265", "no": 265, "c": "e3", "src": "社會自修(3) 第 64 頁 會考試題範例 第 2 題", "st": "自修", "ctx": "", "fig": "", "q": "中國某一座跨海大橋於 2018 年完工，其連結了中國兩個特別行政區及一個經濟特區，可縮短往來三地的距離，及強化三地經濟社會的交流。上述跨海大橋應位於下列哪條河川的出海口？", "o": ["珠江", "長江", "海河", "黃河"], "a": 0, "e": "港珠澳大橋連接香港、澳門與珠海，位在珠江口。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-266", "no": 266, "c": "e7", "src": "社會自修(3) 第 65 頁 會考試題範例 第 3 題", "st": "自修", "ctx": "", "fig": "", "q": "中國實施「一帶一路」政策規畫了許多經濟走廊，右圖為部分經濟走廊示意圖。其中有一條的規畫目的，除可降低從波斯灣運石油至中國須經印尼、馬來西亞間海峽及南海的風險外，也兼具促進中國西部地區與西亞、南亞國家的能源和貿易往來，此經濟走廊最可能為圖中何者？", "o": ["甲", "乙", "丙", "丁"], "a": 2, "e": "中巴經濟走廊（丙）可避開麻六甲海峽，促進中國西部與南亞、西亞往來。", "rep": false, "img": "g4-q266", "imgnote": "", "fh": "", "maps": ["g4-map-belt"], "chk": ""}, {"id": "g4-267", "no": 267, "c": "e3", "src": "社會自修(3) 第 65 頁 選擇題 基礎養成 第 1 題", "st": "自修", "ctx": "", "fig": "", "q": "中國實施改革開放後，陸續設置 6 個經濟特區。根據經濟特區的位置判斷，其中哪一經濟特區主要是因為鄰近中亞地區，而發展邊境貿易活動？", "o": ["珠海", "喀什", "汕頭", "深圳"], "a": 1, "e": "鄰近中亞、發展邊境貿易的經濟特區是喀什。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-sez"], "chk": ""}, {"id": "g4-268", "no": 268, "c": "e1", "src": "社會自修(3) 第 65 頁 選擇題 基礎養成 第 2 題", "st": "自修", "ctx": "", "fig": "", "q": "近年來，中國為確保糧食供應而進行農業轉型，形成專業生產區。上述提到中國農場經營的轉變，與下列何項原因最有關係？", "o": ["人口持續增加", "務農人口減少", "鄉村勞力回流", "土地面積減少"], "a": 1, "e": "從事農業的人口減少，所以農場轉型為大規模的專業生產區。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-269", "no": 269, "c": "e1", "src": "社會自修(3) 第 66 頁 選擇題 基礎養成 第 3 題", "st": "自修", "ctx": "", "fig": "", "q": "中國在經濟改革開放之後，農業面臨極大挑戰，進而農業轉型。下列何者不符合中國農業轉型的方向？", "o": ["內蒙古的酪農專業區", "東北平原機械化耕作糧食", "以傳統山牧季移維生", "農業科技發展生態農業"], "a": 2, "e": "山牧季移是傳統畜牧方式，不是農業轉型的方向。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-270", "no": 270, "c": "e4", "src": "社會自修(3) 第 66 頁 選擇題 基礎養成 第 4 題", "st": "自修", "ctx": "", "fig": "", "q": "市場廣大是目前中國在產業發展和國際貿易上的一大利基，這與下列哪一種條件最直接相關？", "o": ["礦產豐富", "運輸便利", "疆域廣闊", "人口眾多"], "a": 3, "e": "市場廣大最直接和人口眾多有關。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-271", "no": 271, "c": "e3", "src": "社會自修(3) 第 66 頁 選擇題 基礎養成 第 5 題", "st": "自修", "ctx": "", "fig": "", "q": "1990 年臺灣開放本地廠商赴中國投資，以紡織和玩具等產業將廠房轉移至中國的經濟特區。上述廠商當時主要是看重中國擁有哪項有利的投資條件？", "o": ["資金", "技術", "市場", "勞工"], "a": 3, "e": "紡織、玩具是勞力密集產業，當時看重中國的勞工。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-272", "no": 272, "c": "e4", "src": "社會自修(3) 第 66 頁 選擇題 基礎養成 第 6 題", "st": "自修", "ctx": "", "fig": "", "q": "2016 年 6 月中旬，上海迪士尼正式開幕，目前為亞洲面積最大的迪士尼樂園。美國華特迪士尼公司持有該樂園的股份達 43%，其他股份則主要是由上海申迪集團的國有公司持有。當初美國華特迪士尼公司因下列哪項因素與上海申迪集團合作投資興建迪士尼樂園？", "o": ["中國的原料充足", "中國的消費市場大", "中國的勞動力低廉", "中國的陸上鄰國多"], "a": 1, "e": "迪士尼和上海合作，是看中中國的消費市場大。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-273", "no": 273, "c": "e6", "src": "社會自修(3) 第 66 頁 選擇題 基礎養成 第 7 題", "st": "自修", "ctx": "", "fig": "", "q": "位於漠南非洲的剛果，其國內的唐凱豐古魯姆鈷礦場原本是由美國企業經營，但在 2016 年時，美國礦業公司將此地的鈷礦經營權賣給中國的企業。上述可以說明下列哪個現象？", "o": ["中國利用投資取得礦產資源", "美國透過併購方式投資中國", "中國的經濟版圖影響力變小", "美國的經濟版圖影響力變大"], "a": 0, "e": "中國企業買下剛果的鈷礦經營權，是利用投資取得礦產資源。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-274", "no": 274, "c": "e5", "src": "社會自修(3) 第 66 頁 選擇題 基礎養成 第 8 題", "st": "自修", "ctx": "", "fig": "", "q": "為解決中國區域發展不均的問題，中國根據各區域現況提出「東北振興」政策，該區所面臨的經濟發展問題包括以下哪一項？", "o": ["人口密集", "交通不便", "開發較晚", "礦產枯竭"], "a": 3, "e": "東北面臨的問題是礦產枯竭、設備老舊。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-275", "no": 275, "c": "e5", "src": "社會自修(3) 第 66 頁 選擇題 基礎養成 第 9 題", "st": "自修", "ctx": "", "fig": "", "q": "圖(一)為 2020 年外資企業在中國登記數量分布圖。根據圖中資訊判斷，下列哪個經濟分區的外資企業相對分布最少？", "o": ["東部地區", "東北地區", "中部地區", "西部地區"], "a": 3, "e": "外資企業最少的是西部地區。", "rep": false, "img": "g4-q275", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-276", "no": 276, "c": "e8", "src": "社會自修(3) 第 67 頁 選擇題 基礎養成 第 10 題", "st": "自修", "ctx": "", "fig": "", "q": "中國透過一帶一路政策協助各參與國的基礎建設，並增強彼此經濟連結，但也為這些參與國家帶來了負面影響。下列何者最有可能是其所帶來的負面影響之一？", "o": ["勞工失業率提高", "龐大的債務負擔", "被迫退出聯合國", "社會福利支出增加"], "a": 1, "e": "參與國借款建設後無力償還，帶來龐大的債務負擔。", "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-277", "no": 277, "c": "e6", "src": "社會自修(3) 第 67 頁 選擇題 基礎養成 第 11 題", "st": "自修", "ctx": "", "fig": "", "q": "近年中國積極與各國簽訂自由貿易協定，以「區域全面經濟夥伴協定」為例，其 GDP 約占全球總產值的 30%。上述現象可以用下列何者來解釋？", "o": ["中國為擴大其經濟版圖", "中國恐將面臨龐大債務", "中部不再實施改革開放", "中國拒絕外國企業投資"], "a": 0, "e": "積極簽訂自由貿易協定，是為了擴大經濟版圖。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-278", "no": 278, "c": "e5", "src": "社會自修(3) 第 67 頁 選擇題 基礎養成 第 12 題", "st": "自修", "ctx": "", "fig": "", "q": "圖(二)為中國主要鐵路線及其樞紐的分布。觀察圖中空間分布的特徵，與下列哪些現象的關聯性最高？", "o": ["緯度高低、地形類型", "地形類型、人口分布", "人口分布、土壤性質", "土壤性質、緯度高低"], "a": 1, "e": "鐵路東密西疏，和地形（東部平坦）與人口分布（東部人多）有關。", "rep": false, "img": "g4-q278", "imgnote": "", "fh": "", "maps": ["g4-map-rail"], "chk": ""}, {"id": "g4-279", "no": 279, "c": "e5", "src": "社會自修(3) 第 67 頁 選擇題 精熟活用 第 13 題", "st": "自修", "ctx": "", "fig": "", "q": "「獨角獸企業」是指成立不到 10 年，企業資產價值 10 億美元以上，但未在股票市場上市的科技新創產業公司。根據 2020 年的統計，中國境內符合此條件的企業者多達 251 家，以研發智能汽車、智慧物流、數位醫療與人工智能等領域為主。上述領域最可能在下列哪些地點發展？", "o": ["上海、深圳", "撫順、蘭州", "喀什、拉薩", "哈爾濱、烏魯木齊"], "a": 0, "e": "新創科技公司多在東部的上海、深圳。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-280", "no": 280, "c": "e4", "src": "社會自修(3) 第 67 頁 選擇題 精熟活用 第 14 題", "st": "自修", "ctx": "", "fig": "", "q": "英國在工業革命的年代，因擁有領先全球的技術、眾多的資金、優質的勞工等條件，使工業發展位居龍頭地位，當時更被稱為世界市場，這主要是與英國在殖民戰爭中獲得遍布世界的殖民地，成為其工業成品的市場有關。但現今中國成為僅次美國的全球第二大經濟體，成為新興消費市場，主要和下列哪項因素最相關？", "o": ["國土面積世界排名第四國家", "高速鐵路總長度位居世界第一", "平原面積約占全國的土地 12%", "國內人口眾多且消費能力提升"], "a": 3, "e": "中國成為新興消費市場，是因為人口眾多且消費能力提升。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-281", "no": 281, "c": "e5", "src": "社會自修(3) 第 68 頁 選擇題 精熟活用 第 15 題", "st": "自修", "ctx": "", "fig": "", "q": "2012 年中國建成以「四縱四橫」為骨架的高速鐵路網，平均時速可以落在 300 公里左右，讓各地的貨物與旅客移動更加快速、便利，帶動工商業快速成長與轉型。中國需要如此快速的高速鐵路，主要是希望打破下列哪項因素的限制？", "o": ["國土面積廣大，人口分布不均", "氣候環境惡劣，不利交通建設", "人口老化嚴重，使勞動力不足", "山多平原少，限制城市的發展"], "a": 0, "e": "國土廣大、人口分布不均，需要快速高鐵縮短距離。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-282", "no": 282, "c": "e1", "src": "社會自修(3) 第 68 頁 選擇題 精熟活用 第 16 題", "st": "自修", "ctx": "", "fig": "", "q": "圖(三)為中國水資源短缺省區市圖，圖中水資源短缺的地區因工業發達與人口集中而缺水，但下列何處卻是因為年降水量稀少而缺水？", "o": ["遼寧省", "山東省", "河北省", "寧夏回族自治區"], "a": 3, "e": "寧夏距海較遠、屬乾燥氣候，因為年降水量稀少而缺水。", "rep": false, "img": "g4-q282", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-283", "no": 283, "c": "e9", "src": "社會自修(3) 第 68 頁 選擇題 精熟活用 第 17 題", "st": "自修", "ctx": "", "fig": "", "q": "臺灣鴻海集團在中國東南沿海所設的出口導向工廠，原有員工 26 萬人。近年為了企業良性發展，將生產基地轉向內陸，當地原廠員工降至 10 萬人。上述現象與下列何者有關？", "o": ["沿海基本工資逐漸調高", "外國對中國的投資減少", "沿海交通不如內陸便利", "人民消費支出漸趨下滑"], "a": 0, "e": "沿海基本工資調高，工廠轉往內陸，原廠員工減少。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-284", "no": 284, "c": "e5", "src": "社會自修(3) 第 68 頁 選擇題 精熟活用 第 18 題", "st": "自修", "ctx": "", "fig": "", "q": "圖(四)為中國的四大經濟區，中國政府在 2000 至 2013 年期間，於圖中綠色區域（西部地區）投入基礎工程總額達 3 兆人民幣以上。該政府會在當地大量興建基礎設施，其目的與下列何者最相關？", "o": ["減少產業對環境的衝擊", "均衡中國區域間的發展", "擴大上海市的腹地範圍", "減緩西部區域成長速度"], "a": 1, "e": "在西部大量興建基礎設施，是為了均衡區域發展。", "rep": false, "img": "g4-q284", "imgnote": "", "fh": "", "maps": ["g4-map-region"], "chk": ""}, {"id": "g4-285", "no": 285, "c": "e6", "src": "社會自修(3) 第 68 頁 選擇題 精熟活用 第 19 題", "st": "自修", "ctx": "", "fig": "", "q": "中國聯想科技公司在 2014 年以 29.1 億美元向 Google 買下美國手機製造公司摩托羅拉；2016 年聯想發布年度財務報表，指出此一併購整合未達到預期成效，在中國的智慧型手機銷售業務下滑，且在北美市場經營也未成功。上述科技公司透過直接併購外國公司以尋求企業發展的目的可能為何？", "o": ["尋找新的原料產地", "將總部外移到國外", "快速打入歐美市場", "大幅降低製造成本"], "a": 2, "e": "聯想併購摩托羅拉，目的是快速打入歐美市場。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-286", "no": 286, "c": "e6", "src": "社會自修(3) 第 69 頁 選擇題 精熟活用 第 20 題", "st": "自修", "ctx": "", "fig": "", "q": "圖❺是 2023 年世界前 5 大貿易總額國家，圖中可以直接看出下列何者？", "o": ["中國對各國大量出超", "中國對各國大幅入超", "中國進出口總值龐大", "中國進出口總值短少"], "a": 2, "e": "圖中中國貿易總額世界第一，可以直接看出中國進出口總值龐大；出超或入超需要另外比較出口和進口。", "rep": false, "img": "g4-q286", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-287", "no": 287, "c": "e7", "src": "社會自修(3) 第 69 頁 選擇題 精熟活用 第 21 題", "st": "自修", "ctx": "", "fig": "", "q": "兩千多年前，自西漢張騫出使西域所走出的絲綢之路，如今已演變成橫貫歐亞大陸的貿易交通線，也是中國與西方國家商業往來的重要通道。近年中國以此路線為基礎，提出了「絲綢之路經濟帶」的構想。若想要讓中國國內廠商前往該經濟帶發展，應前往下列哪一行政區設廠？", "o": ["西藏", "新疆", "廣西", "內蒙古"], "a": 1, "e": "絲綢之路經濟帶經中國西北往中亞，廠商應到新疆設廠。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-288", "no": 288, "c": "e7", "src": "社會自修(3) 第 69 頁 選擇題 精熟活用 第 22 題", "st": "自修", "ctx": "", "fig": "", "q": "中國所推展的一帶一路政策，除了重視沿線上各國的經貿互動關係，對於國內也強調省區之間的互聯互通、產業承接與轉移。將有利於加快中國經濟轉型升級的腳步，改變中國區域發展版圖。其中位在西北內陸的新疆維吾爾自治區應扮演下列哪種角色？", "o": ["高鐵製造基地", "陸運交通樞紐", "油氣消費市場", "電腦生產中心"], "a": 1, "e": "新疆西鄰中亞，是一帶一路陸上絲路的必經之地，扮演陸運交通樞紐。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-289", "no": 289, "c": "e8", "src": "社會自修(3) 第 69 頁 選擇題 精熟活用 第 23 題", "st": "自修", "ctx": "", "fig": "", "q": "根據下列資料判斷，參與中國一帶一路政策的國家可能會面臨何種風險？資料一：中國港灣工程公司協助斯里蘭卡興建漢班托塔商港，但因斯里蘭卡無法償還工程貸款，2017 年將管理權移交給中國公司。資料二：塔吉克 2018 年因無法償還中國提供興建發電廠的貸款，只好讓出採礦權利給中國。", "o": ["龐大債務負擔", "就業機會減少", "基礎建設不足", "商品出口受阻"], "a": 0, "e": "斯里蘭卡、塔吉克都無法償還中國貸款，被迫讓出港口、礦權，面臨龐大債務負擔。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-290", "no": 290, "c": "e5", "src": "社會自修(3) 第 69 頁 選擇題 精熟活用 第 24 題", "st": "自修", "ctx": "", "fig": "", "q": "考慮前往中國投資的陳董正在蒐集各經濟分區的資訊以作參考。下列有關他蒐集的投資評估資料，何者較為正確？", "o": ["西部地區交通便捷，適合開設商業銀行", "東部地區礦產豐富，利於興建大鋼鐵廠", "東北地區資源豐富，工商業發展較緩慢", "中部地區有低廉的工資與自然資源優勢"], "a": 3, "e": "中部地區有低廉的工資與自然資源優勢。西部交通不便、東部礦產不多、東北工商業曾是重工業重心。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-291", "no": 291, "c": "e5", "src": "社會自修(3) 第 70 頁 選擇題 精熟活用 第 25 題", "st": "自修", "ctx": "", "fig": "表(一)：東北三省 GDP 占全國比例——1970 年 13.50%、1980 年 13.29%、1990 年 11.88%、2000 年 10.89%", "q": "表(一)為 1970～2000 年間中國東北地區及主要三省區的國內生產總值。表中呈現當時該地區的經濟發展和全國平均相比，已呈現衰退現象，若不考慮其他省市的發展狀況，造成此一現象的主要原因為何？", "o": ["勞力外流，人口老化情形嚴重", "工業發展資金不足，政府政策不當", "礦產逐漸枯竭，工廠設備老舊", "鐵路交通設施老舊，運輸效率降低"], "a": 2, "e": "東北地區礦產逐漸枯竭、工廠設備老舊，經濟占全國比例下降。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-292", "no": 292, "c": "e3", "src": "社會自修(3) 第 70 頁 填圖題 第 1～6 題（原為填圖題）", "st": "自修", "ctx": "", "fig": "", "q": "圖(六)為中國經濟特區分布圖，請依圖中代號的位置，填入經濟特區的名稱：1. 甲；2. 乙；3. 丙；4. 丁；5. 戊；6. 己。", "o": ["甲—喀什、乙—廈門、丙—汕頭、丁—深圳、戊—珠海、己—海南", "甲—深圳、乙—喀什、丙—海南、丁—珠海、戊—汕頭、己—廈門", "甲—海南、乙—珠海、丙—深圳、丁—汕頭、戊—廈門、己—喀什", "甲—喀什、乙—海南、丙—深圳、丁—珠海、戊—汕頭、己—廈門"], "a": 0, "e": "甲喀什（新疆）、乙廈門（福建）、丙汕頭、丁深圳、戊珠海（廣東）、己海南。", "rep": false, "img": "g4-q292", "imgnote": "", "fh": "", "maps": ["g4-map-sez"], "chk": ""}, {"id": "g4-293", "no": 293, "c": "e7", "src": "社會自修(3) 第 70 頁 統整應用題組 第 1 題（原為簡答題）", "st": "自修", "ctx": "亞洲基礎設施投資銀行（亞投行）是以提供資金支持一帶一路全線基礎建設項目的開發機構，包括鐵路、公路、機場、海港、科技產業園區和物流集散中心等，「想要富，先修路」的觀念，更是中國經濟發展起飛的重點。但是近年參與一帶一路的國家，多屬於貧窮國家，反而是遭遇到許多合作上的阻礙，使得部分計畫暫停或終止，出現許多變數。", "fig": "", "q": "亞洲基礎設施投資銀行（亞投行）是以提供資金支持一帶一路全線基礎建設項目的開發機構，包括鐵路、公路、機場、海港、科技產業園區和物流集散中心等。「想致富，先修路」的觀念，更是中國經濟發展起飛的重點。上文中提及的亞投行，其發起國最有可能是哪個國家？", "o": ["中國", "美國", "俄羅斯", "日本"], "a": 0, "e": "亞投行是支持一帶一路建設的機構，由中國發起。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-294", "no": 294, "c": "e7", "src": "社會自修(3) 第 71 頁 統整應用題組 第 2 題", "st": "自修", "ctx": "亞洲基礎設施投資銀行（亞投行）是以提供資金支持一帶一路全線基礎建設項目的開發機構，包括鐵路、公路、機場、海港、科技產業園區和物流集散中心等，「想要富，先修路」的觀念，更是中國經濟發展起飛的重點。但是近年參與一帶一路的國家，多屬於貧窮國家，反而是遭遇到許多合作上的阻礙，使得部分計畫暫停或終止，出現許多變數。", "fig": "", "q": "承上題，上頁文中提及「要致富，先修路」是指中國認為先投資哪項基礎建設，可能帶動落後或開發中國家的經濟成長？", "o": ["交通", "能源", "科技", "文化"], "a": 0, "e": "「要想富，先修路」指先投資交通建設。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-295", "no": 295, "c": "e8", "src": "社會自修(3) 第 71 頁 統整應用題組 第 3 題", "st": "自修", "ctx": "亞洲基礎設施投資銀行（亞投行）是以提供資金支持一帶一路全線基礎建設項目的開發機構，包括鐵路、公路、機場、海港、科技產業園區和物流集散中心等，「想要富，先修路」的觀念，更是中國經濟發展起飛的重點。但是近年參與一帶一路的國家，多屬於貧窮國家，反而是遭遇到許多合作上的阻礙，使得部分計畫暫停或終止，出現許多變數。", "fig": "", "q": "承上題，上文提及若是參與一帶一路的國家，偏屬經濟發展相對落後，容易遭遇到許多合作上的阻礙，下列何者並非是參與上述合作計畫容易遇到的風險？", "o": ["掉入債務陷阱", "自然環境破壞", "侵害國家主權", "本國勞力外流"], "a": 3, "e": "一帶一路的風險是債務陷阱、環境破壞、主權受損，不會造成本國勞力外流。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-296", "no": 296, "c": "e4", "src": "社會自修(3) 第 71 頁 統整應用題組 第 4 題", "st": "自修", "ctx": "金磚國家是指五個主要的新興市場國家，分別為巴西、俄羅斯、印度、中國和南非。「金磚五國」國土面積占世界總面積 26%，人口占世界總人口 42%，預測可能在 2050 年成為世界超級強大的經濟體。", "fig": "表(二)：2016 年 GDP（兆美元）／占全球比例——巴西 1.796／2.38%；俄羅斯 1.283／1.70%；印度 2.263／3.00%；中國 11.199／14.82%；南非 0.295／0.39%", "q": "金磚國家是指五個主要的新興市場國家，分別為巴西、俄羅斯、印度、中國和南非。上文提及，這些國家有哪兩個優勢條件，而能有機會在 2050 年成為全球超級強大的經濟體？(甲)財力資本雄厚 (乙)國土面積廣大 (丙)經濟改革開放 (丁)人口總數眾多", "o": ["甲乙", "乙丁", "丙丁", "甲丁"], "a": 1, "e": "金磚國家的共同優勢是國土面積廣大（乙）、人口總數眾多（丁）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-297", "no": 297, "c": "e4", "src": "社會自修(3) 第 71 頁 統整應用題組 第 5 題", "st": "自修", "ctx": "金磚國家是指五個主要的新興市場國家，分別為巴西、俄羅斯、印度、中國和南非。「金磚五國」國土面積占世界總面積 26%，人口占世界總人口 42%，預測可能在 2050 年成為世界超級強大的經濟體。", "fig": "", "q": "承上題，由表(二)可知，中國 GDP 相當高，但如果換算成人均 GDP，卻遠低於許多國家。此現象與中國哪個特色最相關？", "o": ["領土廣大", "工資低廉", "人口眾多", "資金充沛"], "a": 2, "e": "中國 GDP 高，但人口太多，平均到每人就很低。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-298", "no": 298, "c": "e3", "src": "社會自修(3) 第 71 頁 統整應用題組 第 6 題", "st": "自修", "ctx": "金磚國家是指五個主要的新興市場國家，分別為巴西、俄羅斯、印度、中國和南非。「金磚五國」國土面積占世界總面積 26%，人口占世界總人口 42%，預測可能在 2050 年成為世界超級強大的經濟體。", "fig": "", "q": "承上題，中國雖尚未成為超級強大的經濟體，近年卻能吸引許多外國企業設廠投資，使 GDP 不斷上升。下列哪些因素最有可能是中國能成功吸引外資的有利條件？", "o": ["位居交通中樞、國內市場廣大", "國內市場廣大、勞工工資低廉", "勞工工資低廉、基礎建設完善", "基礎建設完善、位居交通中樞"], "a": 1, "e": "中國吸引外資的條件是國內市場廣大、勞工工資低廉。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-299", "no": 299, "c": "e7", "src": "社會自修(3) 第 72 頁 閱讀素養評量 問題一（原為簡答題）", "st": "自修", "ctx": "中國「一帶一路」緣起於 2013 年，藉由重建古絲綢之路，促進亞洲、歐洲和非洲的經貿往來，以公路、鐵路、港口和電力設施等基礎建設投資強化與沿線國家的合作。以巴基斯坦「中巴經濟走廊」為例，中國和巴基斯坦共同修建公路和發電廠，但巴基斯坦近年債務高築；肯亞向中國貸款興建鐵路，貸款總額已逾 80 億美元，延伸路線卻未能實現。", "fig": "", "q": "中國「一帶一路」緣起於 2013 年的「全球基礎設施與經濟合作計畫」，此計畫主要是藉由重建立絲綢之路，促進亞洲、歐洲和非洲的經貿往來。上文提到此計畫是藉由重建古絲綢之路，促進與其他國家或地區的經貿往來。這表示近年中國擴大貿易市場的方向偏向下列何者？", "o": ["向東", "向西", "向南", "向北"], "a": 1, "e": "一帶一路重建古絲路，促進與歐洲、非洲的往來，中國擴大市場的方向偏向西。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-300", "no": 300, "c": "e5", "src": "社會自修(3) 第 72 頁 閱讀素養評量 問題二（原為簡答題）", "st": "自修", "ctx": "中國「一帶一路」緣起於 2013 年，藉由重建古絲綢之路，促進亞洲、歐洲和非洲的經貿往來，以公路、鐵路、港口和電力設施等基礎建設投資強化與沿線國家的合作。以巴基斯坦「中巴經濟走廊」為例，中國和巴基斯坦共同修建公路和發電廠，但巴基斯坦近年債務高築；肯亞向中國貸款興建鐵路，貸款總額已逾 80 億美元，延伸路線卻未能實現。", "fig": "", "q": "承上文，若中國和巴基斯坦的「中巴經濟走廊」經營成功，對中國而言，應最有利於國內哪一經濟分區的出口與進口貿易順利進行？", "o": ["東部地區", "中部地區", "東北地區", "西部地區"], "a": 3, "e": "中巴經濟走廊從新疆經巴基斯坦出海，最有利西部地區的進出口貿易。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-301", "no": 301, "c": "e8", "src": "社會自修(3) 第 72 頁 閱讀素養評量 問題三（原為簡答題）", "st": "自修", "ctx": "中國「一帶一路」緣起於 2013 年，藉由重建古絲綢之路，促進亞洲、歐洲和非洲的經貿往來，以公路、鐵路、港口和電力設施等基礎建設投資強化與沿線國家的合作。以巴基斯坦「中巴經濟走廊」為例，中國和巴基斯坦共同修建公路和發電廠，但巴基斯坦近年債務高築；肯亞向中國貸款興建鐵路，貸款總額已逾 80 億美元，延伸路線卻未能實現。", "fig": "", "q": "承上文，上文提到若開發中國家參與中國「一帶一路」，可能會面臨到哪個困境？", "o": ["背負龐大外債陷入債務陷阱", "國內失業人口大量攀升", "失去所有港口與鐵路所有權", "被迫全面採用人民幣交易"], "a": 0, "e": "參與國家經濟較差，借款建設後可能背負龐大外債，陷入債務陷阱。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-302", "no": 302, "c": "e1", "src": "社會自修(3) 第 73 頁 第2次學力診斷評量 第 1 題", "st": "自修", "ctx": "", "fig": "", "q": "昔日的內蒙古自治區多盛行逐水草而居的游牧活動；但近年則改經營酪農業，並以專業生產區的管理模式經營，提升農產品的品質。上述內容可以解釋下列哪一現象？", "o": ["人均可耕地面積高於世界的平均值", "水資源分配不均而影響工商業發展", "因地制宜，生產具有優勢的農產品", "畜牧技術進步，提高自然環境限制"], "a": 2, "e": "內蒙古改經營酪農專業生產區，是因地制宜、生產具有優勢的農產品。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-303", "no": 303, "c": "e9", "src": "社會自修(3) 第 73 頁 第2次學力診斷評量 第 4 題", "st": "自修", "ctx": "", "fig": "", "q": "在 1990 年代，臺灣有許多工廠遷往中國；近年來，這些前往中國設廠者，已有不少將工廠遷至東南亞或南亞國家。上述這些工廠多是因為哪一項工業生產條件的變化而遷移？", "o": ["礦藏挖掘殆盡", "海運交通受阻", "基本工資上漲", "生產技術落後"], "a": 2, "e": "工廠從中國再遷到東南亞、南亞，是因為中國基本工資上漲。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-304", "no": 304, "c": "e1", "src": "社會自修(3) 第 73 頁 第2次學力診斷評量 第 6 題", "st": "自修", "ctx": "", "fig": "", "q": "中國在經濟改革開放後，傳統農業活動面臨許多問題而須進行轉型，其轉型項目不包括以下哪一項？", "o": ["專業生產區", "機械化耕作", "土地轉作農用", "發展生態農業"], "a": 2, "e": "農業轉型是專業生產、機械化、生態農業；「土地轉作農用」不是轉型項目。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-305", "no": 305, "c": "e1", "src": "社會自修(3) 第 74 頁 第2次學力診斷評量 第 8 題", "st": "自修", "ctx": "", "fig": "", "q": "2023 年初，中國鮮乳價格大降，主要是該國農場畜養乳牛頭數太多，導致鮮乳產量過剩，許多省區的中小型農場出現「倒奶殺牛」的現象。上述現象說明了中國現代農業具有何項特徵？", "o": ["注重永續發展", "形成專業化生產", "可耕地面積減少", "減少科技化生產"], "a": 1, "e": "乳牛養太多造成鮮乳過剩，說明中國農業已形成專業化生產。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-306", "no": 306, "c": "e1", "src": "社會自修(3) 第 74 頁 第2次學力診斷評量 第 9 題", "st": "自修", "ctx": "", "fig": "表(一)：人口數／人均糧食作物產量——黑龍江 3,062 萬人／2,528 公斤；吉林 2,339 萬人／1,786 公斤；內蒙古 2,396 萬人／1,650 公斤；全中國 140,967 萬人／493 公斤", "q": "表(一)為 2023 年中國全國和主要農產省區的人口總數和人均糧食作物產量統計，表中行政區為人均糧食作物產量前三名的行政區。依表判斷，中國現代農業具有下列何項特徵？", "o": ["人均可耕地面積大", "生產優勢的農產品", "農業生態環境惡化", "農業生產技術提升"], "a": 1, "e": "黑龍江、吉林、內蒙古人均糧食產量遠高於全國，代表各地生產具優勢的農產品。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-307", "no": 307, "c": "e5", "src": "社會自修(3) 第 74 頁 第2次學力診斷評量 第 10 題", "st": "自修", "ctx": "", "fig": "表(二)：2023 年最低月薪（人民幣）最多——東部上海 2,590、中部湖北 2,010、西部重慶 2,100、東北遼寧 1,910；最少——東部海南 1,830、中部安徽 1,650、西部青海 1,700、東北黑龍江 1,860", "q": "中國各地最低薪資標準不盡相同，表(二)呈現 2023 年中國四大經濟區內最低月薪最多和最少的省市，根據表中內容判斷，中國各地已出現下列哪一現象？", "o": ["區域發展不均", "對外貿易額大", "內陸市場廣大", "勞動力衰退"], "a": 0, "e": "各經濟區最低薪資差異大，代表區域發展不均。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-308", "no": 308, "c": "e3", "src": "社會自修(3) 第 74 頁 第2次學力診斷評量 第 11 題", "st": "自修", "ctx": "", "fig": "", "q": "阿德是一位美國財經記者，想體驗一年不買中國製造產品的日常生活，結果原本很便宜又容易買到的商品，卻需要大費周章尋找，所付出的價格經常高出原價的 6～7 倍。上述現象與中國何項特色最相關？", "o": ["農礦資源豐富", "西北內陸貿易活絡", "國內消費市場廣大", "勞工多且工資低廉"], "a": 3, "e": "不買中國製產品，東西就變貴又難找，因為中國勞工多且工資低廉。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-309", "no": 309, "c": "e5", "src": "社會自修(3) 第 74 頁 第2次學力診斷評量 第 12 題", "st": "自修", "ctx": "", "fig": "", "q": "近年來，中國許多內陸的民工不再到沿海地區工作，反而留在家鄉就業，使沿海地區爆發嚴重「缺工潮」。下列何者最可能是造成上述現象的原因？", "o": ["內陸地區的物價高漲", "沿海地區的工廠外移", "內陸地區就業機會增加", "沿海地區薪資所得降低"], "a": 2, "e": "內陸地區就業機會增加，民工留在家鄉工作，沿海才會缺工。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-310", "no": 310, "c": "e5", "src": "社會自修(3) 第 75 頁 第2次學力診斷評量 第 13 題", "st": "自修", "ctx": "", "fig": "表(三)：農村居民可支配收入 2021／2022／2023（人民幣）——東部 23,556／25,037／26,907；中部 17,858／19,080／20,518；西部 15,608／16,632／17,911；東北 18,280／18,919／20,300", "q": "表(三)為 2021 至 2023 年中國四大經濟區農村居民可支配收入。僅根據表中資訊判斷，中國各地的農村有何發展特色？", "o": ["區域發展不均", "就業機會減少", "人口結構高齡", "人力資源增加"], "a": 0, "e": "東部農村收入明顯高於其他地區，代表區域發展不均。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-311", "no": 311, "c": "e3", "src": "社會自修(3) 第 75 頁 第2次學力診斷評量 第 14 題", "st": "自修", "ctx": "", "fig": "", "q": "2016 年 11 月巴基斯坦的中資港口——瓜達爾港正式開航，中國之所以積極協助並出資設港，主要是圖(二)中有「中國西部大門」之稱的經濟特區可由中巴鐵路抵達瓜達爾港，為中國打開通往西亞地區的大門。圖中的經濟特區應為下列哪個城市？", "o": ["深圳", "重慶", "喀什", "烏魯木齊"], "a": 2, "e": "有「中國西大門」之稱、可經中巴鐵路到瓜達爾港的經濟特區是喀什。", "rep": false, "img": "g4-q311", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-312", "no": 312, "c": "e5", "src": "社會自修(3) 第 75 頁 第2次學力診斷評量 第 15 題", "st": "自修", "ctx": "", "fig": "", "q": "2007 年 7 月，全球發生金融海嘯危機，導致許多國家消費性電子產品外銷訂單急速衰退，於是中國政府提出「家電下鄉」方案。該方案是將家電產品以補貼方式銷往內陸或偏鄉地區，擴大市場需求的方式，來替代外銷的缺口。上述政策還可以減緩下列哪項問題發生？", "o": ["嚴重的工業汙染", "民生物價逐漸高漲", "區域發展差距加大", "人口性別比例失衡"], "a": 2, "e": "家電下鄉擴大內陸與偏鄉的市場，能減緩區域發展差距。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-313", "no": 313, "c": "e6", "src": "社會自修(3) 第 75 頁 第2次學力診斷評量 第 16 題", "st": "自修", "ctx": "", "fig": "圖(三)：吉利汽車、GEOMETRY、LYNK&CO（領克）、PROTON、LOTUS（蓮花）、VOLVO（富豪）等汽車品牌標誌", "q": "圖(三)為中國民營企業浙江吉利控股集團旗下部分汽車品牌，有的是本國自行研發，有的則是收購國外品牌（如富豪 Volvo、蓮花 Lotus）。該企業積極直接在國外投資企業、收購的原因為下列何者？", "o": ["將總部外移到國外", "快速打入歐美市場", "限制企業投資金額", "大幅降低生產成本"], "a": 1, "e": "吉利收購 Volvo、Lotus 等國外品牌，可以快速打入歐美市場。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-314", "no": 314, "c": "e5", "src": "社會自修(3) 第 75 頁 第2次學力診斷評量 第 17 題", "st": "自修", "ctx": "", "fig": "", "q": "2024 年 3 月，中國完成一條西電東送的管線輸送路線，每年可從陝西省向河南與安徽省輸送約 360 億度的電量。上述建設應屬於下列何項區域發展政策？", "o": ["中部崛起", "東北振興", "西部大開發", "東部率先發展"], "a": 2, "e": "西電東送屬於西部大開發。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-315", "no": 315, "c": "e5", "src": "社會自修(3) 第 76 頁 第2次學力診斷評量 第 20 題", "st": "自修", "ctx": "", "fig": "", "q": "2023 年中國為了能北貨南運，與俄羅斯達成協議，將圖(四)中的甲港口（海參崴）作為國內貿易中轉口岸，並非選擇大連港，由此地運輸至中國南方，可使距離成本縮短。上述作法應屬於下列何項區域發展政策？", "o": ["西部大開發", "中部崛起", "東北振興", "東部率先發展"], "a": 2, "e": "經俄羅斯海參崴港北貨南運，屬於東北振興。", "rep": false, "img": "g4-q315", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-316", "no": 316, "c": "e3", "src": "社會自修(3) 第 76 頁 第2次學力診斷評量 題組 第 21 題", "st": "自修", "ctx": "1980 年代中國實施經濟改革開放，於各地設立經濟特區，最早多集中在福建省和廣東省沿海一帶，近年才設立內陸唯一的經濟特區。", "fig": "", "q": "中國經濟特區最早設立的地區具有下列哪一優勢？", "o": ["擁有豐富且便宜的原料", "對外交通便利，吸引國外資金", "距離中亞和歐洲地區較近", "地形平坦遼闊，腹地較為廣大"], "a": 1, "e": "最早設立經濟特區的東南沿海對外交通便利，容易吸引國外資金。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-317", "no": 317, "c": "e3", "src": "社會自修(3) 第 76 頁 第2次學力診斷評量 題組 第 22 題", "st": "自修", "ctx": "1980 年代中國實施經濟改革開放，於各地設立經濟特區，最早多集中在福建省和廣東省沿海一帶，近年才設立內陸唯一的經濟特區。", "fig": "", "q": "承上題，上文中唯一位於內陸的經濟特區，應是在下列哪個省級行政區內？", "o": ["西藏自治區", "寧夏回族自治區", "內蒙古自治區", "新疆維吾爾自治區"], "a": 3, "e": "唯一位於內陸的經濟特區喀什，在新疆維吾爾自治區。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-sez"], "chk": ""}, {"id": "g4-318", "no": 318, "c": "e3", "src": "社會自修(3) 第 76 頁 第2次學力診斷評量 題組 第 23 題", "st": "自修", "ctx": "1980 年代中國實施經濟改革開放，於各地設立經濟特區，最早多集中在福建省和廣東省沿海一帶，近年才設立內陸唯一的經濟特區。", "fig": "", "q": "承上題，中國設立經濟特區，可藉由外資引進哪些工業發展的條件進入？", "o": ["市場、勞工", "勞工、資金", "資金、技術", "技術、原料"], "a": 2, "e": "設立經濟特區可藉外資引進資金與技術。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-319", "no": 319, "c": "e5", "src": "社會自修(3) 第 76 頁 第2次學力診斷評量 題組 第 24 題", "st": "自修", "ctx": "", "fig": "", "q": "2000 年起，中國政府提出多項均衡區域的政策，將中國畫分為圖(五)的四大經濟區。圖中哪處境內因重工業發展甚早，故近年礦產已有枯竭的現象，再加上工廠的設備不夠新穎，區內的工業產值不斷衰退，因而亟待工業轉型？", "o": ["甲", "乙", "丙", "丁"], "a": 2, "e": "重工業發展早、礦產枯竭、設備老舊的是東北（丙）。", "rep": true, "img": "g4-q319", "imgnote": "", "fh": "", "maps": ["g4-map-region"], "chk": ""}, {"id": "g4-320", "no": 320, "c": "e5", "src": "社會自修(3) 第 76 頁 第2次學力診斷評量 題組 第 25 題", "st": "自修", "ctx": "2000 年起，中國政府提出多項均衡區域的政策，將中國畫分為圖(五)的四大經濟區。", "fig": "", "q": "承上題，圖中甲區（西部地區）因區域發展相對較為落後，已和其他地區產生區域失衡的現象。但若要開發該區域，可以憑藉當地哪項優勢？", "o": ["勞工充足，且工資低廉", "海運便利，有利產品出口", "面積廣大，吸引外資投入", "礦產資源豐富，可對外出口"], "a": 3, "e": "西部地區（甲）礦產資源豐富，可以發展礦產開採並輸出。", "rep": false, "img": "g4-q319", "imgnote": "", "fh": "", "maps": ["g4-map-region"], "chk": ""}, {"id": "g4-321", "no": 321, "c": "e3", "src": "評量單 第 7 回 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "「這個國家因勞工眾多且工資低廉，吸引大量外國企業前去設廠，故有『世界工廠』之稱。」上文提及的國家應為下列何者？", "o": ["美國", "日本", "英國", "中國"], "a": 3, "e": "勞工多、工資低、外商設廠，就是「世界工廠」中國。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-322", "no": 322, "c": "e3", "src": "評量單 第 7 回 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "中國實施經濟改革開放措施後，吸引許多企業前往當地設廠，依據產業的特性判斷，下列哪一種產業前往設廠的時間相對較晚？", "o": ["成衣", "紡織", "製鞋", "汽車"], "a": 3, "e": "初期以成衣、紡織、製鞋等勞力密集產業為主，汽車等技術較高的產業較晚才進駐。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-323", "no": 323, "c": "e1", "src": "評量單 第 7 回 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "中國三級產業就業人口中，下列哪一類型就業人口占其比例最多？", "o": ["第一級產業", "第二級產業", "第三級產業", "無法判斷"], "a": 2, "e": "第三級產業（服務業）就業人口持續上升，現已最多。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-324", "no": 324, "c": "e5", "src": "評量單 第 7 回 第 4 題", "st": "講義", "ctx": "", "fig": "", "q": "「這個地區擁有豐富自然資源，但對外交通不便，工商業發展緩慢，因此中國提出青藏鐵路、南水北調等計畫，將中國煤、鐵、石油等資源輸往他區。」上文中提及的策略應為下列何者？", "o": ["東北振興", "西部開發", "中部崛起", "東部率先發展"], "a": 1, "e": "資源豐富但交通不便的是西部，對策是西部大開發。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-325", "no": 325, "c": "e3", "src": "評量單 第 7 回 第 5 題", "st": "講義", "ctx": "", "fig": "", "q": "港珠澳大橋是連接香港、澳門及珠海等三地的跨海大橋，依據三個城市的位置判斷，行駛於該橋梁上見到的應為下列哪一河口？", "o": ["黃河口", "海河口", "長江口", "珠江口"], "a": 3, "e": "香港、澳門、珠海都在珠江口。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-326", "no": 326, "c": "e5", "src": "評量單 第 7 回 第 6 題", "st": "講義", "ctx": "", "fig": "", "q": "交通運輸是工商業發展的條件之一，中國自經濟改革開放後，積極進行各地的鐵公路等交通建設，但礙於自然環境限制，右圖中哪一地區的鐵公路網密度可能最低？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "丁是西部地區，地形崎嶇、氣候乾燥，鐵公路網最稀疏。", "rep": false, "img": "g4-p6", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-327", "no": 327, "c": "e5", "src": "評量單 第 7 回 第 7 題", "st": "講義", "ctx": "", "fig": "", "q": "隨著中國經濟開放，各地區經濟開始出現差異，其中某地區是中國傳統重工業重鎮，但近年因為礦產枯竭及工廠設備老舊等問題，故政府提出哪一因應措施？", "o": ["東北振興", "中部崛起", "西部開發", "東部率先發展"], "a": 0, "e": "傳統重工業、礦產枯竭、設備老舊，是東北地區，對策是東北振興。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-328", "no": 328, "c": "e3", "src": "評量單 第 7 回 第 8 題", "st": "講義", "ctx": "", "fig": "", "q": "西元 1273 年，馬可波羅翻越帕米爾高原，抵達這個位於塔里木盆地邊緣的綠洲。這裡是古絲綢之路必經城市，張騫、班超先後在當地駐守十幾年，現為中國第六個經濟特區。上述城市應為下列何者？", "o": ["廈門", "汕頭", "珠海", "喀什"], "a": 3, "e": "位於塔里木盆地邊緣、第六個經濟特區的是新疆喀什。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-329", "no": 329, "c": "e1", "src": "評量單 第 7 回 第 9 題", "st": "講義", "ctx": "", "fig": "", "q": "右表為中國與澳洲可耕地總面積及人均可耕地面積資料，影響表中中國後者數據與澳洲有顯著差異的主因為何？", "o": ["地形起伏小", "人口總數多", "氣候較乾燥", "農業技術差"], "a": 1, "e": "中國可耕地總面積比澳洲大，但人口太多，平均每人分到的耕地很少。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-330", "no": 330, "c": "e1", "src": "評量單 第 7 回 第 10 題", "st": "講義", "ctx": "", "fig": "", "q": "隨著經濟發展，中國三級產業的產值有顯著變化，其中自 1980 年迄今，第一級產業占總產業產值的比例呈現何種變化趨勢？", "o": ["持續上升", "持續下降", "先升後降", "先降後升"], "a": 1, "e": "經濟發展後，第一級產業的產值比例持續下降。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-331", "no": 331, "c": "e6", "src": "評量單 第 8 回 第 1 題", "st": "講義", "ctx": "", "fig": "", "q": "中國為了擴大經濟版圖，近年來積極與各國簽訂自由貿易協定，於 2020 年簽署區域全面經濟夥伴協定，該協定的簡稱為何？", "o": ["WTO", "GDP", "RCEP", "APEC"], "a": 2, "e": "區域全面經濟夥伴協定的簡稱是 RCEP。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-332", "no": 332, "c": "e6", "src": "評量單 第 8 回 第 2 題", "st": "講義", "ctx": "", "fig": "", "q": "圖(一)是 2024 年世界前四大貿易總額國家，其中何者應為中國？", "o": ["甲", "乙", "丙", "丁"], "a": 0, "e": "中國是世界貿易總額第一的國家。", "rep": false, "img": "g4-p82", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-333", "no": 333, "c": "e6", "src": "評量單 第 8 回 第 3 題", "st": "講義", "ctx": "", "fig": "", "q": "中國為了擴大經濟版圖，積極與各國簽訂自由貿易協定，其中 2020 年簽署的區域全面經濟夥伴協定除了東南亞多國之外，其簽署的國家不包括下列哪一國家？", "o": ["日本", "澳洲", "印度", "南韓"], "a": 2, "e": "RCEP 是東協 10 國加中、日、韓、澳、紐，印度沒有加入。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-334", "no": 334, "c": "e4", "src": "評量單 第 8 回 第 4 題", "st": "講義", "ctx": "", "fig": "", "q": "根據中國國家統計局結果顯示，自 2000 年開始，國外投資中國產業中製造業占 80%，但 2023 年時僅剩 28%，但房地產業、租賃和商務服務業都有增加的趨勢。根據上述畫線處內容，何種原因讓中國擁有龐大的消費潛力？", "o": ["人民所得增加", "一帶一路政策改變", "土地面積廣大", "電子商務銷售衰退"], "a": 0, "e": "人民所得增加、消費力提升，外資才轉向服務業。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-335", "no": 335, "c": "e7", "src": "評量單 第 8 回 第 5 題", "st": "講義", "ctx": "", "fig": "", "q": "「一帶一路」是近年來中國提出的經濟政策，其中「一帶」主要是以圖(二)中何者為路線基礎進行規畫？", "o": ["甲", "乙", "丙", "丁"], "a": 1, "e": "「一帶」是陸上的絲綢之路經濟帶，沿著古絲路（乙）。", "rep": false, "img": "g4-p85", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-336", "no": 336, "c": "e7", "src": "評量單 第 8 回 第 6 題", "st": "講義", "ctx": "", "fig": "", "q": "中國推動一帶一路政策的目的不包括下列何者？", "o": ["消化過剩工業產能", "獲得穩定能源供給", "擴大對外貿易範圍", "透過併吞擴大領土"], "a": 3, "e": "一帶一路是經濟合作，不是併吞領土。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-337", "no": 337, "c": "e7", "src": "評量單 第 8 回 第 7 題", "st": "講義", "ctx": "圖(三)為中國於 2013 年提出新經濟政策的路線，該政策依其位置，分為甲、乙兩路線。", "fig": "", "q": "甲路線是沿著昔日絲綢之路為基礎進行規畫，而該路線在中國的起點城市位於下列何地？", "o": ["上海", "西安", "北京", "廣州"], "a": 1, "e": "絲綢之路經濟帶的起點是西安。", "rep": false, "img": "g4-p87", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-338", "no": 338, "c": "e7", "src": "評量單 第 8 回 第 8 題", "st": "講義", "ctx": "圖(三)為中國於 2013 年提出新經濟政策的路線，該政策依其位置，分為甲、乙兩路線。", "fig": "", "q": "甲路線離開中國國境後，最先進入的應為哪一地區？", "o": ["歐洲", "美洲", "南亞", "中亞"], "a": 3, "e": "由新疆出境後最先進入中亞。", "rep": false, "img": "g4-p87", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-339", "no": 339, "c": "e7", "src": "評量單 第 8 回 第 9 題", "st": "講義", "ctx": "圖(三)為中國於 2013 年提出新經濟政策的路線，該政策依其位置，分為甲、乙兩路線。", "fig": "", "q": "乙路線所聯繫的地區不包括下列哪一大洲？", "o": ["亞洲", "美洲", "歐洲", "非洲"], "a": 1, "e": "海上絲綢之路經東南亞、印度洋、非洲到歐洲，不經過美洲。", "rep": false, "img": "g4-p87", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-340", "no": 340, "c": "e7", "src": "評量單 第 8 回 第 10 題", "st": "講義", "ctx": "圖(三)為中國於 2013 年提出新經濟政策的路線，該政策依其位置，分為甲、乙兩路線。", "fig": "", "q": "乙路線是沿著哪一個中國探險家的路徑規畫？", "o": ["玄奘", "張騫", "鄭和", "文成公主"], "a": 2, "e": "21 世紀海上絲綢之路沿著鄭和下西洋的航路。", "rep": false, "img": "g4-p87", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-341", "no": 341, "c": "e4", "src": "114上翰林社會2上A卷 卷6 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國今日已是世界重要消費市場，有「世界市場」之稱，吸引許多世界知名品牌進駐搶食市場大餅，中國的龐大消費力更成為國際貿易的重要談判籌碼。下列何者不是中國消費力龐大的原因？", "o": ["人口數量龐大", "平均收入提高", "產業高度發展", "文化擴散快速"], "a": 3, "e": "人口多、收入提高、產業發展都讓消費力變大；文化擴散和消費力無關。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-342", "no": 342, "c": "e3", "src": "114上翰林社會2上A卷 卷6 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "造就中國成為世界工廠的原因來自低廉的生產成本，可以輸出紡織、玩具等產品，此種產業最主要的獲利來源是因為哪一項生產要素成本占有優勢？", "o": ["原料", "勞力", "動力", "交通"], "a": 1, "e": "紡織、玩具是勞力密集產業，中國工資低，勞力成本占優勢。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-343", "no": 343, "c": "e9", "src": "114上翰林社會2上A卷 卷6 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "商業週刊指出：「於中國設廠的某科技集團，近年來逐漸將廠房遷移至內陸，此項舉動被認為可降低生產成本，增加企業競爭力而獲好評。」上文中的「降低生產成本」是指下列何者？", "o": ["原料", "動力", "勞工", "運輸"], "a": 2, "e": "中國內陸的工資比沿海低，遷到內陸可降低勞工成本。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-344", "no": 344, "c": "e1", "src": "114上翰林社會2上A卷 卷6 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(一)為中國某個牧場所購置的畜牧設備，從圖中可以判斷出，此牧場經營發展的方向應該為何？", "o": ["開發休閒牧場，以達到環境保育的目的", "科技化經營，提高產量，提升產品品質", "維持傳統畜牧方式，避免傳統文化失傳", "發展生物科技產業，研發最新生技產品"], "a": 1, "e": "使用機械化擠乳設備，是科技化經營、提高產量與品質。", "rep": false, "img": "g4-a6", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-345", "no": 345, "c": "e1", "src": "114上翰林社會2上A卷 卷6 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "新聞報導：「三年內將在中國培育 100 萬名農業無人機操作員，用以解決當前農藥噴灑問題。」上述為中國農業轉型的現況，下列何者是主要的造成因素？", "o": ["氣候變遷導致蝗災頻繁", "農業生產類型日趨多元", "傳統農業受自然環境的限制大", "第一級產業就業人口比例下降"], "a": 3, "e": "務農人口減少、人力不足，才需要用無人機噴灑農藥。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-346", "no": 346, "c": "e7", "src": "114上翰林社會2上A卷 卷6 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國推動「一帶一路」政策，希望藉由陸路、海路兩路線，與沿線國家互補、合作。上述沿線國家不包括下列何者？", "o": ["歐洲", "非洲", "中亞", "北美洲"], "a": 3, "e": "一帶一路連接亞、歐、非，不包括北美洲。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-347", "no": 347, "c": "e1", "src": "114上翰林社會2上A卷 卷6 實戰模擬題 1", "st": "考卷", "ctx": "", "fig": "", "q": "中國農民收入偏低，許多農村居民須外出打工以改善生計，形成許多農民工。雖然農民工供應了都市勞力需求，但也帶來許多問題。上述造成中國農民普遍貧困的原因為何？", "o": ["人均可耕地小", "農業人口增加", "農業產量偏低", "農業轉型失敗"], "a": 0, "e": "中國山多平原少、人口多，人均可耕地小，加上降水與人口分布不均，農業發展受限。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-348", "no": 348, "c": "e9", "src": "114上翰林社會2上A卷 卷6 實戰模擬題 2", "st": "考卷", "ctx": "", "fig": "", "q": "中國的生產優勢近年面臨各種挑戰，下列何人的說法最為正確？", "o": ["張三：人口數量減少，勞力供應漸趨不足", "李四：勞工薪資下跌，生產成本逐漸降低", "王五：與各國往來頻繁，容易受國際情勢影響", "方六：交通建設發展緩慢，區域發展差距擴大"], "a": 2, "e": "中國和各國貿易往來頻繁，容易受貿易戰等國際情勢影響。中國人口仍是世界前幾名、薪資是上漲、交通建設也很快。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": ["g4-map-region"], "chk": ""}, {"id": "g4-349", "no": 349, "c": "e2", "src": "114上翰林社會2上B卷 卷6 第 22 題", "st": "考卷", "ctx": "", "fig": "", "q": "「中國某行政區經常出現嚴重霧霾天氣，該行政區會呼籲民眾盡量待在室內，並對區內大量的重工業進行限制，暫停煤礦開採與加工，同時鼓勵民眾改搭公共運輸，以期減少汙染排放。」文中提及的行政區最可能為圖(十二)何地？", "o": ["甲", "乙", "丙", "丁"], "a": 0, "e": "中國的煤礦與重工業主要分布在北部，甲最可能。", "rep": false, "img": "g4-b22", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-350", "no": 350, "c": "e6", "src": "114上翰林社會2上C卷 卷5 進階思考題 1", "st": "考卷", "ctx": "", "fig": "", "q": "中國新車品牌「領克」為中國吉利企業併購歐洲富豪汽車後所推出的新品牌。近幾年中國政府鼓勵大型企業併購歐美企業，主要是為了獲得哪項發展優勢？", "o": ["中國可快速獲取高科技產業技術", "增加中國移民在他國的就業機會", "中國獲准在美國境內設經濟特區", "有利於發展兩國之間的交通建設"], "a": 0, "e": "透過併購可以快速獲取技術、進入歐美市場。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-351", "no": 351, "c": "e5", "src": "114上翰林社會2上C卷 卷5 進階思考題 2", "st": "考卷", "ctx": "", "fig": "", "q": "圖(七)是 2020 年外資企業在中國的登記數量，形成數量分布不均的因素為何？", "o": ["礦產能源分布不均", "區域之間經濟落差", "與鄰國的距離遠近", "維護現有生態環境"], "a": 1, "e": "東部人口多、勞力與市場充足，經濟發展好，外資集中；西部較少，反映區域經濟落差。", "rep": false, "img": "g4-cx2", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-352", "no": 352, "c": "e2", "src": "114上翰林社會2上C卷 卷5 進階思考題 3", "st": "考卷", "ctx": "", "fig": "", "q": "圖(八)為中國煤、鐵、石油的分布狀況。根據圖中內容，下列敘述何者正確？", "o": ["人口集中在礦產分布地區", "中國北部的重工業比例高", "礦產分布受河川流向影響", "受限於地形礦產難以運出"], "a": 1, "e": "煤鐵石油多在北部，有利發展重工業。", "rep": false, "img": "g4-cx3", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-353", "no": 353, "c": "e4", "src": "114上翰林社會2上C卷 卷5 進階思考題 4", "st": "考卷", "ctx": "", "fig": "", "q": "中國改革開放後經濟逐步發展，由「世界工廠」轉變為「世界市場」。下列何種現象，能夠說明上述轉變？", "o": ["許多工業產品由中國輸往全球", "許多來自各國的勞工湧入中國", "消費能力的提升帶動企業進駐", "中國與他國簽訂各項合作協議"], "a": 2, "e": "人民消費力提升，吸引各國企業進駐銷售，中國成為世界市場。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-354", "no": 354, "c": "e5", "src": "114上翰林社會2上C卷 卷5 進階思考題 5", "st": "考卷", "ctx": "", "fig": "", "q": "中國政府為了平衡區域發展，推出相關的經濟政策。其中，東北振興政策主要的目的為何？", "o": ["提升高科技產業優勢", "推動傳統重工業轉型", "大量輸出煤鐵等礦產", "發展成內陸交通樞紐"], "a": 1, "e": "東北礦產枯竭、設備老舊，東北振興是推動傳統重工業轉型。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-355", "no": 355, "c": "e5", "src": "114上翰林社會2上C卷 卷5 進階思考題 6", "st": "考卷", "ctx": "", "fig": "", "q": "圖(九)為中國某項重要的建設，目的是帶動西部地區的經濟成長，同時提升東部地區的產能。這項建設最有可能為下列何者？", "o": ["能源管線", "人工運河", "跨區公路", "高速鐵路"], "a": 0, "e": "把西部的天然氣、電力送往東部（西氣東輸、西電東送），是能源管線。", "rep": false, "img": "g4-cx6", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-356", "no": 356, "c": "e8", "src": "114上翰林社會2上C卷 卷5 進階思考題 7", "st": "考卷", "ctx": "", "fig": "", "q": "中國實施一帶一路政策投資許多開發中國家，然而有些國家因無力償還債務而發生主權和利益糾紛，下列哪個事件與上述情況有關連？", "o": ["希臘將皮雷埃夫斯港口所有權給中國", "中國大量投資德國庫卡的工業機器人", "中國比亞迪電動車產量成為世界第一", "印度退出區域全面經濟伙伴協定（RCEP）"], "a": 0, "e": "希臘把港口所有權賣給中國，牽涉一帶一路的主權問題。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-357", "no": 357, "c": "e1", "src": "114上翰林社會2上C卷 卷6 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國領土面積廣大，位居世界第三，但人均可耕地面積卻低於世界平均，其原因包括下列何者？", "o": ["產業結構改變，導致農業勞動力不足", "地形以山地和高原為主，且比例較高", "降水量不足，居民傳統多以畜牧維生", "實施一胎化政策，造成人口組成失衡"], "a": 1, "e": "中國山多平原少（山地、高原比例高），加上人口多，人均可耕地少。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-358", "no": 358, "c": "e8", "src": "114上翰林社會2上C卷 卷6 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "2022 年斯里蘭卡政府宣布面臨破產，並宣稱這是該國有史以來最嚴重經濟危機。其中一個重要原因與中國有關。上述與中國有關的原因應為下列何者？", "o": ["大量中國移民遷至斯里蘭卡", "向斯里蘭卡大量傾銷農產品", "禁止斯里蘭卡出口中國市場", "斯里蘭卡參與中國投資政策"], "a": 3, "e": "斯里蘭卡參與一帶一路，借款建設後無力償還債務。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-359", "no": 359, "c": "e5", "src": "114上翰林社會2上C卷 卷6 進階思考題 1", "st": "考卷", "ctx": "", "fig": "", "q": "近年來，中國大量興建鐵路與高速公路，圖(七)是中國主要鐵路分布圖，從圖中可看出中國鐵路分布具有下列哪項特色？", "o": ["鐵路集中於西北部地區", "鐵路路線主要為東西向", "高速鐵路多分布在西部", "西半部的鐵路分布較少"], "a": 3, "e": "西半部地形崎嶇、人口少，鐵路分布較少。", "rep": false, "img": "g4-cy1", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-360", "no": 360, "c": "e3", "src": "114上翰林社會2上C卷 卷6 題組 2", "st": "考卷", "ctx": "中國於 1978 年實施了某項政策，吸引大量外國資金到中國投資設廠，表(二)為中國近代都市化程度變化。", "fig": "", "q": "隨著表中都市化程度的變化，同時期中國可能會出現下列哪種現象？", "o": ["大量人口移入都市", "出生率逐漸下降", "農耕人口大量增加", "都市環境品質提升"], "a": 0, "e": "改革開放後工商業發展，大量人口移入都市，都市化程度提高。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-361", "no": 361, "c": "e4", "src": "114上金安翰版社會2上A卷 第5次練習 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "右圖為近年中國與美國的國內生產毛額比較。依圖判斷，中國的國內生產毛額與美國的差距曲線，最接近下列何者？", "o": ["曲線 (A)", "曲線 (B)", "曲線 (C)", "曲線 (D)"], "a": 3, "e": "中國 GDP 成長比美國快，兩國差距逐年縮小，差距曲線往下降，選 (D)。", "rep": false, "img": "g4-j18", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-362", "no": 362, "c": "e1", "src": "114上金安翰版社會2上A卷 第5次練習 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "「蒙牛」以極快的速度登上中國乳製品龍頭，該公司興起於中國放牧區，為因應市場需求，畜牧戶採企業化經營方式，該公司的乳源蒐集區更擴大到游牧區。根據中國的畜牧區分布判斷，「蒙牛」乳品來源最可能位於右上圖中何處？", "o": ["甲", "乙", "丙", "丁"], "a": 1, "e": "乙是內蒙古高原，東側為放牧區、西側為游牧區。", "rep": false, "img": "g4-j19", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-363", "no": 363, "c": "e9", "src": "114上金安翰版社會2上A卷 第5次練習 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "右圖為近年日本對東南亞和中國的投資金額統計，圖中顯示 2012 年後日本對中國投資額不斷減少，而對東南亞地區明顯增加。主因為中國工業發展的哪項優勢已逐漸消失？", "o": ["廉價的勞力", "廣大的市場", "便利的運輸", "充足的資金"], "a": 0, "e": "中國提高基本工資，勞力成本上升，日本企業轉往東南亞。", "rep": false, "img": "g4-j20", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-364", "no": 364, "c": "e1", "src": "114上金安翰版社會2上A卷 第5次練習 第 21 題", "st": "考卷", "ctx": "", "fig": "", "q": "右表為某年各國人均可耕地面積比較，由表中資訊發現，中國可耕地面積雖較澳洲大，但人均可耕地面積卻比澳洲少很多。造成上述現象與中國哪項地理特性關係最密切？", "o": ["地形種類複雜", "氣候類型多樣", "土壤太過貧瘠", "人口數量龐大"], "a": 3, "e": "中國有 14 億人口，平均每人分到的耕地很少。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-365", "no": 365, "c": "e3", "src": "114上金安翰版社會2上A卷 第5次練習 第 22 題", "st": "考卷", "ctx": "", "fig": "", "q": "1980 年代起，中國陸續設立了五個經濟特區，並開放沿海城市，主要是考慮東部經濟帶具有右圖中哪幾項工業區位優勢？", "o": ["甲乙丙", "乙丁戊", "丙戊庚", "丁己庚"], "a": 2, "e": "東部經濟特區的優勢是勞工便宜（丙）、交通便利（戊）、土地便宜（庚）。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-366", "no": 366, "c": "e3", "src": "114上金安翰版社會2上A卷 第5次練習 第 23 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國於 1980 年代陸續在東南沿海設置 5 個經濟特區。有學者說：「中國的經濟特區是模仿臺灣經驗而來。」上述「臺灣經驗」指的是下列哪種類型的工業區？", "o": ["勞工區位的加工出口區", "原料充足的水泥工業區", "交通便利的石化專業區", "附加價值高的科學園區"], "a": 0, "e": "中國經濟特區以勞力密集的加工出口業為主，類似臺灣的加工出口區。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-367", "no": 367, "c": "e6", "src": "114上金安翰版社會2上A卷 第5次練習 第 24 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國與日本、南韓、東南亞多國、澳洲、紐西蘭等國，在 2020 年簽署「RCEP」。參與協定國享有右表哪些優惠？", "o": ["甲乙", "甲丙", "乙丁", "丙丁"], "a": 1, "e": "RCEP 的優惠是關稅減免、降低進出口限制；統一貨幣、統一規格是歐盟才有的。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-368", "no": 368, "c": "e5", "src": "114上金安翰版社會2上A卷 第5次練習 第 25 題", "st": "考卷", "ctx": "", "fig": "", "q": "春節是中國人相當重視的節慶，由於返鄉車票難訂，因此近年來也開啟了「反向春運」浪潮，就是年輕人選擇將住在老家的父母和孩子接來自己工作地點過年，春節後再返回老家。上述「反向春運」的地點最可能集中在下列哪一張圖示的灰色地區？", "o": ["圖 (A)", "圖 (B)", "圖 (C)", "圖 (D)"], "a": 0, "e": "年輕人的工作地點多集中在經濟發達、工作機會多的東部沿海，選灰色在沿海的 (A)。", "rep": false, "img": "g4-j25", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-369", "no": 369, "c": "e7", "src": "114上金安翰版社會2上A卷 第5次練習 題組 (一) 26", "st": "考卷", "ctx": "近年來中國為了消化過剩的產能，於 2013 年提出「一帶一路」政策，全名為「絲綢之路經濟帶」及「21 世紀海上絲綢之路」，右圖為該政策的兩條主要路線，中國參與了沿線國家基礎建設，促使經貿的合作關係更加密切。", "fig": "", "q": "甲路線在中國境內經過的範圍，大多屬於何種氣候類型？", "o": ["高地氣候", "溫帶季風氣候", "溫帶沙漠氣候", "副熱帶季風氣候"], "a": 2, "e": "甲路線是古代絲綢之路，在中國境內多屬溫帶沙漠氣候。", "rep": false, "img": "g4-j26", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-370", "no": 370, "c": "e7", "src": "114上金安翰版社會2上A卷 第5次練習 題組 (一) 27", "st": "考卷", "ctx": "近年來中國為了消化過剩的產能，於 2013 年提出「一帶一路」政策，全名為「絲綢之路經濟帶」及「21 世紀海上絲綢之路」，右圖為該政策的兩條主要路線，中國參與了沿線國家基礎建設，促使經貿的合作關係更加密切。", "fig": "", "q": "乙路線是「鄭和下西洋」的海路，會經過下列哪些海域？", "o": ["太平洋、大西洋", "太平洋、印度洋", "大西洋、印度洋", "大西洋、北極海"], "a": 1, "e": "乙路線由中國東南沿海的太平洋，經東南亞、南亞到印度洋。", "rep": false, "img": "g4-j26", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-371", "no": 371, "c": "e3", "src": "114上金安翰版社會2上A卷 第5次練習 題組 (二) 28", "st": "考卷", "ctx": "中國有首歌《春天的故事》歌詞如下：「一九七九年，那是一個春天，有一位老人在中國的南海邊畫了一個圈，神話般地崛起座座城，奇蹟般地聚起座座金山……。」近年來，中國雖然經濟成長快速，但也造成沿海與內陸、都市與鄉村的區域發展不均，2000 年起，中國為了達成區域均衡發展，劃分為東部、中部、西部和東北地區四大經濟區，如右圖所示。", "fig": "", "q": "歌詞中的「畫了一個圈」，是指當時的哪項經濟政策？", "o": ["中部崛起", "西部大開發", "設立經濟特區", "振興東北老工業基地"], "a": 2, "e": "改革開放後在東南沿海設立經濟特區，帶動經濟發展。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-372", "no": 372, "c": "e5", "src": "114上金安翰版社會2上A卷 第5次練習 題組 (二) 29", "st": "考卷", "ctx": "中國有首歌《春天的故事》歌詞如下：「一九七九年，那是一個春天，有一位老人在中國的南海邊畫了一個圈，神話般地崛起座座城，奇蹟般地聚起座座金山……。」近年來，中國雖然經濟成長快速，但也造成沿海與內陸、都市與鄉村的區域發展不均，2000 年起，中國為了達成區域均衡發展，劃分為東部、中部、西部和東北地區四大經濟區，如右圖所示。", "fig": "", "q": "圖中丙區是目前外資積極投入的新興地區，主要是丙區比乙區具有下列哪項優勢？", "o": ["工資較低廉", "市場較廣大", "運輸較便利", "資金較充裕"], "a": 0, "e": "丙是中部地區，工資比東部（乙）低廉，吸引外資進駐。", "rep": false, "img": "g4-j28", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-373", "no": 373, "c": "e5", "src": "114上金安翰版社會2上A卷 第5次練習 題組 (二) 30", "st": "考卷", "ctx": "中國有首歌《春天的故事》歌詞如下：「一九七九年，那是一個春天，有一位老人在中國的南海邊畫了一個圈，神話般地崛起座座城，奇蹟般地聚起座座金山……。」近年來，中國雖然經濟成長快速，但也造成沿海與內陸、都市與鄉村的區域發展不均，2000 年起，中國為了達成區域均衡發展，劃分為東部、中部、西部和東北地區四大經濟區，如右圖所示。", "fig": "", "q": "圖中的丁區，在工業發展上具有哪項最大的優勢？", "o": ["資源豐富，工礦原料充足", "鐵路發達，有利產品出口", "面積廣大，土地取得容易", "教育發達，勞工素質較高"], "a": 0, "e": "丁是西部地區，煤、石油、天然氣等資源豐富。", "rep": false, "img": "g4-j28", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-m1", "no": null, "c": "e5", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "中國四大經濟區與政策的配對，何者正確？", "o": ["東北地區—中部崛起", "西部地區—西部大開發", "中部地區—東北振興", "東部地區—西部大開發"], "a": 1, "e": "東部率先發展、中部崛起、東北振興、西部大開發，要依地區正確配對。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-m2", "no": null, "c": "e5", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "中國哪一個經濟區昔日是重工業重心，近年面臨礦產枯竭、設備老舊的問題？", "o": ["東部地區", "中部地區", "東北地區", "西部地區"], "a": 2, "e": "東北煤鐵石油豐富，是傳統重工業區，現在礦產枯竭、設備老舊，推動東北振興。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-m3", "no": null, "c": "e3", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "中國最早設立的 5 個經濟特區，不包括下列哪一個？", "o": ["深圳", "廈門", "海南", "喀什"], "a": 3, "e": "1980 年代設深圳、珠海、汕頭、廈門、海南；喀什是 2010 年才設立的內陸經濟特區。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-m4", "no": null, "c": "e3", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "改革開放初期，東南沿海經濟特區吸引外資的優勢，不包括下列何者？", "o": ["交通便利", "工資低廉", "土地便宜", "技術先進"], "a": 3, "e": "當時中國技術並不先進，優勢是交通、勞力、土地。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-m5", "no": null, "c": "e1", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "中國人均可耕地面積只有約 0.08 公頃，遠低於世界平均，主要原因是什麼？", "o": ["人口太多且農地轉作他用", "國土面積太小", "農業技術落後", "全部都是沙漠"], "a": 0, "e": "中國國土大，但人口眾多，加上工商業發展使農地轉作建地，人均可耕地很小。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-m6", "no": null, "c": "e1", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "內蒙古把傳統游牧轉型為大規模的酪農場，這屬於中國農業轉型的哪一個方向？", "o": ["生態農業", "專業生產區", "休閒農業", "山牧季移"], "a": 1, "e": "因地制宜生產最有優勢的農產品，形成規模化的專業生產區。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-m7", "no": null, "c": "e7", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "「一帶一路」中的「一帶」與「一路」分別是指什麼？", "o": ["陸路、海路", "海路、陸路", "鐵路、航空", "公路、管線"], "a": 0, "e": "一帶是陸上的「絲綢之路經濟帶」，一路是海上的「21 世紀海上絲綢之路」。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}, {"id": "g4-m8", "no": null, "c": "e7", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "中歐班列從新疆出境後，最先進入哪一個地區？", "o": ["南亞", "中亞", "東南亞", "東北亞"], "a": 1, "e": "絲綢之路經濟帶由新疆往西，最先進入中亞，再通往歐洲。", "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": ""}], "extras": [{"id": "compare", "title": "易混淆比較", "html": "<h3>1. 中國四大經濟區特徵與發展對策比較表</h3><div class=\"tbl\"><table><thead><tr><th>經濟分區</th><th>涵蓋代表範圍</th><th>發展優勢</th><th>面臨困境與挑戰</th><th>政府核心發展策略與定位</th></tr></thead><tbody><tr><td><b>東部地區</b></td><td>東部沿海省市（江蘇、浙江、廣東、上海、北京等）</td><td>對外開放最早、對外交通便利（海運發達）、勞力充沛、工商業與高科技最發達</td><td>糧食、能源、礦產原料不足；工資與地價高漲</td><td><b>東部率先發展</b>：發展高科技與金融，將產業優勢擴散至其他區域（如上海洋山深水港）</td></tr><tr><td><b>中部地區</b></td><td>內陸過渡省分（山西、河南、湖北、湖南、安徽、江西等）</td><td>煤、鐵、石油、水力與農產豐富；勞工工資相對較低；具承東啟西交通樞紐地位</td><td>地處內陸，對外開放較晚，經濟發展程度不如東部</td><td><b>中部崛起</b>：承接東部轉移之製造業，打造現代交通物流與製造樞紐（如武漢）</td></tr><tr><td><b>東北地區</b></td><td>東北三省（遼寧、吉林、黑龍江）</td><td>早期煤、鐵、石油豐富，為中國傳統<b>重工業重心</b>（曾被譽為「中國的工業巨人」）</td><td>礦產資源枯竭、工廠設備老舊、人口外流與高齡化嚴重，轉為衰退的「鏽帶」</td><td><b>東北振興</b>：推動老舊工廠轉型，發展新興能源、汽車與觀光業，加強與俄羅斯跨界合作</td></tr><tr><td><b>西部地區</b></td><td>西部內陸省分（新疆、西藏、青海、四川、重慶等）</td><td>自然與能源資源豐富（煤、石油、天然氣、水電）；與多國接壤利於邊境貿易</td><td>地形崎嶇、深居內陸、氣候乾燥，對外交通不便，工商業基礎薄弱</td><td><b>西部大開發</b>：推動「西氣東輸」、「西電東送」，發展能源加工、綠洲農業與觀光</td></tr></tbody></table></div><h3>2. 「世界工廠」 vs. 「世界市場」角色對照表</h3><div class=\"tbl\"><table><thead><tr><th>比較項目</th><th>世界工廠（Made in China）</th><th>世界市場（Market in China）</th></tr></thead><tbody><tr><td><b>核心意涵</b></td><td>扮演全球主要的<b>生產與製造端</b></td><td>扮演全球重要的<b>消費與吸收端</b></td></tr><tr><td><b>發展優勢</b></td><td>勞工工資與土地成本低廉、基礎設施完善、產業供應鏈完整</td><td>人口眾多、國民收入與消費力逐年提高、中產階級快速增加</td></tr><tr><td><b>代表產業／現象</b></td><td>玩具、成衣、3C 組裝、代工製造業產品行銷世界各地</td><td>國際精品、外國連鎖餐飲、進口車、國內電子商務蓬勃發展</td></tr><tr><td><b>轉變驅動力</b></td><td>1978 年改革開放設立經濟特區，引進外資</td><td>經濟快速成長帶動所得上升，內需消費市場龐大</td></tr></tbody></table></div><h3>3. 「一帶一路」之「一帶」與「一路」對照表</h3><div class=\"tbl\"><table><thead><tr><th>項目</th><th>一帶（絲綢之路經濟帶）</th><th>一路（21 世紀海上絲綢之路）</th></tr></thead><tbody><tr><td><b>交通型態</b></td><td><b>陸路</b>交通（以鐵路、公路、油氣管線為主）</td><td><b>海路</b>交通（以海運船運、深水港口為主）</td></tr><tr><td><b>歷史意象淵源</b></td><td>承襲漢唐兩千年前的「張騫通西域」陸上絲綢之路</td><td>承襲明代「鄭和下西洋」的海上貿易航路</td></tr><tr><td><b>主要路徑走向</b></td><td>中國西北地區（新疆阿拉山口/霍爾果斯）\\(\\rightarrow\\) <b>中亞</b> \\(\\rightarrow\\) 西亞 \\(\\rightarrow\\) <b>歐洲</b></td><td>東南沿海港口（福州/泉州/廣州）\\(\\rightarrow\\) 南海 \\(\\rightarrow\\) <b>東南亞</b> \\(\\rightarrow\\) <b>南亞</b> \\(\\rightarrow\\) <b>非洲東岸</b> \\(\\rightarrow\\) <b>歐洲</b></td></tr><tr><td><b>代表性旗艦建設</b></td><td><b>中歐班列</b>（陸運貨運列車）、中巴經濟走廊管線</td><td>希臘皮雷埃夫斯港、斯里蘭卡漢班托塔港、肯亞蒙巴薩鐵路</td></tr></tbody></table></div>"}, {"id": "timeline", "title": "經濟發展歷程", "html": "<h3>當代中國經濟發展與對外開放歷程</h3><div class=\"tbl\"><table><thead><tr><th>年代時期</th><th>重大政策／歷史事件</th><th>經濟發展與空間結構演變特徵</th></tr></thead><tbody><tr><td><b>1978 年</b></td><td><b>中共十一屆三中全會：推行「改革開放」</b></td><td>結束計畫經濟體制，打破鎖國封閉，政策重心全面轉向經濟建設。</td></tr><tr><td><b>1980 年</b></td><td><b>設立首批 4 個經濟特區</b>（深圳、珠海、汕頭、廈門）</td><td>吸引外資與港澳臺僑資，發展勞力密集出口加工業，東南沿海率先起飛。</td></tr><tr><td><b>1988 年</b></td><td><b>增設海南經濟特區</b>（全省劃為特區）</td><td>擴大沿海開放範圍，使沿海特區增至 5 個。</td></tr><tr><td><b>2000 年前後</b></td><td><b>提出「西部大開發」；推進「中部崛起」與「東北振興」</b></td><td>因應沿海與內陸差距擴大，啟動四大經濟區區域協調政策，推動西氣東輸與西電東送。</td></tr><tr><td><b>2001 年</b></td><td><b>正式加入世界貿易組織（WTO）</b></td><td>大幅降低進口關稅，深化融入全球經貿體系，「世界工廠」格局確立。</td></tr><tr><td><b>2010 年</b></td><td><b>設立新疆「喀什經濟特區」</b></td><td>成為中國唯一的內陸邊境經濟特區，承擔面向中亞邊境貿易門戶任務。</td></tr><tr><td><b>2013 年</b></td><td><b>正式倡議提出「一帶一路」經濟戰略</b></td><td>拓展海外基礎設施投資、取得穩定能源供給、消化國內多餘工業產能。</td></tr><tr><td><b>2018 年</b></td><td><b>美中貿易戰全面爆發</b></td><td>美國加徵懲罰性關稅與科技禁運封鎖，促使外資與陸企分散產能，推動「中國加一」策略。</td></tr><tr><td><b>2020 年簽署／2022 年生效</b></td><td><b>簽署「區域全面經濟夥伴協定（RCEP）」</b></td><td>全球最大自由貿易協定正式運作，強化與東協、日、韓、澳、紐的經貿零關稅互惠。</td></tr></tbody></table></div>"}, {"id": "charts", "title": "圖表判讀", "html": "<h3>1. 《中國四大經濟區劃分與發展走勢圖》</h3><figure class=\"cimg\"><img src=\"img/g4-map-region.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>中國四大經濟區分布圖</figcaption></figure><p class=\"li\"><b>圖表名稱</b>：《中國四大經濟區分布地圖》及《四大經濟區農村居民收入／GDP 差異表》。</p><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">1. <b>東部地區</b>：沿海省分，對外交通最發達、吸納外資最多（外資占比逾 70%）、GDP 與人均收入最高。</p><p class=\"li sub\">2. <b>中部地區</b>：夾在東部與西部之間，是全國重要鐵路與水路交通中樞（如長江黃金水道、京廣高鐵）。</p><p class=\"li sub\">3. <b>東北地區</b>：黑吉遼三省，昔日重工業基地，近年面臨轉型挑戰。</p><p class=\"li sub\">4. <b>西部地區</b>：版圖最遼闊（占逾半面積），資源極豐但經濟指標最低，仰賴中央財政補貼與大型工程挹注。</p><p class=\"li\"><b>常見判讀方式</b>：題目常給出外資數量分布地圖（東部極密、西部幾乎空白），要求判斷是哪一政策所導致（改革開放率先開放沿海）；或給予四大區經濟數據表格，考各區對應代號。</p><h3>2. 《中國經濟特區分布圖》</h3><figure class=\"cimg\"><img src=\"img/g4-map-sez.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>中國經濟特區分布圖</figcaption></figure><p class=\"li\"><b>圖表名稱</b>：《中國經濟特區地理分布示意圖》。</p><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">1. <b>廣東省 3 個</b>：<b>深圳</b>（緊鄰香港）、<b>珠海</b>（緊鄰澳門）、<b>汕頭</b>（潮汕僑鄉）。</p><p class=\"li sub\">2. <b>福建省 1 個</b>：<b>廈門</b>（隔海遙望臺灣）。</p><p class=\"li sub\">3. <b>海南省 1 個</b>：<b>海南島</b>全島。</p><p class=\"li sub\">4. <b>新疆 1 個</b>：<b>喀什</b>（位於極西內陸，鄰近中亞各國，2010 年設立）。</p><p class=\"li\"><b>常見判讀方式</b>：在空白地圖上填代號；或題幹描述「唯一位於內陸、鄰近中亞發展邊境貿易的特區」，答案必選「喀什」。</p><h3>3. 《「一帶一路」海陸路線示意圖》</h3><figure class=\"cimg\"><img src=\"img/g4-map-belt.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>中國一帶一路路線示意圖</figcaption></figure><p class=\"li\"><b>圖表名稱</b>：《中國「一帶一路」戰略規劃走廊示意圖》。</p><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">1. <b>紅線（陸路：絲綢之路經濟帶）</b>：自西安出發，穿過甘肅河西走廊，由新疆阿拉山口／霍爾果斯出境，跨越<b>中亞五國</b>、西亞、俄羅斯，抵達歐洲（如德國杜伊斯堡）。</p><p class=\"li sub\">2. <b>綠/藍線（海路：21 世紀海上絲綢之路）</b>：自東南沿海（泉州/廣州/海口）出發，經<b>麻六甲海峽</b>，橫跨<b>印度洋</b>，停靠斯里蘭卡、非洲東岸肯亞，穿過紅海、蘇伊士運河，直達歐洲地中海（希臘皮雷埃夫斯港）。</p><p class=\"li sub\">3. <b>中巴經濟走廊</b>：由新疆直接向南通往巴基斯坦瓜達爾港，避開麻六甲海峽咽喉點。</p><p class=\"li\"><b>常見判讀方式</b>：問某條路線「未經過」哪一大洲（美洲、大洋洲通常不經過）；或陸上路線出境後最先進入哪一區域（答：中亞）。</p><h3>4. 《中國歷年三級產業結構變遷折線圖》</h3><figure class=\"cimg\"><img src=\"img/g4-map-ind.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>中國三級產業產值比例統計圖</figcaption></figure><p class=\"li\"><b>圖表名稱</b>：《中國三級產業就業人口與產值比例變化圖》。</p><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">1. <b>第一級產業（農業）</b>：從早期就業與產值最高，呈直線持續下滑（產值跌破 10%，就業降至約 20% 多）。</p><p class=\"li sub\">2. <b>第二級產業（工業）</b>：長年居於主導（約 30%～40% 間震盪）。</p><p class=\"li sub\">3. <b>第三級產業（服務業）</b>：自 1980 年代穩定攀升，至 2015 年後產值正式超越第二級產業，成為產值占比最高之產業（逾 50%）。</p><p class=\"li\"><b>常見判讀方式</b>：根據甲、乙、丙三條曲線之起伏，要求依序判斷第一、第二、第三級產業；或詢問「現代化國家產業發展的必然趨勢」（第一級下降，第三級躍居最高）。</p>"}, {"id": "tips", "title": "口訣與防錯", "html": "<h3>考試核心防陷阱口訣</h3><div class=\"poem\"><b>「改革開放起東南，五大特區外資連；</b></div><div class=\"poem\"><b>唯有喀什在內陸，面向中亞邊境牽；</b></div><div class=\"poem\"><b>北方重工煤鐵油，南方輕工少礦產；</b></div><div class=\"poem\"><b>率先發展東沿海，中部崛起樞紐建；</b></div><div class=\"poem\"><b>振興東北老工業，西部開發油氣牽；</b></div><div class=\"poem\"><b>一帶一路通亞歐，債務主權起波瀾；</b></div><div class=\"poem\"><b>工資高漲美中戰，轉型自研不懼難。」</b></div><p class=\"li\"><b>防錯關鍵 1（經濟特區的位置與成立時間絕不混淆）</b>：</p><p class=\"li sub\">• 1980 年首批 4 個：<b>深圳、珠海、汕頭、廈門</b>（均在東南沿海）。</p><p class=\"li sub\">• 1988 年第 5 個：<b>海南</b>。</p><p class=\"li sub\">• 2010 年新增第 6 個：<b>喀什</b>（位於新疆內陸，考邊境貿易、一帶核心時必考）。</p><p class=\"li\"><b>防錯關鍵 2（四大經濟區戰略名詞嚴格配對）</b>：</p><p class=\"li sub\">• 東部地區 \\(\\rightarrow\\) <b>「東部率先發展」</b></p><p class=\"li sub\">• 中部地區 \\(\\rightarrow\\) <b>「中部崛起」</b></p><p class=\"li sub\">• 東北地區 \\(\\rightarrow\\) <b>「東北振興」</b></p><p class=\"li sub\">• 西部地區 \\(\\rightarrow\\) <b>「西部大開發」</b></p><p class=\"li sub\">• 題目常張冠李戴（例如將「東北振興」說成「東北崛起」或配給中部），請務必精準配對。</p><p class=\"li\"><b>防錯關鍵 3（「一帶」與「一路」的陸海方向辨析）</b>：</p><p class=\"li sub\">• <b>「一帶」是陸路</b>（絲綢之路經濟帶，通往中亞、歐洲）。</p><p class=\"li sub\">• <b>「一路」是海路</b>（21 世紀海上絲綢之路，經南海、印度洋通往非洲、歐洲）。</p><p class=\"li sub\">• 口訣記法：「帶字像皮帶在地上延伸（陸路），路字像海路巡航（海路）」。</p><p class=\"li\"><b>防錯關鍵 4（世界工廠 vs. 世界市場的主客體區分）</b>：</p><p class=\"li sub\">• 看到「廉價勞工、外銷歐美、製造玩具成衣、產值世界第一」\\(\\rightarrow\\) <b>世界工廠</b>。</p><p class=\"li sub\">• 看到「14 億消費人口、吸引精品進駐、電商熱絡、購買力強」\\(\\rightarrow\\) <b>世界市場</b>。</p><p class=\"li\"><b>防錯關鍵 5（美中貿易戰的本質是科技與關稅，非傳統領土戰爭）</b>：</p><p class=\"li sub\">• 美中衝突的主要手段是「<b>加徵商品關稅</b>」與「<b>高科技關鍵零組件（晶片）限制出口</b>」，造成外資企業分散投資至東南亞或印度（供應鏈重組）。</p>"}]});
